INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b18f20-e709-4ec9-b9d5-0b479ed6958e', '謝人送鯽魚鱠', '謝人送鯽鱼鱠', '08b14256-c564-4489-be33-927205119c81', '唐', '["君家一筯萬錢𢬵，分我銀絲侑客歡。","芳餌得來珍丙穴，金刀落處照辛盤。","腹空羞迫詩肩瘦，鱗活能生酒面寒。","玉手行廚如許巧，說教魚婢學應難。","（影印本《詩淵》第一冊第一一三頁）。"]', '["君家一筯万錢𢬵，分我銀絲侑客歡。","芳餌得来珍丙穴，金刀落处照辛盤。","腹空羞迫诗肩瘦，鱗活能生酒面寒。","玉手行廚如許巧，说教鱼婢学應难。","（影印本《诗淵》第一冊第一一三頁）。"]', '诗', 'shi', '', NULL, '謝人送鯽魚鱠 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('703dafdf-761a-4cc8-a12a-d363fc468ab5', '謝人送粽', '謝人送粽', '08b14256-c564-4489-be33-927205119c81', '唐', '["來時三月春猶在，到日端陽節又臨。","珍重主人意勤腆，滿槃角黍細包金。","（同前第一五六頁）。"]', '["来时三月春猶在，到日端陽節又臨。","珍重主人意勤腆，满槃角黍細包金。","（同前第一五六頁）。"]', '诗', 'shi', '', NULL, '謝人送粽 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9a79ca-3381-4318-b8aa-582cd13d0686', '別薛柳二員外', '別薛柳二員外', '08b14256-c564-4489-be33-927205119c81', '唐', '["江上月明胡雁過，淮南木落楚山多。","（《千載佳句》卷上《四時部·暮秋》）。"]', '["江上月明胡雁過，淮南木落楚山多。","（《千載佳句》卷上《四时部·暮秋》）。"]', '诗', 'shi', '', NULL, '別薛柳二員外 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84db1bf0-0201-4d06-b77f-541a5fae140e', '太原寒食觀仗上嚴司空', '太原寒食观仗上嚴司空', '08b14256-c564-4489-be33-927205119c81', '唐', '["天倚王師靜沙漠，年年寒食幷州樂。","珠華相壓駕重（下缺。","見上海圖書館藏明抄本《古今歲時雜詠》卷十一，末注：「以下古本缺二頁。","」《四庫全書》本無。","）。"]', '["天倚王師静沙漠，年年寒食幷州乐。","珠华相壓駕重（下缺。","见上海圖书館藏明抄本《古今歲时杂詠》卷十一，末注：「以下古本缺二頁。","」《四庫全书》本無。","）。"]', '诗', 'shi', '', NULL, '太原寒食觀仗上嚴司空 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b343abd3-e591-4021-a017-22f95d9c85c1', '贈盧洺州', '贈盧洺州', '08b14256-c564-4489-be33-927205119c81', '唐', '["三刀夢益州，一箭取遼城。","（見《白氏長慶集》卷十五《贈楊秘書巨源》自注）（按：《全唐詩》卷三三三收此二句，缺題，係源出《唐詩紀事》卷三五，今重錄之。","）。"]', '["三刀梦益州，一箭取遼城。","（见《白氏长慶集》卷十五《贈楊秘书巨源》自注）（按：《全唐诗》卷三三三收此二句，缺題，係源出《唐诗紀事》卷三五，今重錄之。","）。"]', '诗', 'shi', '', NULL, '贈盧洺州 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4bc504-daaa-49bf-bd5a-e05cc6c33136', '句', '句', '08b14256-c564-4489-be33-927205119c81', '唐', '["思出秦雲外，恩生漢水東。","（《輿地紀勝》卷八二《襄陽府》）。"]', '["思出秦云外，恩生漢水东。","（《輿地紀勝》卷八二《襄陽府》）。"]', '诗', 'shi', '', NULL, '句 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ebac523-db9f-44a0-8b91-e07aa17940ce', '秪（疑當作「抵」）剡', '秪（疑當作「抵」）剡', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["秋渚涵容碧，秋水刷眼青。","排頭烟樹老，撲面水風腥。","上瀨復下瀨，長亭仍短亭。","夜船明月好，客夢滿流螢。","（《記纂淵海》卷九）。"]', '["秋渚涵容碧，秋水刷眼青。","排头烟樹老，撲面水风腥。","上瀨复下瀨，长亭仍短亭。","夜船明月好，客梦满流螢。","（《記纂淵海》卷九）。"]', '诗', 'shi', '', NULL, '秪（疑當作「抵」）剡 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4283fcf-ab19-4ef0-a7c9-254c8cc70d51', '又', '又', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["船撑鑑湖月，路指沃洲雲。","（同前）。"]', '["船撑鑑湖月，路指沃洲云。","（同前）。"]', '诗', 'shi', '', NULL, '又 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf6787ee-1b9f-44d9-b2de-3d369f2f3f38', '句', '句', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["緣崖踏石層。","（見李壁《王荆文公詩箋注》卷三十《次韻吳季野題岳上人澄心亭》引）。"]', '["緣崖踏石層。","（见李壁《王荆文公诗箋注》卷三十《次韻吳季野題岳上人澄心亭》引）。"]', '诗', 'shi', '', NULL, '句 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9933a8ea-a39c-4b88-9d62-3a6b08acfd96', '曜日頌', '曜日頌', 'ff3b1d12-1f51-4573-8a97-d642927c131f', '唐', '["遍身烘爛更何人？臥棘森森一智真。","爲報你來須體妙，時中不擬宛然新。","（《祖堂集》卷四）。"]', '["遍身烘爛更何人？臥棘森森一智真。","爲報你来須體妙，时中不擬宛然新。","（《祖堂集》卷四）。"]', '诗', 'shi', '', NULL, '曜日頌 惟儼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62adf161-bdc4-4fc7-9637-9087d4376266', '李獨攜酒見訪', '李独携酒见訪', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["曉齋獨坐霜景寒，草堂逸士來相干。","風神左峭心意濶。","自言山中新醖熟，手挈一壺兼一軸。","果然文字稱儀容，已覺建安風彩俗。","嗟予潦倒身無成，偶因章句生浮名。","就中憐愛李景儉，酒狂大語欺奴兵。","老夫昔逐巴江岸，唱得《竹枝》腸欲斷。","爲君試發一聲看，九派煙霞愁漫漫。","（影印本《詩淵》第一冊一三一頁）。"]', '["晓斋独坐霜景寒，草堂逸士来相干。","风神左峭心意濶。","自言山中新醖熟，手挈一壺兼一軸。","果然文字稱儀容，已覺建安风彩俗。","嗟予潦倒身無成，偶因章句生浮名。","就中怜愛李景儉，酒狂大語欺奴兵。","老夫昔逐巴江岸，唱得《竹枝》腸欲斷。","爲君試發一声看，九派煙霞愁漫漫。","（影印本《诗淵》第一冊一三一頁）。"]', '诗', 'shi', '', NULL, '李獨攜酒見訪 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa1fa68-ce29-40ed-9fc5-291ad34d02c0', '贈蘇小', '贈蘇小', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["地人仙人家洛浦，聞道新年年十五。","巧轉明眸雙劍連，開粧一面千花吐。","流蘇帳，雲母屏，碧羅作卷花亭亭。","崑崙阿母暗鈎引，東海麻姑投姓名。","梭能織詩箏解語，鴛鴦難稱煙波侶。","偶逢曼倩巧言詞，不覺投花忽相許。","自言夫婿心不骨，黃金買笑輕侯王。","掌中看舞腰欲斷，暗裏聽歌愁滿堂。","莫學爲雲去無跡，巫山高高接天碧。","（同前第五五一頁）。"]', '["地人仙人家洛浦，闻道新年年十五。","巧轉明眸雙劍連，开粧一面千花吐。","流蘇帳，云母屏，碧羅作卷花亭亭。","崑崙阿母暗鈎引，东海麻姑投姓名。","梭能织诗箏解語，鴛鴦难稱煙波侶。","偶逢曼倩巧言词，不覺投花忽相許。","自言夫婿心不骨，黄金買笑轻侯王。","掌中看舞腰欲斷，暗裏听歌愁满堂。","莫学爲云去無跡，巫山高高接天碧。","（同前第五五一頁）。"]', '诗', 'shi', '', NULL, '贈蘇小 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1401f2ab-6fd5-40ac-bc0d-2a74585423be', '商州（題擬）', '商州（題擬）', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["宮址蔓生草，洞門低枕泉。","廢興人目擊，何處是神仙？","（《記纂淵海》卷二四）。"]', '["宮址蔓生草，洞门低枕泉。","廢兴人目擊，何处是神仙？","（《記纂淵海》卷二四）。"]', '诗', 'shi', '', NULL, '商州（題擬） 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c8f722-fade-4c44-a264-5e4dcf7860bd', '遊棲巖寺', '游棲巖寺', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["晚上梯延洞，通宵興莫窮。","高明千嶂月，清爽一巖風。","坐久衣衫潤，吟餘物象空。","舉頭星可摘，疑在廣寒宮。","（見《古今圖書集成·山川典》卷三五《中條山部》）。"]', '["晚上梯延洞，通宵兴莫窮。","高明千嶂月，清爽一巖风。","坐久衣衫潤，吟餘物象空。","舉头星可摘，疑在廣寒宮。","（见《古今圖书集成·山川典》卷三五《中條山部》）。"]', '诗', 'shi', '', NULL, '遊棲巖寺 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ce17904-ffc5-43ce-9e03-5b68c86f504a', '詠諸葛亮（題擬）', '詠諸葛亮（題擬）', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["草廬龍舊臥，花府鳳曾棲。","（見《輿地紀勝》卷八二《襄陽府》）。"]', '["草廬龙旧臥，花府鳳曾棲。","（见《輿地紀勝》卷八二《襄陽府》）。"]', '诗', 'shi', '', NULL, '詠諸葛亮（題擬） 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a00696-d734-481c-95bf-5a7325306553', '小庭水植率爾成詩', '小庭水植率爾成诗', 'e986399b-f711-4d2d-ac33-53527b250845', '唐', '["泓然一缶水，下與㘭堂接。","青菰八九枝，圓荷四五葉。","動搖香風至，顧盼野心愜。","行可採芙蓉，長江詎云涉。","（見錢仲聯《韓昌黎詩繫年集釋》卷九《奉和錢七兄曹長盆池所植》附）（按：宋方崧卿《韓集舉正》卷三云：「錢徽也。","唐本具錢詩於前。","」）。"]', '["泓然一缶水，下與㘭堂接。","青菰八九枝，圓荷四五葉。","动搖香风至，顧盼野心愜。","行可採芙蓉，长江詎云涉。","（见錢仲聯《韓昌黎诗繫年集釋》卷九《奉和錢七兄曹长盆池所植》附）（按：宋方崧卿《韓集舉正》卷三云：「錢徽也。","唐本具錢诗於前。","」）。"]', '诗', 'shi', '', NULL, '小庭水植率爾成詩 錢徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ce1d75-a527-47c6-9d68-071249ebf061', '同樂天登青龍寺上方望藍田山絕句（題擬）', '同乐天登青龙寺上方望藍田山絕句（題擬）', 'e986399b-f711-4d2d-ac33-53527b250845', '唐', '["偶來上寺因高望，松雪分明見舊山。","（見《白氏長慶集》卷十一《登龍昌上寺望江南山懷錢舍人》自注引）。"]', '["偶来上寺因高望，松雪分明见旧山。","（见《白氏长慶集》卷十一《登龙昌上寺望江南山懷錢舍人》自注引）。"]', '诗', 'shi', '', NULL, '同樂天登青龍寺上方望藍田山絕句（題擬） 錢徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44edf6d6-1339-4b32-ad55-c3c1ccbdbba4', '題從生假山', '題從生假山', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["宅相多能好自持，愛山攢石倚庭陲。","銅梁公阜□□□，□□□□□□□。","（見北京圖書館藏《分門纂類唐歌詩》宋刻殘本，轉錄自張篷舟《薛濤詩箋·後記》。","《宛委別藏》本將此詩刪棄。","）。"]', '["宅相多能好自持，愛山攢石倚庭陲。","銅梁公阜□□□，□□□□□□□。","（见北京圖书館藏《分门纂類唐歌诗》宋刻殘本，轉錄自張篷舟《薛濤诗箋·後記》。","《宛委別藏》本將此诗刪棄。","）。"]', '诗', 'shi', '', NULL, '題從生假山 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a9344c-5075-4057-992b-1bf234c877e5', '登石傘峰', '登石傘峰', '68dcad37-4ab6-4d78-ae3a-6697b54b4641', '唐', '["夙志慕遐嶠，偶時叨撫封。","幸茲秋成候，得與心期從。","宛在洲渚外，稍躋林嶺重。","紫垣感嘉惠，丹壑暢幽蹤。","之子綽有裕，結廬枕前峰。","亭臺互虧蔽，物象分輕濃。","玉傘踐危石，苔枝棲古松。","登攀逐羣彥，息偃慙衰容。","閶闔如可接，靈仙疑暫逢。","海帆去的的，霜雁來噰噰。","赫奕護軍重，導迎裨將恭。","迴舟遲新月，鼙鼓迎疏鐘。","（見《會稽掇英總集》卷四）。"]', '["夙志慕遐嶠，偶时叨撫封。","幸茲秋成候，得與心期從。","宛在洲渚外，稍躋林嶺重。","紫垣感嘉惠，丹壑暢幽蹤。","之子綽有裕，結廬枕前峰。","亭台互虧蔽，物象分轻濃。","玉傘踐危石，苔枝棲古松。","登攀逐羣彥，息偃慙衰容。","閶闔如可接，靈仙疑暫逢。","海帆去的的，霜雁来噰噰。","赫奕護軍重，導迎裨將恭。","迴舟遲新月，鼙鼓迎疏鐘。","（见《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登石傘峰 楊於陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d2669a-f307-40dd-93e3-bb1a607c6fde', '習家池大堤詩（題擬）', '習家池大堤诗（題擬）', '68dcad37-4ab6-4d78-ae3a-6697b54b4641', '唐', '["習氏蹤誰寄，羊氏道可躋。","（見《輿地紀勝》卷八二《襄陽府》）。"]', '["習氏蹤誰寄，羊氏道可躋。","（见《輿地紀勝》卷八二《襄陽府》）。"]', '诗', 'shi', '', NULL, '習家池大堤詩（題擬） 楊於陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5e9ee9-2aad-4632-aacc-96ff702ef0b7', '句', '句', '68dcad37-4ab6-4d78-ae3a-6697b54b4641', '唐', '["雲歛荆門近，江平峴首低。","（《記纂淵海》卷十二）（按：此二句與前「習氏」二句疑出同一首詩。","）。"]', '["云歛荆门近，江平峴首低。","（《記纂淵海》卷十二）（按：此二句與前「習氏」二句疑出同一首诗。","）。"]', '诗', 'shi', '', NULL, '句 楊於陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145b3d1e-c28e-4e7b-975f-e68410985198', '詠陀羅山', '詠陀羅山', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鑿開混沌露元氣，散布森羅彌梵天。","雲外無時不閒在，樓居何處得超然。","（《記纂淵海》卷二三）。"]', '["鑿开混沌露元氣，散布森羅彌梵天。","云外無时不閒在，楼居何处得超然。","（《記纂淵海》卷二三）。"]', '诗', 'shi', '', NULL, '詠陀羅山 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9a2809-eb92-46db-bdea-5c6071efe4f1', '夢好梨花歌', '梦好梨花歌', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["薄薄落落霧（別本作「路」）不分，夢中喚作梨花雲。","瑤池水光蓬萊雪，青葉白花相次發。","不從地上生枝柯，合在天頭遶宮闕。","天風微微吹不破，白艷却愁香涴露。","玉房綵女齊看來，錯認仙山鶴飛過。","落花散粉飄滿空，梨花顏色同不同。","眼穿臂短取不得，取得亦如從夢中。","無人爲我解此夢，梨花一曲心珍重。","（見宋張邦基《墨莊漫錄》卷六）（按：《墨莊漫錄》：「東坡作梅花詞云：『高情已逐曉雲空，不與梨花同夢。","』注云：『唐王建有《夢看梨花雲詩》。","』予求王建詩，行世甚少，唯印行本一卷，乃無此篇。","後得之於晏元獻《類要》中。","後又得建全集七卷，乃得全篇，題云《夢好梨花歌》。","〖詩略〗或誤傳爲王昌齡，非也。","」另參本書卷九王昌齡詩附按。","）。"]', '["薄薄落落霧（別本作「路」）不分，梦中喚作梨花云。","瑤池水光蓬萊雪，青葉白花相次發。","不從地上生枝柯，合在天头遶宮闕。","天风微微吹不破，白艷却愁香涴露。","玉房綵女齊看来，錯認仙山鹤飞過。","落花散粉飄满空，梨花顏色同不同。","眼穿臂短取不得，取得亦如從梦中。","無人爲我解此梦，梨花一曲心珍重。","（见宋張邦基《墨莊漫錄》卷六）（按：《墨莊漫錄》：「东坡作梅花词云：『高情已逐晓云空，不與梨花同梦。","』注云：『唐王建有《梦看梨花云诗》。","』予求王建诗，行世甚少，唯印行本一卷，乃無此篇。","後得之於晏元獻《類要》中。","後又得建全集七卷，乃得全篇，題云《梦好梨花歌》。","〖诗略〗或誤傳爲王昌齡，非也。","」另參本书卷九王昌齡诗附按。","）。"]', '诗', 'shi', '', NULL, '夢好梨花歌 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d4ab9ea-cbda-4e59-a334-511bb7bc4703', '讚碎金', '讚碎金', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一軸零書則（斯六一九卷作「時」）未多，要來不得（斯六一九卷作「問」）那人何？","從頭至尾無閑字，勝看真（斯六一九卷作「珍」）珠一百螺。","（見斯六二○四卷《字寶碎金》末附，署「吏部郎中王建」。","斯六一九卷署「王建郎中」。","）。"]', '["一軸零书則（斯六一九卷作「时」）未多，要来不得（斯六一九卷作「问」）那人何？","從头至尾無闲字，勝看真（斯六一九卷作「珍」）珠一百螺。","（见斯六二○四卷《字寶碎金》末附，署「吏部郎中王建」。","斯六一九卷署「王建郎中」。","）。"]', '诗', 'shi', '', NULL, '讚碎金 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44a084d-e344-44df-b389-dc787b0c3dcb', '靈隱寺', '靈隐寺', '96efda6a-f9ff-4f06-91ed-73136fa4a744', '唐', '["長松晉家樹，絕頂客兒亭。","（見《淳祐臨安志》殘本卷八）。"]', '["长松晉家樹，絕頂客兒亭。","（见《淳祐臨安志》殘本卷八）。"]', '诗', 'shi', '', NULL, '靈隱寺 盧元輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e59a5e-22ff-4e8b-9dac-6abe0dc89622', '夢遊仙賦附詩 一', '梦游仙賦附诗 一', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["白日低兮春塘滿，紅華芳兮草芽短。","菱結帶兮荇含絲，設遨遊兮遵佳期。"]', '["白日低兮春塘满，紅华芳兮草芽短。","菱結带兮荇含絲，設遨游兮遵佳期。"]', '诗', 'shi', '', NULL, '夢遊仙賦附詩 一 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c0748a-1f6e-4450-abb6-1c0eb6b978b6', '夢遊仙賦附詩 二', '梦游仙賦附诗 二', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["穠光醉兮，昏緜緜焉。","與久樂萬年春，留連兮其未央。","（均見《沈下賢文集》卷一）。"]', '["穠光醉兮，昏緜緜焉。","與久乐万年春，留連兮其未央。","（均见《沈下賢文集》卷一）。"]', '诗', 'shi', '', NULL, '夢遊仙賦附詩 二 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02bdd88e-91cf-4845-a993-23dffd5fd146', '湘中怨解載鄭生愁吟', '湘中怨解載鄭生愁吟', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["情無垠兮蕩洋洋，懷佳期兮屬三湘。","（見《沈下賢文集》卷二）。"]', '["情無垠兮蕩洋洋，懷佳期兮屬三湘。","（见《沈下賢文集》卷二）。"]', '诗', 'shi', '', NULL, '湘中怨解載鄭生愁吟 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1137cf3c-0588-433a-8e26-2dd4e30a0b93', '觀元相公花飲（一作「宴」）', '观元相公花饮（一作「宴」）', 'cbaa69c5-d042-4b71-a70f-447b72a0db3e', '唐', '["尺八調悲銀字管，琵琶聲送紫檀槽。","（《千載佳句》卷下《宴喜部·管絃》）（按：此詩署「僧直言」。","同書卷上作「僧直玄」，《和漢朗詠集》卷下作「僧亘玄」，《全唐詩逸》卷中作「真元」。","未詳孰是。","）。"]', '["尺八調悲銀字管，琵琶声送紫檀槽。","（《千載佳句》卷下《宴喜部·管絃》）（按：此诗署「僧直言」。","同书卷上作「僧直玄」，《和漢朗詠集》卷下作「僧亘玄」，《全唐诗逸》卷中作「真元」。","未詳孰是。","）。"]', '诗', 'shi', '', NULL, '觀元相公花飲（一作「宴」） 直言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcf0184-5551-4707-8e56-a7599c9dad49', '再酬復言和誇州宅', '再酬复言和誇州宅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["會稽天下本無儔，任取蘇杭作輩流。","斷髮儀刑千古學，奔濤（一作「騰」）翻動萬人憂。","石緣類鬼名羅剎，寺爲因墳號虎丘。","莫著詩章遠牽引，由來北郡似南州。","（見宋孔延之編《會稽掇英總集》卷一）。"]', '["會稽天下本無儔，任取蘇杭作輩流。","斷髮儀刑千古学，奔濤（一作「腾」）翻动万人憂。","石緣類鬼名羅剎，寺爲因墳號虎丘。","莫著诗章远牽引，由来北郡似南州。","（见宋孔延之編《會稽掇英總集》卷一）。"]', '诗', 'shi', '', NULL, '再酬復言和誇州宅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b02d63-237c-476b-98bc-a1de6f2c2651', '遊雲門', '游云门', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["遙泉滴滴度更遲，秋夜霜天入竹扉。","明月自隨山影去，清風長送白雲歸。","（同前書卷六）。"]', '["遙泉滴滴度更遲，秋夜霜天入竹扉。","明月自隨山影去，清风长送白云归。","（同前书卷六）。"]', '诗', 'shi', '', NULL, '遊雲門 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b3f154-3006-4ae8-9d7a-c9c19c5785ae', '題法華山天衣寺', '題法华山天衣寺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["馬踏紅塵古塞平，出門誰不爲功名。","到頭爭似棲禪客，林下無言過一生。","（同前書卷八）。"]', '["马踏紅塵古塞平，出门誰不爲功名。","到头爭似棲禪客，林下無言過一生。","（同前书卷八）。"]', '诗', 'shi', '', NULL, '題法華山天衣寺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7193680-7c8b-4114-9f53-94679d21998d', '拜禹廟', '拜禹廟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["恢能咨岳日，悲慕羽山秋。","父陷功仍繼，君名禮不讎。","洪水襄陵後，玄圭菲食由。","已甘魚父子，翻荷粒咽喉。","古廟蒼煙冷，寒亭翠柏稠。","馬泥真骨動，龍畫活睛留。","祀典稽千聖，孫謀絕一丘。","道雖污世載，恩豈酌沈浮。","洞穴探常近，圖書即可求。","德崇人不惰，風在俗斯柔。","茭色湖光上，泉聲雨脚收。","歌詩呈志義，簫鼓凟清猷。","史亦明勳最，時方怒校酋。","還希四載術，將以拯虔劉。","（同前）（按：以上四首，卞孝萱《元稹年譜》、冀勤校《元稹集》均出揭出。","）。"]', '["恢能咨岳日，悲慕羽山秋。","父陷功仍繼，君名禮不讎。","洪水襄陵後，玄圭菲食由。","已甘鱼父子，翻荷粒咽喉。","古廟蒼煙冷，寒亭翠柏稠。","马泥真骨动，龙畫活睛留。","祀典稽千聖，孫謀絕一丘。","道雖污世載，恩豈酌沈浮。","洞穴探常近，圖书即可求。","德崇人不惰，风在俗斯柔。","茭色湖光上，泉声雨脚收。","歌诗呈志義，簫鼓凟清猷。","史亦明勳最，时方怒校酋。","還希四載術，將以拯虔劉。","（同前）（按：以上四首，卞孝萱《元稹年譜》、冀勤校《元稹集》均出揭出。","）。"]', '诗', 'shi', '', NULL, '拜禹廟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34cf8a1c-d01d-4cee-8931-3190ef964898', '奉使往蜀路傍見山花吟寄樂天（題擬） 一', '奉使往蜀路傍见山花吟寄乐天（題擬） 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["深紅山木艷丹雲，路遠無由摘寄君。","恰似牡丹如許大，淺深看取石榴裙。"]', '["深紅山木艷丹云，路远無由摘寄君。","恰似牡丹如許大，淺深看取石榴裙。"]', '诗', 'shi', '', NULL, '奉使往蜀路傍見山花吟寄樂天（題擬） 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5303babc-7d62-4841-bf82-5a0754cccf6b', '奉使往蜀路傍見山花吟寄樂天（題擬） 二', '奉使往蜀路傍见山花吟寄乐天（題擬） 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["向前已說深紅木，更有輕紅說向君。","深葉淺花何所似，薄妝愁坐碧羅裙。","（人民文學出版社刊周本淳校點本《詩話總龜》卷二七引《唐賢抒情》）。"]', '["向前已说深紅木，更有轻紅说向君。","深葉淺花何所似，薄妝愁坐碧羅裙。","（人民文学出版社刊周本淳校点本《诗話總龟》卷二七引《唐賢抒情》）。"]', '诗', 'shi', '', NULL, '奉使往蜀路傍見山花吟寄樂天（題擬） 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1d9337-94a4-47bd-88e7-a9e871839c3c', '封書', '封书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["每書題作上都字，悵望關東無限情。","寂寞此心新雨後，槐花高樹晚蟬聲。","（《千載佳句》卷上《四時部·早秋》）。"]', '["每书題作上都字，悵望关东無限情。","寂寞此心新雨後，槐花高樹晚蟬声。","（《千載佳句》卷上《四时部·早秋》）。"]', '诗', 'shi', '', NULL, '封書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('925022af-7405-45d7-8395-55a65e1d0e58', '春詞', '春词', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一雙玉手十三弦，移柱高低落鬢邊。","即問向來彈了曲，羞人不道《想夫憐》。","（《千載佳句》卷下《宴喜部·箏》）。"]', '["一雙玉手十三弦，移柱高低落鬢邊。","即问向来彈了曲，羞人不道《想夫怜》。","（《千載佳句》卷下《宴喜部·箏》）。"]', '诗', 'shi', '', NULL, '春詞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8ac46f-d5aa-4ae9-9636-78fd0166eb25', '詠鶯', '詠鶯', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天下金衣侶，還能貺草萊。","風流晉王謝，言語漢鄒枚。","公等久安在，今絕何處來？","山禽正嘈雜，慰我日徘徊。","（《夢梁錄》卷十八）。"]', '["天下金衣侶，還能貺草萊。","风流晉王謝，言語漢鄒枚。","公等久安在，今絕何处来？","山禽正嘈杂，慰我日徘徊。","（《梦梁錄》卷十八）。"]', '诗', 'shi', '', NULL, '詠鶯 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000e5022-c53c-43d4-8020-175679690fb1', '石榴花', '石榴花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寥落山榴深映葉，紅霞淺帶碧霄雲。","麴塵枝下年年見，別似衣裳不似裙。","（《永樂大典》卷八二一引《甕牖閑評》引）（〖1〗以上二詩據《古籍整理出版情況簡報》一六六期刊冀勤同志《元稹佚詩續輯》錄出。","）。"]', '["寥落山榴深映葉，紅霞淺带碧霄云。","麴塵枝下年年见，別似衣裳不似裙。","（《永乐大典》卷八二一引《甕牖闲評》引）（〖1〗以上二诗據《古籍整理出版情況簡報》一六六期刊冀勤同志《元稹佚诗續輯》錄出。","）。"]', '诗', 'shi', '', NULL, '石榴花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b60f5792-b691-4a6b-a858-f9db017291c7', '送晏秀才歸江陵', '送晏秀才归江陵', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["長堤纖草河邊綠，近郭新鶯竹裏啼。","（《千載佳句》卷上《四時部·早春》）。"]', '["长堤纖草河邊綠，近郭新鶯竹裏啼。","（《千載佳句》卷上《四时部·早春》）。"]', '诗', 'shi', '', NULL, '送晏秀才歸江陵 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e3986e-e013-4360-a2d0-b95a4d00eb95', '早春書情', '早春书情', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["空城月落方知曉，淺水荷香始覺春。","（同前《四時部·春情》）。"]', '["空城月落方知晓，淺水荷香始覺春。","（同前《四时部·春情》）。"]', '诗', 'shi', '', NULL, '早春書情 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1b5863-c7bc-4bfe-bfa1-4d878f332865', '雨後書情', '雨後书情', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["溪上懶蒲藏釣艇，窗前新筍長漁竿。","（同前《四時部·暮春》）。"]', '["溪上懶蒲藏釣艇，窗前新筍长漁竿。","（同前《四时部·暮春》）。"]', '诗', 'shi', '', NULL, '雨後書情 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b575286-dab3-4ba9-a979-f72b771acf07', '雨後感懷', '雨後感懷', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雲際日光分萬井，煙消山色露千峰。","（同前《天象部·晴霽》）。"]', '["云際日光分万井，煙消山色露千峰。","（同前《天象部·晴霽》）。"]', '诗', 'shi', '', NULL, '雨後感懷 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb5ddde-02a7-492e-9b37-629ffcde1a3c', '雨後感情', '雨後感情', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["甕開白酒花間醉，簾卷青山雨後看。","（同前卷下《宴喜部·醉後》）（按：此詩與前錄之《雨後書情》疑爲一首詩。","）。"]', '["甕开白酒花间醉，簾卷青山雨後看。","（同前卷下《宴喜部·醉後》）（按：此诗與前錄之《雨後书情》疑爲一首诗。","）。"]', '诗', 'shi', '', NULL, '雨後感情 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0842ab65-f1c6-41a2-9f91-a0b1168fcf7f', '題李端', '題李端', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["新筍短松低曉露，晚花寒沼漾殘暉。","（同前卷上《人事部·文藻》）。"]', '["新筍短松低晓露，晚花寒沼漾殘暉。","（同前卷上《人事部·文藻》）。"]', '诗', 'shi', '', NULL, '題李端 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e5d2a9-3abe-40c5-bd48-3343af916848', '春情多', '春情多', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["白髮鏡中慚易老，青山江上幾迴春。","（同前《人事部·老》）。"]', '["白髮镜中慚易老，青山江上幾迴春。","（同前《人事部·老》）。"]', '诗', 'shi', '', NULL, '春情多 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9c7718-bad0-4ebe-a4bd-306ad4b3227f', '薔薇', '薔薇', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["千重密葉侵階綠，萬（一作「百」）朵閑花向日紅。","（同前卷下《草木部·薔薇》）。"]', '["千重密葉侵階綠，万（一作「百」）朵闲花向日紅。","（同前卷下《草木部·薔薇》）。"]', '诗', 'shi', '', NULL, '薔薇 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89047b80-db42-4d29-b823-ca3f7780fa74', '夜花', '夜花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["燈照露花何所似，館娃宮殿夜妝臺。","（同前《草木部·雜花》）。"]', '["灯照露花何所似，館娃宮殿夜妝台。","（同前《草木部·杂花》）。"]', '诗', 'shi', '', NULL, '夜花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516e1135-8047-4969-b70d-9f240964c3d6', '送故人歸府', '送故人归府', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["落日樽前添別思，碧潭灘上荻花秋。","（同前《離別部·餞別》）。"]', '["落日樽前添別思，碧潭灘上荻花秋。","（同前《離別部·餞別》）。"]', '诗', 'shi', '', NULL, '送故人歸府 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb8b5a7-63ea-4693-9769-4d0ed671bbfb', '送劉秀才歸江陵', '送劉秀才归江陵', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["花間祖席離人醉，水上歸帆落日行。","（同前）。"]', '["花间祖席離人醉，水上归帆落日行。","（同前）。"]', '诗', 'shi', '', NULL, '送劉秀才歸江陵 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('230de686-8d61-4b6d-a9e3-c67053c926bf', '送裴侍御', '送裴侍御', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["欲知別後思君處，看取湘江秋月明。","（同前《離別部·秋別》）。"]', '["欲知別後思君处，看取湘江秋月明。","（同前《離別部·秋別》）。"]', '诗', 'shi', '', NULL, '送裴侍御 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a233672c-06fe-4b8a-8011-859b0fe51b6f', '上西陵留別', '上西陵留別', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["□憂去國三千里，遙指江南一道雲。","（同前《離別部·留別》）。"]', '["□憂去国三千里，遙指江南一道云。","（同前《離別部·留別》）。"]', '诗', 'shi', '', NULL, '上西陵留別 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c385f3-273f-4911-be21-858da1840253', '旅舍感懷', '旅舍感懷', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["因依客路煙波上，迢遞鄉心夜夢中。","（同前《離別部·水行》）。"]', '["因依客路煙波上，迢遞乡心夜梦中。","（同前《離別部·水行》）。"]', '诗', 'shi', '', NULL, '旅舍感懷 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01241e5-e44e-4154-b0b7-93d290227409', '罷弊務思歸故國寄知友', '罷弊務思归故国寄知友', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["如今欲種韓康藥，未卜雲山第幾峰。","（同前《隱逸部·思隱》）。"]', '["如今欲種韓康藥，未卜云山第幾峰。","（同前《隐逸部·思隐》）。"]', '诗', 'shi', '', NULL, '罷弊務思歸故國寄知友 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ad7de2-5b33-470e-aaf5-8619811de3ee', '閉門即事', '閉门即事', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["數竿修竹衡門裏，一徑松杉落日中。","（同前《隱逸部·幽居》）。"]', '["數竿修竹衡门裏，一徑松杉落日中。","（同前《隐逸部·幽居》）。"]', '诗', 'shi', '', NULL, '閉門即事 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b10644-6242-4b94-b9e0-22bbbb469f6a', '題王右軍遺跡', '題王右軍遺跡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["生臥竹堂虛室白，逍遙松逕遠山青。","（同前）（按：《封書》、《春詞》及《送晏秀才歸江陵》以降各句，冀勤校點本《元稹集》均已據花房英樹《元稹研究》收錄。","今據王水照教授自日本携歸之東京大學圖書館藏森鷗外捐贈抄本《千載佳句》複印本校錄。","）。"]', '["生臥竹堂虛室白，逍遙松逕远山青。","（同前）（按：《封书》、《春词》及《送晏秀才归江陵》以降各句，冀勤校点本《元稹集》均已據花房英樹《元稹研究》收錄。","今據王水照教授自日本携归之东京大学圖书館藏森鷗外捐贈抄本《千載佳句》複印本校錄。","）。"]', '诗', 'shi', '', NULL, '題王右軍遺跡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a808e488-7f26-4c95-96a9-c006ac032e63', '題藍橋驛', '題藍橋驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江陵歸時逢春雪。","（見《白氏長慶集》卷十五《藍橋驛見元九詩》自注引）。"]', '["江陵归时逢春雪。","（见《白氏长慶集》卷十五《藍橋驛见元九诗》自注引）。"]', '诗', 'shi', '', NULL, '題藍橋驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc1df0a-fae1-41bb-99c0-a09cbd136da7', '宮詞', '宮词', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["外人不識承恩處，唯有羅衣染御香。","（見日藤原公任《倭漢朗詠集》卷下《妓女》）。"]', '["外人不識承恩处，唯有羅衣染御香。","（见日藤原公任《倭漢朗詠集》卷下《妓女》）。"]', '诗', 'shi', '', NULL, '宮詞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('babca013-8579-4067-9f9b-8721e5a33624', '詠李花', '詠李花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["葦綃開萬朶。","（見馮贄《雲仙雜記》卷七引《高隱外書》）。"]', '["葦綃开万朶。","（见馮贄《云仙杂記》卷七引《高隐外书》）。"]', '诗', 'shi', '', NULL, '詠李花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd17ee2-116b-415f-9b75-70d1f0bff257', '拗花（題擬）', '拗花（題擬）', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["試問酒旗歌板地，今朝誰是拗花人。","（見陶宗儀《南村輟耕錄》卷十二）。"]', '["試问酒旗歌板地，今朝誰是拗花人。","（见陶宗儀《南村輟耕錄》卷十二）。"]', '诗', 'shi', '', NULL, '拗花（題擬） 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2210687d-43ea-4b4f-943c-5ba4394f6ee6', '山茶花', '山茶花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["冷蜂寒蝶（一作「冷蝶寒蜂」）尚未來。","（見宋鄭元佐《朱淑真〈斷腸詩集〉注》卷二《春歸》、卷三《窗西桃花盛開》注引）。"]', '["冷蜂寒蝶（一作「冷蝶寒蜂」）尚未来。","（见宋鄭元佐《朱淑真〈斷腸诗集〉注》卷二《春归》、卷三《窗西桃花盛开》注引）。"]', '诗', 'shi', '', NULL, '山茶花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a466a56-a0ad-4e65-9b7d-9ea02b668efb', '崔徽歌 一', '崔徽歌 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["崔徽本不是娼家，教歌按舞娼家長。","使君知有不自由，坐在顯時立在掌。"]', '["崔徽本不是娼家，教歌按舞娼家长。","使君知有不自由，坐在显时立在掌。"]', '诗', 'shi', '', NULL, '崔徽歌 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eef3043-363b-46b9-8c6c-dc54353f5c53', '崔徽歌 二', '崔徽歌 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有客有客名丘夏，善寫儀容得艷姿。","爲徽持此寄敬中，以死報郎爲終始。","（以上見《綠窗新話》卷上）（按：《全唐詩》卷四二三收以上二節，有缺誤，又誤連作一首，今重錄。","）。"]', '["有客有客名丘夏，善寫儀容得艷姿。","爲徽持此寄敬中，以死報郎爲終始。","（以上见《綠窗新話》卷上）（按：《全唐诗》卷四二三收以上二節，有缺誤，又誤連作一首，今重錄。","）。"]', '诗', 'shi', '', NULL, '崔徽歌 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd36d087-f11b-4ff7-90cc-50bd413010f4', '崔徽歌 三', '崔徽歌 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["眼明正似琉璃瓶，心蕩秋水橫波清。","（見施元之等《注東坡先生詩》卷十五《百步洪》注引）。"]', '["眼明正似琉璃瓶，心蕩秋水橫波清。","（见施元之等《注东坡先生诗》卷十五《百步洪》注引）。"]', '诗', 'shi', '', NULL, '崔徽歌 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e506de-dbc8-46d0-9fda-2b661b028150', '崔徽歌 四', '崔徽歌 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吏感徽心關鎖開。","（見任淵《山谷詩注》卷九《出禮部試院王才元惠梅花三種皆妙絕戲答三首》注引）（按：以上五題皆據冀勤校《元稹集·外集》卷七《續補》一。","）。"]', '["吏感徽心关鎖开。","（见任淵《山谷诗注》卷九《出禮部試院王才元惠梅花三種皆妙絕戲答三首》注引）（按：以上五題皆據冀勤校《元稹集·外集》卷七《續補》一。","）。"]', '诗', 'shi', '', NULL, '崔徽歌 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e75660-2a43-4282-940e-d86084f29494', '崔徽歌 五', '崔徽歌 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鳳凰寶釵爲郎戴。","（見陳元龍《片玉集注》卷二《秋蘂香》注引元微之詩）。"]', '["鳳凰寶釵爲郎戴。","（见陳元龙《片玉集注》卷二《秋蘂香》注引元微之诗）。"]', '诗', 'shi', '', NULL, '崔徽歌 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fec5c61-1422-455b-9ff3-6a6e4c3cd13a', '崔徽歌 六', '崔徽歌 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["舞態低迷誤招拍。","（同前書卷八《蝶戀花》之二注引崔徽詩）。"]', '["舞態低迷誤招拍。","（同前书卷八《蝶戀花》之二注引崔徽诗）。"]', '诗', 'shi', '', NULL, '崔徽歌 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e575e7-1c74-4e86-b29d-66526f56ea22', '崔徽歌 七', '崔徽歌 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鳳釵亂折金鈿碎。","（同前書卷二《憶舊遊》注引元徽之詩）（按：以上三句，《元氏長慶集》不收，似皆《崔徽歌》佚文。","）。"]', '["鳳釵亂折金鈿碎。","（同前书卷二《憶旧游》注引元徽之诗）（按：以上三句，《元氏长慶集》不收，似皆《崔徽歌》佚文。","）。"]', '诗', 'shi', '', NULL, '崔徽歌 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f35303d7-2581-485e-be93-66803dcbb4ec', '和浙西李大夫晚下北固山喜松徑成陰悵然懷古偶題臨江亭', '和浙西李大夫晚下北固山喜松徑成陰悵然懷古偶題臨江亭', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自公鎮南徐，三換營門柳。","（《嘉定鎮江志》卷十四）（按：傅璇琮先生《李德裕年譜》寶曆元年譜錄出二句，詩題亦從傳說。","）。"]', '["自公鎮南徐，三換營门柳。","（《嘉定鎮江志》卷十四）（按：傅璇琮先生《李德裕年譜》寶曆元年譜錄出二句，诗題亦從傳说。","）。"]', '诗', 'shi', '', NULL, '和浙西李大夫晚下北固山喜松徑成陰悵然懷古偶題臨江亭 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16947d3c-6d33-4e1f-ae20-ad9501605642', '句', '句', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["無妙思帝里，不合厭杭州。","（俞文豹《吹劍三錄》。","此則亦從冀勤同志說）。"]', '["無妙思帝里，不合厭杭州。","（俞文豹《吹劍三錄》。","此則亦從冀勤同志说）。"]', '诗', 'shi', '', NULL, '句 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2718164-27ca-4bb8-bc8b-2f20f5ceed58', '詠廿四氣詩 立春正月節', '詠廿四氣诗 立春正月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春冬移律呂，天地換星霜。","間泮游魚躍，和風待柳芳。","早梅迎雨水，殘雪怯朝陽。","萬物含新意，同歡聖日長。"]', '["春冬移律呂，天地換星霜。","间泮游鱼躍，和风待柳芳。","早梅迎雨水，殘雪怯朝陽。","万物含新意，同歡聖日长。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 立春正月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6098ea5c-d715-44fe-9b40-7ec6d4761e42', '詠廿四氣詩 雨水正月中', '詠廿四氣诗 雨水正月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨水洗春容，平田已見龍。","祭魚盈浦嶼，歸雁□山峰。","雲色輕還重，風光淡又濃。","向春入二月，花色影重重。"]', '["雨水洗春容，平田已见龙。","祭鱼盈浦嶼，归雁□山峰。","云色轻還重，风光淡又濃。","向春入二月，花色影重重。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 雨水正月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a0457b2-c06c-4b05-9f99-84e81f2c64f3', '詠廿四氣詩 驚蟄二月節', '詠廿四氣诗 驚蟄二月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["陽氣初驚蟄，韶光大（一作「天」）地周。","桃花開蜀錦，鷹老化春（一作「爲」）鳩。","時候爭催迫，萌芽牙{丿爲丶}（一作「護」）矩修。","人間務生事，耕種滿田疇。","。"]', '["陽氣初驚蟄，韶光大（一作「天」）地周。","桃花开蜀錦，鷹老化春（一作「爲」）鳩。","时候爭催迫，萌芽牙{丿爲丶}（一作「護」）矩修。","人间務生事，耕種满田疇。","。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 驚蟄二月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a527c4-c502-43c9-9e83-7035c1ffaa2f', '詠廿四氣詩 春分二月中', '詠廿四氣诗 春分二月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["二氣莫交爭，春分雨處行。","雨來看電影，雲過聽雷聲。","山色連天碧，林花向日明。","樑間玄鳥語，欲似解人情。"]', '["二氣莫交爭，春分雨处行。","雨来看電影，云過听雷声。","山色連天碧，林花向日明。","樑间玄鸟語，欲似解人情。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 春分二月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bf8979-799a-4cc3-9895-26c6bed3bb87', '詠廿四氣詩 清明三月節', '詠廿四氣诗 清明三月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["清明來向晚，山淥正光華。","楊柳先飛絮，梧桐續放花。","鴽聲知化鼠，虹影指天涯。","已識風雲意，寧愁雨穀（一作「穀雨」）賒。"]', '["清明来向晚，山淥正光华。","楊柳先飞絮，梧桐續放花。","鴽声知化鼠，虹影指天涯。","已識风云意，寧愁雨穀（一作「穀雨」）賒。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 清明三月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ca5cb1-857a-4cb0-8682-0a9b6e2deba3', '詠廿四氣詩 穀雨春光曉', '詠廿四氣诗 穀雨春光晓', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["穀雨春光曉，山川黛色青。","葉間鳴戴勝，澤水長浮萍。","暖屋生蠶蟻，喧風引麥葶。","鳴鳩徒拂羽，信矣不堪聽。"]', '["穀雨春光晓，山川黛色青。","葉间鳴戴勝，澤水长浮萍。","暖屋生蠶蟻，喧风引麦葶。","鳴鳩徒拂羽，信矣不堪听。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 穀雨春光曉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741080f2-7dfb-40cb-8bf8-f336f3e05527', '詠廿四氣詩 立夏四月節', '詠廿四氣诗 立夏四月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["欲知春與夏，仲[呂]（侶）啓朱明。","蚯蚓誰教出，王苽自合生。","簾（一作「簇」）蠶呈蠒樣，林鳥哺雛聲。","漸覺雲峰好，徐徐帶雨行。"]', '["欲知春與夏，仲[呂]（侶）啓朱明。","蚯蚓誰教出，王苽自合生。","簾（一作「簇」）蠶呈蠒樣，林鸟哺雛声。","漸覺云峰好，徐徐带雨行。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 立夏四月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b774a770-4e4c-44ef-a330-3b1e34be457f', '詠廿四氣詩 小滿四月中', '詠廿四氣诗 小满四月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小滿氣全時，如何靡草衰。","田家私黍稷，方伯問蠶絲。","杏麥修鐮釤，錋苽{下爲爪}竪棘籬。","向來看苦菜，獨秀也何爲？","。"]', '["小满氣全时，如何靡草衰。","田家私黍稷，方伯问蠶絲。","杏麦修鐮釤，錋苽{下爲爪}竪棘籬。","向来看苦菜，独秀也何爲？","。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 小滿四月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b99676f3-9508-4056-a22b-f7f123a2721e', '詠廿四氣詩 芒種五月節', '詠廿四氣诗 芒種五月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["芒種看今日，螗螂應節生。","彤雲高下影，鷃鳥往來聲。","淥沼蓮花放，炎風暑雨情。","相逢問蠶麥，幸得稱人情。"]', '["芒種看今日，螗螂應節生。","彤云高下影，鷃鸟往来声。","淥沼蓮花放，炎风暑雨情。","相逢问蠶麦，幸得稱人情。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 芒種五月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21fc31a5-a1de-493c-98d6-5b0fe8b2c379', '詠廿四氣詩 夏至五月中', '詠廿四氣诗 夏至五月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["處處聞蟬響，須知五月中。","龍潛淥水坑，火助太陽宮。","過雨頻飛電，行雲屢帶虹。","蕤賓移去後，二氣各西東。"]', '["处处闻蟬响，須知五月中。","龙潛淥水坑，火助太陽宮。","過雨頻飞電，行云屢带虹。","蕤賓移去後，二氣各西东。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 夏至五月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee2c6e2-11fd-4893-8c00-11be94308e97', '詠廿四氣詩 小暑六月節', '詠廿四氣诗 小暑六月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["倏忽溫風至，因循小暑來。","竹喧先覺雨，山暗已聞雷。","戶牖深青靄，階庭長綠苔。","鷹鸇新習學，蟋蟀莫相催。"]', '["倏忽溫风至，因循小暑来。","竹喧先覺雨，山暗已闻雷。","戶牖深青靄，階庭长綠苔。","鷹鸇新習学，蟋蟀莫相催。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 小暑六月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f757815-c2c7-4ea3-adca-8ee5ee78d7bb', '詠廿四氣詩 大暑六月中', '詠廿四氣诗 大暑六月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["大暑三秋近，林鐘九夏移。","桂輪開子夜，螢火照空時。","苽菓邀儒客，菰蒲長墨池。","絳紗渾卷上，經史待風吹。"]', '["大暑三秋近，林鐘九夏移。","桂輪开子夜，螢火照空时。","苽菓邀儒客，菰蒲长墨池。","絳紗渾卷上，經史待风吹。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 大暑六月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e57fffd-020a-4abf-ad38-1d0718d93fe0', '詠廿四氣詩 立秋七月節', '詠廿四氣诗 立秋七月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["不期朱夏盡，涼吹暗迎秋。","天漢成橋鵲，星娥會玉樓。","寒聲喧耳外，白露滴林頭。"]', '["不期朱夏尽，涼吹暗迎秋。","天漢成橋鵲，星娥會玉楼。","寒声喧耳外，白露滴林头。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 立秋七月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f62c486f-70ce-436f-8ec8-df42d55c5b17', '詠廿四氣詩 處暑七月中', '詠廿四氣诗 处暑七月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["向來鷹祭鳥，漸覺白藏深。","葉下空驚吹，天高不見心。","氣收禾黍熟，風靜草蟲吟。","緩酌罇中酒，容調膝上琴。"]', '["向来鷹祭鸟，漸覺白藏深。","葉下空驚吹，天高不见心。","氣收禾黍熟，风静草蟲吟。","緩酌罇中酒，容調膝上琴。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 處暑七月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42d0a2f0-257e-462a-af6b-4d07a7d3cbd6', '詠廿四氣詩 白露八月節', '詠廿四氣诗 白露八月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["露霑蔬草白，天氣轉青高。","葉下和秋吹，驚看兩鬢毛（一作「毫」）。","養羞因野鳥，爲客[訝]蓬蒿。","火急收田種，晨昏莫辭勞。"]', '["露霑蔬草白，天氣轉青高。","葉下和秋吹，驚看兩鬢毛（一作「毫」）。","養羞因野鸟，爲客[訝]蓬蒿。","火急收田種，晨昏莫辞勞。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 白露八月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('597ddf1c-f6e4-4925-9a4e-89357e00407c', '詠廿四氣詩 秋分八月中', '詠廿四氣诗 秋分八月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["琴彈南呂調，風色已高清。","雲[散]飄颻影，雷收振怒聲。","乾坤能靜肅，寒暑喜（一作「合」）均平。"]', '["琴彈南呂調，风色已高清。","云[散]飄颻影，雷收振怒声。","乾坤能静肅，寒暑喜（一作「合」）均平。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 秋分八月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9769c1be-a929-4357-a1ef-f03ba25451ad', '詠廿四氣詩 寒露九月節', '詠廿四氣诗 寒露九月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寒露驚秋晚，朝看菊漸黃。","千家風掃葉，萬里雁隨陽。","化蛤悲羣鳥，收田畏早霜。","因知松柏志，冬夏色蒼蒼。"]', '["寒露驚秋晚，朝看菊漸黄。","千家风掃葉，万里雁隨陽。","化蛤悲羣鸟，收田畏早霜。","因知松柏志，冬夏色蒼蒼。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 寒露九月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f68448b8-ee1f-45f6-baac-0ed517f98c21', '詠廿四氣詩 霜降九月中', '詠廿四氣诗 霜降九月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風卷晴霜（一作「清雲」）盡，空天萬里霜。","野豺先祭月，仙菊遇重陽。","秋色悲疏木，鴻鳴憶故鄉。","誰知一罇酒，能使百秋亡。"]', '["风卷晴霜（一作「清云」）尽，空天万里霜。","野豺先祭月，仙菊遇重陽。","秋色悲疏木，鴻鳴憶故乡。","誰知一罇酒，能使百秋亡。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 霜降九月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c00bc0b1-bb19-4325-9f5e-f7d92d4e1c3d', '詠廿四氣詩 立冬十月節', '詠廿四氣诗 立冬十月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["霜降向人寒，輕冰淥水漫。","蟾將纖（一作「輕」）影出，雁帶幾行殘。","田種收藏了，衣裘製造看。","野鷄投水日，化蜃不將難。"]', '["霜降向人寒，轻冰淥水漫。","蟾將纖（一作「轻」）影出，雁带幾行殘。","田種收藏了，衣裘製造看。","野鷄投水日，化蜃不將难。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 立冬十月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14230988-6c4f-4b82-bb77-7bb87b6a0009', '詠廿四氣詩 小雪十月中', '詠廿四氣诗 小雪十月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫怪虹無影，如今小雪時。","陰陽依上下，寒暑喜分離。","滿月光天漢，長風響樹枝。","橫琴對淥醑，猶（一作「獨」）自歛愁眉。"]', '["莫怪虹無影，如今小雪时。","陰陽依上下，寒暑喜分離。","满月光天漢，长风响樹枝。","橫琴对淥醑，猶（一作「独」）自歛愁眉。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 小雪十月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea669e8-e189-4999-883f-564db644a82c', '詠廿四氣詩 大雪十一月節', '詠廿四氣诗 大雪十一月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["積陰成大雪，看處亂霏霏。","玉管鳴寒夜，披書曉絳帷。","黃鐘隨氣改，鷃鳥不鳴時。","何限蒼生類，依依惜暮暉。"]', '["積陰成大雪，看处亂霏霏。","玉管鳴寒夜，披书晓絳帷。","黄鐘隨氣改，鷃鸟不鳴时。","何限蒼生類，依依惜暮暉。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 大雪十一月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf479f27-19c9-49e7-a77f-8fe6639f1986', '詠廿四氣詩 冬至十一月中', '詠廿四氣诗 冬至十一月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["二氣俱生處，周家正立年。","歲星瞻北極，舜（一作「景」）日照南天。","拜慶朝金殿，歡娛列綺筵。"]', '["二氣俱生处，周家正立年。","歲星瞻北極，舜（一作「景」）日照南天。","拜慶朝金殿，歡娛列綺筵。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 冬至十一月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee40f3a-7197-460a-993a-d0fdd09466b6', '詠廿四氣詩 小寒十二月節', '詠廿四氣诗 小寒十二月節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小寒連大呂，歡鵲壘新巢。","拾食尋河曲，銜紫遶樹梢。","霜鷹近北首，雊雉隱藂茅。","莫怪嚴凝切，春冬正月交。"]', '["小寒連大呂，歡鵲壘新巢。","拾食尋河曲，銜紫遶樹梢。","霜鷹近北首，雊雉隐藂茅。","莫怪嚴凝切，春冬正月交。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 小寒十二月節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c94d4c-3e76-4bf9-84ec-b9b8d1098497', '詠廿四氣詩 大寒十二月中', '詠廿四氣诗 大寒十二月中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["臘酒自盈罇，金爐獸炭溫。","大寒宜近火，無事莫開門。","冬與春交替，星周月詎存？","明朝換新律，梅柳待陽春。","（見伯二六二四、斯三八八○卷）（按：此組詩存兩個鈔本。","伯二六二四卷較完整，卷首題「盧相公詠廿四氣詩」。","斯三八八○卷卷首已缺雨水、春分、穀雨、小滿、夏至〖此首僅存末八字〗等五首，卷末題：「甲辰年夏月上旬寫記。","元相公撰，李慶君書。","」今以伯二六二四卷爲底本，以斯三八八○卷參校。","至其作者，二書有異。","元相公可確定爲元稹，盧相公不詳爲誰。","究爲誰作，今已難甄辨。","亦有可能元、盧二人皆爲依託之名。","今姑從一說錄附元稹之末。","）。"]', '["臘酒自盈罇，金爐獸炭溫。","大寒宜近火，無事莫开门。","冬與春交替，星周月詎存？","明朝換新律，梅柳待陽春。","（见伯二六二四、斯三八八○卷）（按：此組诗存兩個鈔本。","伯二六二四卷較完整，卷首題「盧相公詠廿四氣诗」。","斯三八八○卷卷首已缺雨水、春分、穀雨、小满、夏至〖此首僅存末八字〗等五首，卷末題：「甲辰年夏月上旬寫記。","元相公撰，李慶君书。","」今以伯二六二四卷爲底本，以斯三八八○卷參校。","至其作者，二书有異。","元相公可確定爲元稹，盧相公不詳爲誰。","究爲誰作，今已难甄辨。","亦有可能元、盧二人皆爲依託之名。","今姑從一说錄附元稹之末。","）。"]', '诗', 'shi', '', NULL, '詠廿四氣詩 大寒十二月中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481bdeb3-2162-40cc-b07d-dcc760122ad1', '霍小玉歌 一', '霍小玉歌 一', 'f60a591f-53f9-4b87-be56-544dc950a08d', '唐', '["衣飄荳蔻減濃香，臉射芙蓉失嬌色。","（明刻本宋佚名《錦繡萬花谷前集》卷十七引《霍小玉歌》）。"]', '["衣飄荳蔻減濃香，臉射芙蓉失嬌色。","（明刻本宋佚名《錦繡万花谷前集》卷十七引《霍小玉歌》）。"]', '诗', 'shi', '', NULL, '霍小玉歌 一 李惟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae479974-a7a3-4eb5-b7e0-04d52a146b02', '霍小玉歌 二', '霍小玉歌 二', 'f60a591f-53f9-4b87-be56-544dc950a08d', '唐', '["粧成落日捲簾坐，小玉焚香羅帳深。","（見同書同卷引李惟詩）。"]', '["粧成落日捲簾坐，小玉焚香羅帳深。","（见同书同卷引李惟诗）。"]', '诗', 'shi', '', NULL, '霍小玉歌 二 李惟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed6313c-5664-4ab4-b04a-7de9d8a2fd3a', '霍小玉歌 三', '霍小玉歌 三', 'f60a591f-53f9-4b87-be56-544dc950a08d', '唐', '["西北檻前掛鸚鵡，籠中報道李郎來。","（見宋陳元龍《片玉集注》卷一《荔枝香》注引《麗情集》引《小玉歌》）（按：此詩作者之推定，與本書卷二十二崔珏《灼灼歌》相類，可參看。","《新唐書》卷七二《宰相世系表》載李義琛孫、李綰子名惟，約爲盛君時人，當非此詩作者。","）。"]', '["西北檻前掛鸚鵡，籠中報道李郎来。","（见宋陳元龙《片玉集注》卷一《荔枝香》注引《丽情集》引《小玉歌》）（按：此诗作者之推定，與本书卷二十二崔珏《灼灼歌》相類，可參看。","《新唐书》卷七二《宰相世系表》載李義琛孫、李綰子名惟，約爲盛君时人，當非此诗作者。","）。"]', '诗', 'shi', '', NULL, '霍小玉歌 三 李惟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('714cd9e4-fb33-468d-b7fa-4c3de2393aa7', '招李夫人魂賦附楚詞 一', '招李夫人魂賦附楚词 一', 'db94e768-6afe-4417-8849-e353cb67b3df', '唐', '["白玉潔兮紅蘭芳，忽玉折兮蘭已傷。","魂兮勿復遊他方，盍歸來兮慰我皇。"]', '["白玉潔兮紅蘭芳，忽玉折兮蘭已傷。","魂兮勿复游他方，盍归来兮慰我皇。"]', '诗', 'shi', '', NULL, '招李夫人魂賦附楚詞 一 謝觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48ddd13-8007-4715-ac4a-5c6eb1930a49', '招李夫人魂賦附楚詞 二', '招李夫人魂賦附楚词 二', 'db94e768-6afe-4417-8849-e353cb67b3df', '唐', '["彩雲裾兮流霞袂，倏而來兮忽而逝。","魂兮勿復遊四裔，[盍]歸來兮膺萬歲。","（見《文苑英華》卷九六）。"]', '["彩云裾兮流霞袂，倏而来兮忽而逝。","魂兮勿复游四裔，[盍]归来兮膺万歲。","（见《文苑英华》卷九六）。"]', '诗', 'shi', '', NULL, '招李夫人魂賦附楚詞 二 謝觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a927dda-4bcb-49da-9cb9-72e1bdb92487', '偈 一', '偈 一', '8e539e07-7bd6-4977-8698-e62371866bdb', '唐', '["少室人不識，金陵又再來。","臨濟一隻眼，到處爲人開。"]', '["少室人不識，金陵又再来。","臨濟一隻眼，到处爲人开。"]', '诗', 'shi', '', NULL, '偈 一 普化和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9f981d-730c-4040-91a2-dd10bd84f3ea', '偈 二', '偈 二', '8e539e07-7bd6-4977-8698-e62371866bdb', '唐', '["河陽新婦子，木塔老婆禪。","臨濟小廝兒，却具一隻眼。","（《五燈會元》卷四）。"]', '["河陽新婦子，木塔老婆禪。","臨濟小廝兒，却具一隻眼。","（《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 二 普化和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576443e4-9250-4e8a-84d9-d39c311822ab', '十二月四日寄樂天（題擬）', '十二月四日寄乐天（題擬）', '75b203ab-ccf1-4b73-934c-7732fbcb3d09', '唐', '["共相呼喚醉歸來。","（見《白氏長慶集》卷二一《答崔賓客晦叔十二月四日見寄》題注引）。"]', '["共相呼喚醉归来。","（见《白氏长慶集》卷二一《答崔賓客晦叔十二月四日见寄》題注引）。"]', '诗', 'shi', '', NULL, '十二月四日寄樂天（題擬） 崔玄亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b6815df-fa6d-4a4e-951e-b1edb4ed265e', '登第後自詠（題擬）', '登第後自詠（題擬）', '75b203ab-ccf1-4b73-934c-7732fbcb3d09', '唐', '["人間不會雲間事，應笑蓬萊最後仙。","（見前書卷二三《得湖州崔十八使君書喜與杭越鄰郡因成長句代賀兼寄微之》詩末自注引）（按：白氏詩注云：「貞元初同登科，崔君名最在後。","當時崔自詠云〖略〗。","」）。"]', '["人间不會云间事，應笑蓬萊最後仙。","（见前书卷二三《得湖州崔十八使君书喜與杭越鄰郡因成长句代賀兼寄微之》诗末自注引）（按：白氏诗注云：「貞元初同登科，崔君名最在後。","當时崔自詠云〖略〗。","」）。"]', '诗', 'shi', '', NULL, '登第後自詠（題擬） 崔玄亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e4f7d6-5987-4d64-9f5c-8d1ba22c8c0d', '石牀石鑑', '石牀石鑑', 'b3e87c42-9b98-44d0-b05e-9884a15681cf', '唐', '["麓牀高接天，伏虎上棲煙。","松低輕蓋偃，藤細若鉤懸。","石明如掛鏡，照物別媸妍。","鶴鸞時弄影，何處覓神仙。","（見嘉慶十一年曾珏纂《寧遠縣志》卷九）（按：《沅湘耆舊集》卷三以此詩爲二首，前四句題作《麓牀》，後四句題作《石鑑》。","今詳詩意，似作一首爲是。","又此詩與《全唐詩》卷七七駱賓王《出石門》甚相似，疑即據駱詩僞託。","）。"]', '["麓牀高接天，伏虎上棲煙。","松低轻蓋偃，藤細若鉤懸。","石明如掛镜，照物別媸妍。","鹤鸾时弄影，何处覓神仙。","（见嘉慶十一年曾珏纂《寧远縣志》卷九）（按：《沅湘耆旧集》卷三以此诗爲二首，前四句題作《麓牀》，後四句題作《石鑑》。","今詳诗意，似作一首爲是。","又此诗與《全唐诗》卷七七駱賓王《出石门》甚相似，疑即據駱诗僞託。","）。"]', '诗', 'shi', '', NULL, '石牀石鑑 李郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8262d60-5203-483f-b615-0c26acd3c5f6', '贈杜顗', '贈杜顗', '2c50dea5-8b15-4c24-bda3-92135d1e96c2', '唐', '["賈馬死來生杜顗，中間寥落一千年。","（見《樊川文集》卷九《唐故淮南支使試大理評事兼監察御史杜君墓誌銘》）。"]', '["賈马死来生杜顗，中间寥落一千年。","（见《樊川文集》卷九《唐故淮南支使試大理評事兼監察御史杜君墓誌銘》）。"]', '诗', 'shi', '', NULL, '贈杜顗 崔岐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce03e565-1cc7-44c5-8074-77b0d9cb4c5d', '和入京', '和入京', 'cb326a4f-2054-49cb-a29c-2852b9eab6d1', '唐', '["俘囚經萬里，憔悴度三春。","髮改河陽鬢，衣餘京洛塵。","鍾儀悲去楚，隨會泣留秦。","既謝（一作「得」）平吳利，終成失路人。","（見《文苑英華》卷二四○）（按：《古詩紀》、《全隋詩》及逯欽立輯《先秦漢魏晉南北朝詩》皆收此詩爲隋詩，實誤。","隋無呂讓其人，《文苑英華》另收呂讓大和八年作《楚州刺史廳記》，可證。","）。"]', '["俘囚經万里，憔悴度三春。","髮改河陽鬢，衣餘京洛塵。","鍾儀悲去楚，隨會泣留秦。","既謝（一作「得」）平吳利，終成失路人。","（见《文苑英华》卷二四○）（按：《古诗紀》、《全隋诗》及逯欽立輯《先秦漢魏晉南北朝诗》皆收此诗爲隋诗，實誤。","隋無呂讓其人，《文苑英华》另收呂讓大和八年作《楚州刺史廳記》，可證。","）。"]', '诗', 'shi', '', NULL, '和入京 呂讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec536673-1b03-449f-8251-0955d88707d7', '', '', 'a2fe40cb-bee4-44c3-9b80-0fd92aede11f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 范酇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd29a438-27c7-4f90-bc06-f927356dffba', '句', '句', 'a2fe40cb-bee4-44c3-9b80-0fd92aede11f', '唐', '["歲盡天涯雨。","（見《唐詩紀事》卷五十、《增修詩話總龜前集》卷十四引《北夢瑣言》）。"]', '["歲尽天涯雨。","（见《唐诗紀事》卷五十、《增修诗話總龟前集》卷十四引《北梦瑣言》）。"]', '诗', 'shi', '', NULL, '句 范酇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97761d17-a4a7-43c5-9b04-658391a8bb6a', '與于駙馬', '與于駙马', '46eaa6d4-eab7-4a4b-810b-7675994b2d6c', '唐', '["莫惜歌喉一串珠。","（見《白氏長慶集》卷三二《寄明州于駙馬使君三絕句》自注引）。"]', '["莫惜歌喉一串珠。","（见《白氏长慶集》卷三二《寄明州于駙马使君三絕句》自注引）。"]', '诗', 'shi', '', NULL, '與于駙馬 嚴休復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff971ec-a73b-4b6c-b611-613c698a6906', '句', '句', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["不鯽溜鈍漢。","（見《宋景文公筆記》卷上）。"]', '["不鯽溜鈍漢。","（见《宋景文公笔記》卷上）。"]', '诗', 'shi', '', NULL, '句 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b84e887-d366-402f-9d85-575c16bca6a5', '', '', '599ba0c1-bdde-444b-829b-ddc89318315d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陸亘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff534e5-11f4-479c-a543-fa6f27a95434', '遊天衣寺', '游天衣寺', '599ba0c1-bdde-444b-829b-ddc89318315d', '唐', '["處世空旦夕，探幽放情志。","長歌向閑雲，引客遊古寺。","秦山倚寥廓，高鳥下蒼翠。","凝陰向杉松，界法齊天地。","疏鐘遠僧舍，深殿有猨戲。","警梵千谿中，真禪寂無二。","寒泉聳毛髮，清露遣心累。","省慮因悟非，勞神豈爲貴。","起然靜中見，覺了愚勝智。","願得棲煙霞，書之謝名利。","（見《會稽掇英總集》卷八）。"]', '["处世空旦夕，探幽放情志。","长歌向闲云，引客游古寺。","秦山倚寥廓，高鸟下蒼翠。","凝陰向杉松，界法齊天地。","疏鐘远僧舍，深殿有猨戲。","警梵千谿中，真禪寂無二。","寒泉聳毛髮，清露遣心累。","省慮因悟非，勞神豈爲貴。","起然静中见，覺了愚勝智。","願得棲煙霞，书之謝名利。","（见《會稽掇英總集》卷八）。"]', '诗', 'shi', '', NULL, '遊天衣寺 陸亘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b262ce7-9213-46d6-aff6-2433d868402f', '白雲亭', '白云亭', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["僧愛白雲溪上飛，白雲深處敞禪扉。","莫言便是無情物，思着故鄉依舊歸。","（見嘉慶二十年洪亮吉纂《寧國府志》卷二四）。"]', '["僧愛白云溪上飞，白云深处敞禪扉。","莫言便是無情物，思着故乡依旧归。","（见嘉慶二十年洪亮吉纂《寧国府志》卷二四）。"]', '诗', 'shi', '', NULL, '白雲亭 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee521572-29c6-4d86-8d39-2e7a6195e89e', '讚碎金', '讚碎金', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["墨寶三千三百餘，展開勝讀兩車書。","人間要字應來盡，呼作零金也不虛。","（見斯六二○四卷，原署「沈侍郎」）。"]', '["墨寶三千三百餘，展开勝读兩车书。","人间要字應来尽，呼作零金也不虛。","（见斯六二○四卷，原署「沈侍郎」）。"]', '诗', 'shi', '', NULL, '讚碎金 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dbbffa9-4700-4682-8ff4-6b314189c0f8', '久住投機偈', '久住投機偈', '8eee2ec4-3d4e-4a75-abc4-adf660aea909', '唐', '["今日還鄉入大門，南泉親道遍乾坤。","法法分明皆祖父，迴頭慚愧好兒孫。","（見《景德傳燈錄》卷十）。"]', '["今日還乡入大门，南泉親道遍乾坤。","法法分明皆祖父，迴头慚愧好兒孫。","（见《景德傳灯錄》卷十）。"]', '诗', 'shi', '', NULL, '久住投機偈 普願 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49975b99-5688-4ed1-bfa1-5e33988154a4', '偈', '偈', 'f56c4011-ad41-4c74-9fa1-7f55a6203aa5', '唐', '["烏不前，兔不後，幾人於此茫然走。","祇有闍黎達本源，結舌何曾着空有？","（《五燈會元》卷五）。"]', '["烏不前，兔不後，幾人於此茫然走。","祇有闍黎達本源，結舌何曾着空有？","（《五灯會元》卷五）。"]', '诗', 'shi', '', NULL, '偈 性空 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a82a93-98ec-45ac-a14f-88bf2adac587', '宮詞', '宮词', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["簾外微明燭下粧，殿明放鎖待君王。","玉階地冷羅鞋薄，衆裏偷身倚玉牀。","（《分門纂類唐宋時賢千家詩選》卷十六）。"]', '["簾外微明燭下粧，殿明放鎖待君王。","玉階地冷羅鞋薄，衆裏偷身倚玉牀。","（《分门纂類唐宋时賢千家诗選》卷十六）。"]', '诗', 'shi', '', NULL, '宮詞 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e47793f4-f3e8-499d-ab55-38516a9d5071', '', '', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e033de-2111-4f36-910a-d3c1833d84b6', '灙谷', '灙谷', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["高峰偃蹇雲崔嵬，層崖巨壑長峽開。","龍蛇縱橫虎豹亂，古（《洋縣志》作「石」）棧朽滅埋深苔。","（見宋祝穆《方輿勝覽》卷六六，校以光緒二十八年張鵬翼纂《洋縣志》卷七）。"]', '["高峰偃蹇云崔嵬，層崖巨壑长峽开。","龙蛇縱橫虎豹亂，古（《洋縣志》作「石」）棧朽滅埋深苔。","（见宋祝穆《方輿勝覽》卷六六，校以光緒二十八年張鵬翼纂《洋縣志》卷七）。"]', '诗', 'shi', '', NULL, '灙谷 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bdbab1e-2a3e-4af2-8773-9f822e849a5e', '缺題', '缺題', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["寥寥官舍靜於僧，雖有園亭亦倦登。","桃李光陰流似水，圖書滋味冷如冰。"]', '["寥寥官舍静於僧，雖有园亭亦倦登。","桃李光陰流似水，圖书滋味冷如冰。"]', '诗', 'shi', '', NULL, '缺題 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf5f554-c04e-4d6c-a4de-41e01f390480', '缺題', '缺題', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["地形連楚濶，山勢入秦豪。","平外斜通駱，深中遠認褒。","圖經何壯觀，故事有蕭曹。"]', '["地形連楚濶，山勢入秦豪。","平外斜通駱，深中远認褒。","圖經何壯观，故事有蕭曹。"]', '诗', 'shi', '', NULL, '缺題 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38180fe-43a5-4565-9b95-ace473f8be4a', '漢中城樓', '漢中城楼', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["斷煙橫沔水，孤鶩入洋州。","（按：四句當分屬二首。","）。"]', '["斷煙橫沔水，孤鶩入洋州。","（按：四句當分屬二首。","）。"]', '诗', 'shi', '', NULL, '漢中城樓 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cdc17a4-37b6-4619-92b5-648242b04077', '廉水渡', '廉水渡', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["江水不流廉節去，清名長解勝貪泉。"]', '["江水不流廉節去，清名长解勝貪泉。"]', '诗', 'shi', '', NULL, '廉水渡 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f441d47e-7e61-454b-9dc4-b5dab22e035a', '教場', '教場', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["豈知王子山前月，曾照曹劉夜戰來。"]', '["豈知王子山前月，曾照曹劉夜戰来。"]', '诗', 'shi', '', NULL, '教場 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d890d1-b1a8-40f2-b30d-36f9c00bf3b2', '句', '句', 'eeacef93-9b2c-4f34-89bf-3ca1a9b4b422', '唐', '["直望漢江三百里，一條如線下洋州。","（以上六題均見宋王象之《輿地紀勝》卷一八三《興元府》）（〖1〗北宋文同《丹淵集》卷十五《崔覲詩》〖原注：大中時人〗：「崔覲者高士，梁州城固人。","讀書不求官，但與耕稼親。","夫婦既已老，左右無子孫。","一日召奴婢，盡以田宅均。","俾之各爲業，不用來相聞。","遂去隱南山，雜跡麋鹿羣。","約曰或過汝，所給爲我陳。","有時携其妻，來至諸人門。","乃與具酒食，嘯詠相歡欣。","山南鄭餘慶，辟之爲參軍。","見趣使就職，漫不知吏文。","已復許謝事，但謂長者云。","補闕王直方，本覲之比鄰。","文宗時上書，召見蒙咨詢。","薦覲有高行，用可追至淳。","詔授起居郎，裒斜走蒲輪。","辭疾不肯至，高風概秋旻。","我昨過其縣，裴回想芳塵。","訪問諸故老，寂無祠與墳。","斯人久不競，薄夫何由敦？","此縣漢唐時，諸公揚清芬。","刻詩子堅廟，來者期不泯。","」按：文同於北宋熙寧六年知漢中府，此詩爲其時作。","詩中保存了一些崔覲事跡的傳聞，故附存之。","）。"]', '["直望漢江三百里，一條如線下洋州。","（以上六題均见宋王象之《輿地紀勝》卷一八三《兴元府》）（〖1〗北宋文同《丹淵集》卷十五《崔覲诗》〖原注：大中时人〗：「崔覲者高士，梁州城固人。","读书不求官，但與耕稼親。","夫婦既已老，左右無子孫。","一日召奴婢，尽以田宅均。","俾之各爲業，不用来相闻。","遂去隐南山，杂跡麋鹿羣。","約曰或過汝，所給爲我陳。","有时携其妻，来至諸人门。","乃與具酒食，嘯詠相歡欣。","山南鄭餘慶，辟之爲參軍。","见趣使就職，漫不知吏文。","已复許謝事，但謂长者云。","補闕王直方，本覲之比鄰。","文宗时上书，召见蒙咨詢。","薦覲有高行，用可追至淳。","詔授起居郎，裒斜走蒲輪。","辞疾不肯至，高风概秋旻。","我昨過其縣，裴回想芳塵。","訪问諸故老，寂無祠與墳。","斯人久不競，薄夫何由敦？","此縣漢唐时，諸公揚清芬。","刻诗子堅廟，来者期不泯。","」按：文同於北宋熙寧六年知漢中府，此诗爲其时作。","诗中保存了一些崔覲事跡的傳闻，故附存之。","）。"]', '诗', 'shi', '', NULL, '句 崔覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d175677-7022-45fd-904f-11db7e4d1193', '過金山寺', '過金山寺', '03144566-48a7-4602-a36e-a982afa4a9bd', '唐', '["古貌滿堂塵暗色，新華落地鳥繁聲。","經行觀禮自心感，一雨僧人不顯名。","（《經國集》卷十。","轉錄自《空海全集》第七卷《拾遺雜集》）。"]', '["古貌满堂塵暗色，新华落地鸟繁声。","經行观禮自心感，一雨僧人不显名。","（《經国集》卷十。","轉錄自《空海全集》第七卷《拾遺杂集》）。"]', '诗', 'shi', '', NULL, '過金山寺 空海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cece203-8db8-49ea-97f2-74f1f885a3bc', '青龍寺留別義操闍梨', '青龙寺留別義操闍梨', '03144566-48a7-4602-a36e-a982afa4a9bd', '唐', '["同法同門喜遇深，空隨白霧忽歸岑。","一生一別難再見，非夢思中數數尋。","（同前）。"]', '["同法同门喜遇深，空隨白霧忽归岑。","一生一別难再见，非梦思中數數尋。","（同前）。"]', '诗', 'shi', '', NULL, '青龍寺留別義操闍梨 空海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ab4868-6bab-45d6-a269-3f7bd452cb1f', '在唐日觀昶法和尚小山', '在唐日观昶法和尚小山', '03144566-48a7-4602-a36e-a982afa4a9bd', '唐', '["看竹看花本國春，人聲鳥哢漢家新。","見君庭際小山色，還識君情不染塵。","（同前）。"]', '["看竹看花本国春，人声鸟哢漢家新。","见君庭際小山色，還識君情不染塵。","（同前）。"]', '诗', 'shi', '', NULL, '在唐日觀昶法和尚小山 空海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812e9615-ef8b-49a1-bcf9-4c1441e30bd9', '在唐日贈劍南僧惟上離合詩', '在唐日贈劍南僧惟上離合诗', '03144566-48a7-4602-a36e-a982afa4a9bd', '唐', '["磴危人難行，石嶮獸無登。","燭暗迷前後，蜀人不得登。","（同前）（按：張步雲《唐代逸詩輯存》收入後三首。","）。"]', '["磴危人难行，石嶮獸無登。","燭暗迷前後，蜀人不得登。","（同前）（按：張步云《唐代逸诗輯存》收入後三首。","）。"]', '诗', 'shi', '', NULL, '在唐日贈劍南僧惟上離合詩 空海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ccb84f-887e-452d-aba1-a60e8e8400ae', '示柳珵（題擬）', '示柳珵（題擬）', '4c5fafe9-79ee-4c5c-8027-907bd443f46f', '唐', '["興一沙衰恒河沙，兔而罝，犬而拏，牛虎相交與角牙，寶檀終不滅其華。","（《宋高僧傳》卷二十《唐洛陽香山寺鑑空傳》）。"]', '["兴一沙衰恒河沙，兔而罝，犬而拏，牛虎相交與角牙，寶檀終不滅其华。","（《宋高僧傳》卷二十《唐洛陽香山寺鑑空傳》）。"]', '诗', 'shi', '', NULL, '示柳珵（題擬） 鑑空 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa05c5f-d9d4-48b9-a8ce-3baf9b4cec0a', '奉和酬相公賓客漢南留贈八韻', '奉和酬相公賓客漢南留贈八韻', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["自作分憂別，今方便道過。","悲酸如我少，語笑爲君多。","淚亦因盃酒，歡非待（一作「侍」）綺羅。","路[歧]（岐）傷不已，松栢性無他。","悵望商山老，慇懃漢水波。","重言塵外約（相公往年垂贈六約），難繼郢中歌。","玉管離聲發，銀[釭]（缸）曙色和。","碧霄看又遠，其奈獨愁和。","（見《文苑英華》卷二四五）（按：《文苑英華》在令狐楚《將赴洛下旅次漢南獻上相公二十兄言懷八韻》後，緊接本詩，署「前人」。","中華書局影印本新編目錄訂爲李逢吉詩，是。","二詩押韻相同，詩中事跡亦皆可考，茲不贅述。","〖《全唐詩》不收此詩〗）。"]', '["自作分憂別，今方便道過。","悲酸如我少，語笑爲君多。","泪亦因盃酒，歡非待（一作「侍」）綺羅。","路[歧]（岐）傷不已，松栢性無他。","悵望商山老，慇懃漢水波。","重言塵外約（相公往年垂贈六約），难繼郢中歌。","玉管離声發，銀[釭]（缸）曙色和。","碧霄看又远，其奈独愁和。","（见《文苑英华》卷二四五）（按：《文苑英华》在令狐楚《將赴洛下旅次漢南獻上相公二十兄言懷八韻》後，緊接本诗，署「前人」。","中华书局影印本新編目錄訂爲李逢吉诗，是。","二诗押韻相同，诗中事跡亦皆可考，茲不贅述。","〖《全唐诗》不收此诗〗）。"]', '诗', 'shi', '', NULL, '奉和酬相公賓客漢南留贈八韻 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af433fc1-4d0e-495b-ac15-eaaa3de19ab9', '句', '句', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["姮娥歸處月華深。","（胡偉《宮詞》）。"]', '["姮娥归处月华深。","（胡偉《宮词》）。"]', '诗', 'shi', '', NULL, '句 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3737022-e104-4ec9-9a96-985f654a736a', '萬卷讚', '万卷讚', '864e6bfb-4c22-4ba6-bee5-832cd65ab5d6', '唐', '["出廓送錢嫌不要，手提葼笠向廬山。","昔日曾聞青霄鶴，更有青霄鶴不如。"]', '["出廓送錢嫌不要，手提葼笠向廬山。","昔日曾闻青霄鹤，更有青霄鹤不如。"]', '诗', 'shi', '', NULL, '萬卷讚 智常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a31558-b2ed-41a7-ba14-4e4e781375f8', '偈 一', '偈 一', '864e6bfb-4c22-4ba6-bee5-832cd65ab5d6', '唐', '["歸宗事理絕，日輪正當午。","自在如師子，不與物依怙。","獨步四山頂，優遊三大路。","吹噓（《燈錄》、《事苑》作「欠呿」）飛禽墮（《燈錄》、《事苑》作「墜」），嚬呻衆獸（《燈錄》、《事苑》作「邪」）怖。","機豎箭易及，影沒手難覆。","施張如（《燈錄》、《事苑》作「若」）工（《事苑》作「二」）使，剪截（《燈錄》、《事苑》作「裁剪」）成尺度。","巧鏤萬盤（《燈錄》、《事苑》作「般」）名，歸宗還似土。","語密（《燈錄》、《事苑》作「默」）音聲絕，理（《燈錄》作「旨」，《事苑》作「音」）妙言（《燈錄》、《事苑》作「情」）難措。","棄箇耳（《燈錄》、《事苑》作「眼」）還聾，取箇目還瞽。","一鏃破三關，分明箭後路。","𪫧（《燈錄》、《事苑》作「可」）憐箇（《事苑》作「大」）丈夫，先天爲心祖。","（《祖堂集》卷十五、《景德傳燈錄》卷二九、《祖庭事苑》卷二）。"]', '["归宗事理絕，日輪正當午。","自在如師子，不與物依怙。","独步四山頂，優游三大路。","吹噓（《灯錄》、《事苑》作「欠呿」）飞禽墮（《灯錄》、《事苑》作「墜」），嚬呻衆獸（《灯錄》、《事苑》作「邪」）怖。","機豎箭易及，影沒手难覆。","施張如（《灯錄》、《事苑》作「若」）工（《事苑》作「二」）使，剪截（《灯錄》、《事苑》作「裁剪」）成尺度。","巧鏤万盤（《灯錄》、《事苑》作「般」）名，归宗還似土。","語密（《灯錄》、《事苑》作「默」）音声絕，理（《灯錄》作「旨」，《事苑》作「音」）妙言（《灯錄》、《事苑》作「情」）难措。","棄箇耳（《灯錄》、《事苑》作「眼」）還聾，取箇目還瞽。","一鏃破三关，分明箭後路。","𪫧（《灯錄》、《事苑》作「可」）怜箇（《事苑》作「大」）丈夫，先天爲心祖。","（《祖堂集》卷十五、《景德傳灯錄》卷二九、《祖庭事苑》卷二）。"]', '诗', 'shi', '', NULL, '偈 一 智常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ac2144-da7b-45e1-984a-eeb161c4aec2', '偈 二', '偈 二', '864e6bfb-4c22-4ba6-bee5-832cd65ab5d6', '唐', '["牛皮靸（《五燈會元》作「鞔」）露柱，露柱啾啾叫。","凡耳聽不聞，諸聖呵呵笑。","（《景德傳燈錄》卷七、《五燈會元》卷三）。"]', '["牛皮靸（《五灯會元》作「鞔」）露柱，露柱啾啾叫。","凡耳听不闻，諸聖呵呵笑。","（《景德傳灯錄》卷七、《五灯會元》卷三）。"]', '诗', 'shi', '', NULL, '偈 二 智常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423f0347-c7f1-49aa-b7dc-87e6459d68c5', '撥櫂歌 一', '撥櫂歌 一', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["千尺絲綸直下垂，一波纔動萬波隨。","夜靜水寒魚不食，滿船空載月明歸。","（按：《五燈會元》卷八載五代時建州白雲令弇禪師引後二句。","）。"]', '["千尺絲綸直下垂，一波纔动万波隨。","夜静水寒鱼不食，满船空載月明归。","（按：《五灯會元》卷八載五代时建州白云令弇禪師引後二句。","）。"]', '诗', 'shi', '', NULL, '撥櫂歌 一 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab29082-f03d-455c-8968-1b9a104c4ff1', '撥櫂歌 二', '撥櫂歌 二', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["三十年來（《嘉禾志》作「二十餘年」）江（《五燈會元》作「海」）上遊，水清魚見不吞鉤。","釣竿斫盡重栽竹，不計工夫（《五燈會元》作「功程」，《嘉禾志》作「工程」）得便休。"]', '["三十年来（《嘉禾志》作「二十餘年」）江（《五灯會元》作「海」）上游，水清鱼见不吞鉤。","釣竿斫尽重栽竹，不計工夫（《五灯會元》作「功程」，《嘉禾志》作「工程」）得便休。"]', '诗', 'shi', '', NULL, '撥櫂歌 二 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706e9d4e-e77d-40cf-9754-78a541e51691', '撥櫂歌 三', '撥櫂歌 三', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["三（《嘉禾志》作「二」）十餘年（《五燈會元》作「年來」、《四溟詩話》作「年前」）坐釣臺，竿（《五燈會元》、《嘉禾志》、《四溟詩話》皆作「鉤」）頭往往得黃龍。","錦（《五燈會元》、《四溟詩話》作「金」）麟不遇空（《嘉禾志》作「虛」）勞力，收取（《四溟詩話》作「拾」）絲綸歸去來。","（以上三首，《嘉禾志》題作《自題三絕》）。"]', '["三（《嘉禾志》作「二」）十餘年（《五灯會元》作「年来」、《四溟诗話》作「年前」）坐釣台，竿（《五灯會元》、《嘉禾志》、《四溟诗話》皆作「鉤」）头往往得黄龙。","錦（《五灯會元》、《四溟诗話》作「金」）麟不遇空（《嘉禾志》作「虛」）勞力，收取（《四溟诗話》作「拾」）絲綸归去来。","（以上三首，《嘉禾志》題作《自題三絕》）。"]', '诗', 'shi', '', NULL, '撥櫂歌 三 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('925c6421-e55d-4c97-82ca-36334f659a7b', '撥櫂歌 四', '撥櫂歌 四', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["一葉虛舟一副竿，了然無事坐煙灘。","忘得喪，任悲歡，却教人喚有多端。"]', '["一葉虛舟一副竿，了然無事坐煙灘。","忘得喪，任悲歡，却教人喚有多端。"]', '诗', 'shi', '', NULL, '撥櫂歌 四 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276217ef-bebf-48b1-92eb-af4acf5a25fa', '撥櫂歌 五', '撥櫂歌 五', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["一任孤舟正又斜，乾坤何路指生涯。","拋歲月，臥煙霞，在處江山便是家。"]', '["一任孤舟正又斜，乾坤何路指生涯。","拋歲月，臥煙霞，在处江山便是家。"]', '诗', 'shi', '', NULL, '撥櫂歌 五 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fc74eb-5dcb-4736-8217-cc2c234a2fff', '撥櫂歌 六', '撥櫂歌 六', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["愚人未識主人公，終日孜孜恨不同。","到彼岸，出樊籠，元來祇是舊時翁。","（以上三首，《嘉禾志》題作《題松澤西亭三首》）。"]', '["愚人未識主人公，終日孜孜恨不同。","到彼岸，出樊籠，元来祇是旧时翁。","（以上三首，《嘉禾志》題作《題松澤西亭三首》）。"]', '诗', 'shi', '', NULL, '撥櫂歌 六 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29bc5fb7-7ebc-4165-b951-fca01cb2f9b7', '撥櫂歌 七', '撥櫂歌 七', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["有一魚兮日溯洄（《五燈會元》作「偉莫裁」），混虛（《五燈會元》作「融」）包納信奇哉。","能變化，吐風雷，下線何曾釣得來。"]', '["有一鱼兮日溯洄（《五灯會元》作「偉莫裁」），混虛（《五灯會元》作「融」）包納信奇哉。","能变化，吐风雷，下線何曾釣得来。"]', '诗', 'shi', '', NULL, '撥櫂歌 七 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46148f16-9189-4be4-a8f9-0a545f4c8ce1', '撥櫂歌 八', '撥櫂歌 八', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["別人祇看採芙蓉，香氣長黏繞指風。","兩岸映，一船紅，何曾解染得虛空。"]', '["別人祇看採芙蓉，香氣长黏繞指风。","兩岸映，一船紅，何曾解染得虛空。"]', '诗', 'shi', '', NULL, '撥櫂歌 八 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d66b66-f289-4310-bcd5-ba0caae3c364', '撥櫂歌 九', '撥櫂歌 九', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["問我生涯祇是船，子孫各自賭機緣。","不由地，不由天，除却簑衣無可傳。"]', '["问我生涯祇是船，子孫各自賭機緣。","不由地，不由天，除却簑衣無可傳。"]', '诗', 'shi', '', NULL, '撥櫂歌 九 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71e0e045-0bbc-435a-a6fd-393483c8a7c3', '撥櫂歌 十', '撥櫂歌 十', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["莫學他家弄釣船，海風起也不知邊。","風拍岸，浪掀天，不易安排得帖然。"]', '["莫学他家弄釣船，海风起也不知邊。","风拍岸，浪掀天，不易安排得帖然。"]', '诗', 'shi', '', NULL, '撥櫂歌 十 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fd3085-0818-4047-bdf5-750b810dd60f', '撥櫂歌 十一', '撥櫂歌 十一', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["大釣何曾離釣求，拋竿卷線却成愁。","活潑潑，樂悠悠，自是遲疑不下鉤。"]', '["大釣何曾離釣求，拋竿卷線却成愁。","活潑潑，乐悠悠，自是遲疑不下鉤。"]', '诗', 'shi', '', NULL, '撥櫂歌 十一 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2768564-7be9-4ffb-9cac-e2795e4722aa', '撥櫂歌 十二', '撥櫂歌 十二', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["靜在須禪動即禪，斷雲孤鶴兩蕭然。","煙浦畔，月川前，槁木形骸在一船。"]', '["静在須禪动即禪，斷云孤鹤兩蕭然。","煙浦畔，月川前，槁木形骸在一船。"]', '诗', 'shi', '', NULL, '撥櫂歌 十二 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aeb1cb4-eea1-4379-80b9-c46929d0d077', '撥櫂歌 十三', '撥櫂歌 十三', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["莫道無修便不修，菩提癡坐若爲求？勤作櫂，慧爲舟，者箇男兒始出頭。"]', '["莫道無修便不修，菩提癡坐若爲求？勤作櫂，慧爲舟，者箇男兒始出头。"]', '诗', 'shi', '', NULL, '撥櫂歌 十三 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8caf0ace-7f7f-4293-b6c3-949e452559a2', '撥櫂歌 十四', '撥櫂歌 十四', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["水色山光處處新，本來不俗不同塵。","著氣力，用精神，莫作虛生浪死人。"]', '["水色山光处处新，本来不俗不同塵。","著氣力，用精神，莫作虛生浪死人。"]', '诗', 'shi', '', NULL, '撥櫂歌 十四 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c35b55dc-629f-4caa-9bc1-5d5a4454419e', '撥櫂歌 十五', '撥櫂歌 十五', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["獨倚蘭橈入遠灘，江花漠漠水漫漫。","空鉤線，沒腥羶，那得凡魚都上竿。"]', '["独倚蘭橈入远灘，江花漠漠水漫漫。","空鉤線，沒腥羶，那得凡鱼都上竿。"]', '诗', 'shi', '', NULL, '撥櫂歌 十五 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0c295b-00d6-47e7-a085-fc626231870a', '撥櫂歌 十六', '撥櫂歌 十六', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["揭却雲篷進却船，一竿雲影一潭煙。","既擲網，又拋筌，莫教倒被釣絲牽。"]', '["揭却云篷進却船，一竿云影一潭煙。","既擲網，又拋筌，莫教倒被釣絲牽。"]', '诗', 'shi', '', NULL, '撥櫂歌 十六 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c5b5e6-5279-4b2f-8ffc-f8526992db37', '撥櫂歌 十七', '撥櫂歌 十七', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["蒼苔滑淨坐忘機，截眼寒雲葉葉飛。","戴箬笠，掛簑衣，別無歸處是吾歸。","。"]', '["蒼苔滑淨坐忘機，截眼寒云葉葉飞。","戴箬笠，掛簑衣，別無归处是吾归。","。"]', '诗', 'shi', '', NULL, '撥櫂歌 十七 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30dd5257-fc0a-427e-b9bc-964b16fb6386', '撥櫂歌 十八', '撥櫂歌 十八', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["外却形骸放却情，蕭然孤坐一舟輕。","圓月上，四方明，不是奇人不易行。"]', '["外却形骸放却情，蕭然孤坐一舟轻。","圓月上，四方明，不是奇人不易行。"]', '诗', 'shi', '', NULL, '撥櫂歌 十八 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b179ef1-2e25-4cdb-b250-0e2dfa0a6ead', '撥櫂歌 十九', '撥櫂歌 十九', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["世知吾懶懶原真，宇宙船中不管身。","烈香飲，落花茵，祖師元是箇閑人。"]', '["世知吾懶懶原真，宇宙船中不管身。","烈香饮，落花茵，祖師元是箇闲人。"]', '诗', 'shi', '', NULL, '撥櫂歌 十九 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7984fe-b23a-42d8-99e8-efe5e1efcad9', '撥櫂歌 二十', '撥櫂歌 二十', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["都大無心罔象間，此中那許是非關。","山兀兀，水潺潺，忙者自忙閑者閑。"]', '["都大無心罔象间，此中那許是非关。","山兀兀，水潺潺，忙者自忙闲者闲。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c1f170-b8e3-4548-8919-66ca4669749f', '撥櫂歌 二十一', '撥櫂歌 二十一', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["浪宕從來水郭間，高歌欹枕看遙山。","紅蓼岸，白蘋灣，肯被蘭橈使不閑。"]', '["浪宕從来水郭间，高歌欹枕看遙山。","紅蓼岸，白蘋灣，肯被蘭橈使不闲。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十一 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6738682-e1d7-4b15-80d2-df674689b820', '撥櫂歌 二十二', '撥櫂歌 二十二', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["古釣先生鶴髮垂，穿波出浪不曾疑。","心蕩蕩，笑怡怡，長道無人畫得伊。"]', '["古釣先生鹤髮垂，穿波出浪不曾疑。","心蕩蕩，笑怡怡，长道無人畫得伊。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十二 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbb636d-87c0-4c2b-b863-dd9bc0e5a935', '撥櫂歌 二十三', '撥櫂歌 二十三', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["動靜由來本兩空，誰教日夜強施功。","波渺渺，霧濛濛，却來江上隱雲中。"]', '["动静由来本兩空，誰教日夜強施功。","波渺渺，霧濛濛，却来江上隐云中。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十三 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a01f0b-b358-4b82-9f4e-c2f6a51a4634', '撥櫂歌 二十四', '撥櫂歌 二十四', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["媚俗無機獨任真，何須洗耳復澄神。","雲與月，友兼親，敢向浮漚任此身。"]', '["媚俗無機独任真，何須洗耳复澄神。","云與月，友兼親，敢向浮漚任此身。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十四 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4071597f-b09a-486f-87f9-983b216918e4', '撥櫂歌 二十五', '撥櫂歌 二十五', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["逐塊追歡不識休，津梁渾不掛心頭。","霜葉落，岸花秋，却教漁父爲人愁。"]', '["逐塊追歡不識休，津梁渾不掛心头。","霜葉落，岸花秋，却教漁父爲人愁。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十五 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc3aecd-fba8-4460-98d2-de9fd9c998e5', '撥櫂歌 二十六', '撥櫂歌 二十六', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["一片江雲倏忽開，翳空晴日絕塵埃。"]', '["一片江云倏忽开，翳空晴日絕塵埃。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十六 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c1b941-273d-4377-bc2b-fc2488cb9abf', '撥櫂歌 二十七', '撥櫂歌 二十七', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["鼓櫂高歌自適情，音稀和寡不求名。","清風起，浪花平，也且隨流逐勢行。"]', '["鼓櫂高歌自適情，音稀和寡不求名。","清风起，浪花平，也且隨流逐勢行。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十七 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5550fd-a7c0-4607-a9d5-f5a7bc206e2e', '撥櫂歌 二十八', '撥櫂歌 二十八', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["不妨綸線不妨鉤，祇要鉤輪得自由。","擲即擲，收即收，無蹤無跡樂悠悠。"]', '["不妨綸線不妨鉤，祇要鉤輪得自由。","擲即擲，收即收，無蹤無跡乐悠悠。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十八 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c2aa9f-0b15-442b-94e9-d83cb396452e', '撥櫂歌 二十九', '撥櫂歌 二十九', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["鉤下俄逢赤水珠，光明圓徹等清虛。","靜即出，覓還無，不在驪龍不在魚。"]', '["鉤下俄逢赤水珠，光明圓徹等清虛。","静即出，覓還無，不在驪龙不在鱼。"]', '诗', 'shi', '', NULL, '撥櫂歌 二十九 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2fbf34-c601-4bd4-b94a-e46374619daa', '撥櫂歌 三十', '撥櫂歌 三十', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["臥海拏雲勢莫知，優悠何處不相宜。","香象子，大龍兒，甚麽波濤颺得伊。"]', '["臥海拏云勢莫知，優悠何处不相宜。","香象子，大龙兒，甚麽波濤颺得伊。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f9d4f22-4b65-42a6-8cbf-d74cbd416155', '撥櫂歌 三十一', '撥櫂歌 三十一', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["雖慕求魚不食魚，網帘蓬戶本空無。","在世界，作凡夫，知聞祇是箇毘盧。"]', '["雖慕求鱼不食鱼，網帘蓬戶本空無。","在世界，作凡夫，知闻祇是箇毘盧。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十一 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26213571-4b04-47e0-a740-72ddee580ca9', '撥櫂歌 三十二', '撥櫂歌 三十二', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["香餌竿頭也不無，向來祇是釣名魚。","波沃日，浪涵虛，萬象牢籠號有餘。"]', '["香餌竿头也不無，向来祇是釣名鱼。","波沃日，浪涵虛，万象牢籠號有餘。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十二 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b83545f-df66-49d9-be19-98c2e15a78ad', '撥櫂歌 三十三', '撥櫂歌 三十三', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["乾坤爲舸月爲篷，一帶雲山一逕風。","身放蕩，性靈空，何妨南北與西東。","。"]', '["乾坤爲舸月爲篷，一带云山一逕风。","身放蕩，性靈空，何妨南北與西东。","。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十三 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9173c7a9-169c-45e5-b596-46fbd5c30a78', '撥櫂歌 三十四', '撥櫂歌 三十四', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["終日江頭理櫂間，忽然失濟若爲還。","灘急急，水潺潺，爭把浮生作等閑。"]', '["終日江头理櫂间，忽然失濟若爲還。","灘急急，水潺潺，爭把浮生作等闲。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十四 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eabd01a-a18c-48cc-8246-a5c17b767849', '撥櫂歌 三十五', '撥櫂歌 三十五', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["有鶴翺翔出海風，往來蹤跡在虛空。","圖不得，弄何窮，日月還教沒此中。"]', '["有鹤翺翔出海风，往来蹤跡在虛空。","圖不得，弄何窮，日月還教沒此中。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十五 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('221c354b-4ee4-44f8-a484-927316c31861', '撥櫂歌 三十六', '撥櫂歌 三十六', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["釣頭曾未曲些些，靜向江濱度歲華。","酌山茗，折蘆花，誰言埋沒在煙霞。"]', '["釣头曾未曲些些，静向江濱度歲华。","酌山茗，折蘆花，誰言埋沒在煙霞。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十六 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df0f3e50-8db7-4c77-b870-4a82d03904ae', '撥櫂歌 三十七', '撥櫂歌 三十七', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["吾自無心無事間，此心祇有水雲關。","攜釣竹，混塵寰，喧靜都來離又閑。"]', '["吾自無心無事间，此心祇有水云关。","携釣竹，混塵寰，喧静都来離又闲。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十七 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a07960-f007-4599-9aec-b75b356b0f8f', '撥櫂歌 三十八', '撥櫂歌 三十八', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["晴川清瀨水橫流，瀟灑元同不繫舟。","長自在，任夷猶，將心隨逐幾時休。"]', '["晴川清瀨水橫流，瀟灑元同不繫舟。","长自在，任夷猶，將心隨逐幾时休。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十八 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028858cc-f99f-4dcf-8904-0aeefbed9b63', '撥櫂歌 三十九', '撥櫂歌 三十九', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["歐冶銛鋒價最高，海中收得用吹毛。","龍鳳繞，鬼神號，不見全牛可下刀。","（以上三十九首，均見嘉慶間刻本《機緣集》，原爲宋大觀四年風涇海會寺石刻。","轉錄自《詞學》第二期刊施蟄存先生《船子和尚撥櫂歌》。","宋明間收錄船子和尚詩偈的著作，筆者所見有：宋釋惠洪《冷齋夜話》卷五、胡仔《苕溪漁隱叢話前集》卷五六收第一首，宋釋慧明《五燈會元》卷五收其一、其二、其三、其七、其八、其九，共六首，宋吳聿《觀林詩話》收第三十九首，元至元《嘉禾志》卷三二收其一至其六，共六首，明謝榛《四溟詩話》卷三收第三首，楊慎《藝林伐山》卷十七收第一至第三首，今即據諸書所引出校。","）（〖1〗《機緣集》附石刻後呂益柔跋云：「雲間船子和尚嗣法藥山，飄然一舟，泛於華亭吳江洙涇之間。","夾山一見悟道。","嘗爲《撥櫂歌》，其傳播人口者纔一二首。","益柔於先子遺篇中得三十九首，屬詞寄意，脫然迥出塵網之外。","篇篇可觀，決非庸常學道輩所能亂真者。","因書以遺風涇海會卿者，俾鑱之石，以資禪客翫味云。","」〖2〗吳聿《觀林詩話》：「華亭船子和尚詩，少見於世，呂益柔刻三十九首於楓涇寺，云得其父遺編中。","……涪翁屢用其語。","」）。"]', '["歐冶銛鋒價最高，海中收得用吹毛。","龙鳳繞，鬼神號，不见全牛可下刀。","（以上三十九首，均见嘉慶间刻本《機緣集》，原爲宋大观四年风涇海會寺石刻。","轉錄自《词学》第二期刊施蟄存先生《船子和尚撥櫂歌》。","宋明间收錄船子和尚诗偈的著作，笔者所见有：宋釋惠洪《冷斋夜話》卷五、胡仔《苕溪漁隐叢話前集》卷五六收第一首，宋釋慧明《五灯會元》卷五收其一、其二、其三、其七、其八、其九，共六首，宋吳聿《观林诗話》收第三十九首，元至元《嘉禾志》卷三二收其一至其六，共六首，明謝榛《四溟诗話》卷三收第三首，楊慎《藝林伐山》卷十七收第一至第三首，今即據諸书所引出校。","）（〖1〗《機緣集》附石刻後呂益柔跋云：「云间船子和尚嗣法藥山，飄然一舟，泛於华亭吳江洙涇之间。","夾山一见悟道。","嘗爲《撥櫂歌》，其傳播人口者纔一二首。","益柔於先子遺篇中得三十九首，屬词寄意，脫然迥出塵網之外。","篇篇可观，決非庸常学道輩所能亂真者。","因书以遺风涇海會卿者，俾鑱之石，以資禪客翫味云。","」〖2〗吳聿《观林诗話》：「华亭船子和尚诗，少见於世，呂益柔刻三十九首於楓涇寺，云得其父遺編中。","……涪翁屢用其語。","」）。"]', '诗', 'shi', '', NULL, '撥櫂歌 三十九 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29628450-ed70-4f13-88a0-06e4b10c36da', '偈', '偈', '62a547e9-bd3f-487c-b6f0-6ba2a0c93451', '唐', '["本是釣魚船上客，偶力須髮著袈裟。","佛祖位中留不住，夜深依舊宿蘆花。","（見明楊慎《藝林伐山》卷十七《船子和尚四偈》）（〖1〗施蟄存先生云：「此首楊升庵所錄四偈之三，疑是僞作。","」）。"]', '["本是釣鱼船上客，偶力須髮著袈裟。","佛祖位中留不住，夜深依旧宿蘆花。","（见明楊慎《藝林伐山》卷十七《船子和尚四偈》）（〖1〗施蟄存先生云：「此首楊升庵所錄四偈之三，疑是僞作。","」）。"]', '诗', 'shi', '', NULL, '偈 德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab311cf-f1e5-48f4-8efd-babfa1cd2384', '王右軍宅', '王右軍宅', '6e45ae2a-da9e-4516-8abc-a9763e46f5f7', '唐', '["寂寂金庭洞，清香發桂枝。","魚吞左慈釣，鵝踏右軍池。","此地常無事，冲天自有期。","向來逢道士，多欲駕文螭。","（見同治九年刊蔡以瑺撰《鄞縣志》卷二四）（按：宋高似孫《剡錄》卷四及《全唐詩續補遺》卷二十據《永樂大典》卷一三○七四所錄，均僅存前四句。","）。"]', '["寂寂金庭洞，清香發桂枝。","鱼吞左慈釣，鵝踏右軍池。","此地常無事，冲天自有期。","向来逢道士，多欲駕文螭。","（见同治九年刊蔡以瑺撰《鄞縣志》卷二四）（按：宋高似孫《剡錄》卷四及《全唐诗續補遺》卷二十據《永乐大典》卷一三○七四所錄，均僅存前四句。","）。"]', '诗', 'shi', '', NULL, '王右軍宅 裴通 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1f11a9-41f7-4838-b932-66086d30e9d9', '偈', '偈', 'd8a07bc0-9643-44b8-8450-194f4307679e', '唐', '["猛熾燄中人有路，旋風頂上屹然棲。","；鎮常歷劫誰差互，杲日無言運照齊。","（見《景德傳燈錄》卷十、《五燈會元》卷四）。"]', '["猛熾燄中人有路，旋风頂上屹然棲。","；鎮常歷劫誰差互，杲日無言運照齊。","（见《景德傳灯錄》卷十、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 齊安和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc7d9d6-0b1a-49fb-be06-897b8e7b6683', '偈', '偈', '810bf451-b80a-47fb-9897-8dc50f7cfc3c', '唐', '["空門不肯出，投窗也大癡。","百年鑽故紙，何日出頭時？","（見《五燈會元》卷四）。"]', '["空门不肯出，投窗也大癡。","百年鑽故紙，何日出头时？","（见《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 神贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c7f3369-920e-4bc6-be8a-0be0eeac2638', '偈', '偈', 'b8e94e65-aeed-4c38-8c05-6ffc370208a6', '唐', '["有名非大道，是非具不禪。","欲識箇中意，黃葉止啼錢。","（《祖堂集》卷十七、《五燈會元》卷四）。"]', '["有名非大道，是非具不禪。","欲識箇中意，黄葉止啼錢。","（《祖堂集》卷十七、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 公畿和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c19e1b3-95f4-4563-b8f1-28a6cba77b6f', '再勸樂天酒（題擬）', '再勸乐天酒（題擬）', '00fa3bf2-ac76-4fc2-9171-a1d4d0319966', '唐', '["且勸香醪一屈巵。","（《白氏文集管見抄》載白居易《戲酬皇甫十再勸酒》題注引）。"]', '["且勸香醪一屈巵。","（《白氏文集管见抄》載白居易《戲酬皇甫十再勸酒》題注引）。"]', '诗', 'shi', '', NULL, '再勸樂天酒（題擬） 皇甫曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6966e2b7-c259-49a9-b288-990f6fc53681', '洗墨池', '洗墨池', '21cb5f0c-e014-4d06-acc1-f28c9393ed87', '唐', '["賸有臨池興，人稱協律郎。","至今蝌蚪跡，猶帶墨痕香。","（見影印文淵閣《四庫全書》本《湖廣通志》卷八九）。"]', '["賸有臨池兴，人稱協律郎。","至今蝌蚪跡，猶带墨痕香。","（见影印文淵閣《四庫全书》本《湖廣通志》卷八九）。"]', '诗', 'shi', '', NULL, '洗墨池 李翺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c1dc282-437f-44f6-b0eb-2a1bcee5d825', '惆悵詩', '惆悵诗', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["夢裏分明入漢宮，覺來燈背錦屏空。","紫臺日落關山曉，腸斷君恩信畫工。","（見《才調集》卷八）（按：《才調集》卷七複收此詩於王渙名下，《全唐詩》卷六九○沿之。","一書而兩見，孰作較難確定，今重收之，以俟知者。","）。"]', '["梦裏分明入漢宮，覺来灯背錦屏空。","紫台日落关山晓，腸斷君恩信畫工。","（见《才調集》卷八）（按：《才調集》卷七複收此诗於王渙名下，《全唐诗》卷六九○沿之。","一书而兩见，孰作較难確定，今重收之，以俟知者。","）。"]', '诗', 'shi', '', NULL, '惆悵詩 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eafaab6-aaf9-4ee0-b5d8-02dbb996aa92', '永嘉百詠 滴水卷', '永嘉百詠 滴水卷', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '永嘉百詠 滴水卷 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9562b6-3b85-47e9-8162-354048dec499', '永嘉百詠', '永嘉百詠', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["滴水泠泠徹碧紗，旱時無減雨無加。","澄清好是爲官侶，引入孤城一帶斜。","（按：此詩序見明姜準《歧海瑣譚》卷十，承張靖龍同志錄示。","）。"]', '["滴水泠泠徹碧紗，旱时無減雨無加。","澄清好是爲官侶，引入孤城一带斜。","（按：此诗序见明姜準《歧海瑣譚》卷十，承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '永嘉百詠 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded43869-73a3-4bb2-8b16-04e72f2fa82b', '永嘉百詠 郭公山', '永嘉百詠 郭公山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["昔賢登步立神州，氣象千年始一浮。","南望羣州如列宿，北觀江水似龍虬。"]', '["昔賢登步立神州，氣象千年始一浮。","南望羣州如列宿，北观江水似龙虬。"]', '诗', 'shi', '', NULL, '永嘉百詠 郭公山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e7e1d33-6e07-4bdd-9243-75a12cfe97b2', '永嘉百詠 大羅山', '永嘉百詠 大羅山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["越王曾保此山巔，楊僕樓船幾控弦。","猶有舊時懸冰在，鮫綃千尺玉潺湲。"]', '["越王曾保此山巔，楊僕楼船幾控弦。","猶有旧时懸冰在，鮫綃千尺玉潺湲。"]', '诗', 'shi', '', NULL, '永嘉百詠 大羅山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988c4564-63b4-4748-9b45-ed290d1f7ef1', '永嘉百詠 白鶴山', '永嘉百詠 白鹤山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["白鶴山邊秋復春，文君宅畔少風塵。","欲驅五馬尋真隱，誰是當年入竹人？","（見永樂《樂清志》卷二、同治丙寅年刊齊召南纂《溫州府志》卷四）（按：《全唐詩》卷四七九收本詩有缺誤，今重錄之。","）。"]', '["白鹤山邊秋复春，文君宅畔少风塵。","欲驱五马尋真隐，誰是當年入竹人？","（见永乐《乐清志》卷二、同治丙寅年刊齊召南纂《溫州府志》卷四）（按：《全唐诗》卷四七九收本诗有缺誤，今重錄之。","）。"]', '诗', 'shi', '', NULL, '永嘉百詠 白鶴山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7976de-bed1-4129-994c-c3cae94b2210', '永嘉百詠 百里芳', '永嘉百詠 百里芳', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["時清遊騎南徂暑，正值荷花百里開。","民喜出行迎五馬，全家知是使君來。","（光緒《永嘉縣志》卷二一《古跡》）。"]', '["时清游騎南徂暑，正值荷花百里开。","民喜出行迎五马，全家知是使君来。","（光緒《永嘉縣志》卷二一《古跡》）。"]', '诗', 'shi', '', NULL, '永嘉百詠 百里芳 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f498ee-6bc3-4350-9806-47595db57427', '永嘉百詠 周公廟', '永嘉百詠 周公廟', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["祠像已加唐衮冕，樂工猶服晉衣冠。","（見光緒《永嘉縣志》卷四「橫山周公廟」條）（按：《百里芳》、《周公廟》二題，承張靖龍同志錄示。","）。"]', '["祠像已加唐衮冕，乐工猶服晉衣冠。","（见光緒《永嘉縣志》卷四「橫山周公廟」條）（按：《百里芳》、《周公廟》二題，承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '永嘉百詠 周公廟 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b72585-2509-44c0-8b60-2dd3160ff5fa', '永嘉百詠', '永嘉百詠', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["空（按：《中界山》詩，《全唐詩》卷四七九已收。","按：又新《永嘉百詠》，《全唐詩》卷四七九收《游白鶴山》、《白石巖》〖從一作〗、《羅浮山》、《青嶂山》、《中界山》、《帆游山》、《謝池》、《華蓋山》、《吹臺山》、《青㠗山》、《孤嶼》〖弘治《溫州府志》卷二二題作《改孤嶼爲雙峰》〗、《春草池》等十二首，《全唐詩續補遺》卷八收《題常雲峰》、《太玉洞》〖存二句〗二首，本書補五首，凡存十九首〖二首殘〗。","從《滴水巷》、《中界山》二詩序推測，各詩原似皆有序。","）。"]', '["空（按：《中界山》诗，《全唐诗》卷四七九已收。","按：又新《永嘉百詠》，《全唐诗》卷四七九收《游白鹤山》、《白石巖》〖從一作〗、《羅浮山》、《青嶂山》、《中界山》、《帆游山》、《謝池》、《华蓋山》、《吹台山》、《青㠗山》、《孤嶼》〖弘治《溫州府志》卷二二題作《改孤嶼爲雙峰》〗、《春草池》等十二首，《全唐诗續補遺》卷八收《題常云峰》、《太玉洞》〖存二句〗二首，本书補五首，凡存十九首〖二首殘〗。","從《滴水巷》、《中界山》二诗序推測，各诗原似皆有序。","）。"]', '诗', 'shi', '', NULL, '永嘉百詠 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91674bf8-174e-4a3b-8308-6c161d1ff2d5', '臨終（題擬）', '臨終（題擬）', '6f536b4c-4fc7-4d37-b487-c122c89f21be', '唐', '["雲山遊已徧。","（《太平御覽》卷二二二引《唐書》引）。"]', '["云山游已徧。","（《太平御覽》卷二二二引《唐书》引）。"]', '诗', 'shi', '', NULL, '臨終（題擬） 鄭居中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93491d28-3ff1-4c5e-a838-83139f0e80e3', '', '', 'f03671fb-7d42-4941-aaf1-540ffa431a93', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 吳士矩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da4a346-0e85-47b5-aaeb-8a8c279795ed', '獨酌謠', '独酌謠', 'f03671fb-7d42-4941-aaf1-540ffa431a93', '唐', '["愚夫子不招。","（見《白氏長慶集》卷三三《吳秘監每有美酒獨酌獨醉但蒙詩報不以飲招輒此戲酬兼呈夢得》自注引）。"]', '["愚夫子不招。","（见《白氏长慶集》卷三三《吳秘監每有美酒独酌独醉但蒙诗報不以饮招輒此戲酬兼呈梦得》自注引）。"]', '诗', 'shi', '', NULL, '獨酌謠 吳士矩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a96348a-b640-4e26-becb-a7d5fa3cdba3', '贈元微之（題擬）', '贈元微之（題擬）', 'f03671fb-7d42-4941-aaf1-540ffa431a93', '唐', '["永慚沾藥犬，多謝出囊錐。","（見《元氏長慶集》卷十《開元觀閑居酬吳士矩侍御三十韻》自注引）。"]', '["永慚沾藥犬，多謝出囊錐。","（见《元氏长慶集》卷十《开元观闲居酬吳士矩侍御三十韻》自注引）。"]', '诗', 'shi', '', NULL, '贈元微之（題擬） 吳士矩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1467f885-b7ac-4f2a-bc10-4c82122b9523', '句', '句', '246b8a1d-cfaf-4d4d-85b1-1e883f468c07', '唐', '["幾人天上爭仙桂，一歲閩南折四枝。","（見乾隆十九年刊魯曾煜等纂《福州府志》卷六十《文苑》）（〖1〗《福州府志》：「蕭膺，字次元，侯官人，開成三年登第。","是歲閩中同舉者三人，朝士詩云〖詩略〗。","自是閩號爲文儒之鄉。","官至大理司直。","」注：「萬曆《府志》，參《閩書》。","」）。"]', '["幾人天上爭仙桂，一歲閩南折四枝。","（见乾隆十九年刊魯曾煜等纂《福州府志》卷六十《文苑》）（〖1〗《福州府志》：「蕭膺，字次元，侯官人，开成三年登第。","是歲閩中同舉者三人，朝士诗云〖诗略〗。","自是閩號爲文儒之乡。","官至大理司直。","」注：「万曆《府志》，參《閩书》。","」）。"]', '诗', 'shi', '', NULL, '句 開成朝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9854fd3c-a18b-49bf-89a7-4c97be13ea6c', '九日黃白二菊花盛開對懷劉二十八', '九日黄白二菊花盛开对懷劉二十八', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["西花雖未謝，二菊又初芳。","鬢雲徒云白，腰金未是黃。","曙花淩露彩，宵豔射星芒。","日正開邊樹，風清發更香。","山椒應散亂，籬下倍熒煌。","泛酒遙相憶，何由共醉狂。","（見蒲積中《古今歲時雜詠》卷三五）（按：此詩原署「相公」，其次爲劉禹錫和詩「素萼迎寒秀」云云，檢劉詩收《劉賓客外集》卷四，題作《和令狐相公九日對黃白二菊花見懷》，知此詩爲楚作。","）。"]', '["西花雖未謝，二菊又初芳。","鬢云徒云白，腰金未是黄。","曙花淩露彩，宵豔射星芒。","日正开邊樹，风清發更香。","山椒應散亂，籬下倍熒煌。","泛酒遙相憶，何由共醉狂。","（见蒲積中《古今歲时杂詠》卷三五）（按：此诗原署「相公」，其次爲劉禹錫和诗「素萼迎寒秀」云云，檢劉诗收《劉賓客外集》卷四，題作《和令狐相公九日对黄白二菊花见懷》，知此诗爲楚作。","）。"]', '诗', 'shi', '', NULL, '九日黃白二菊花盛開對懷劉二十八 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80273a21-0d48-4301-aaa9-b37a84b107f9', '酬蘇少尹中元夜追懷去年此夕鄙人與故李諫議郭員外見訪感時傷舊之作', '酬蘇少尹中元夜追懷去年此夕鄙人與故李諫議郭員外见訪感时傷旧之作', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["直繼先朝衛與英，能移孝友作忠貞。","劍門失險曾縛虎，淮水安流緣斬鯨。","黃閣碧幢惟是儉，三公二伯未爲榮。","惠連忽贈池塘句，又遣羸師破膽驚。","（見蒲積中《古今歲時雜詠》卷二八）（按：《全唐詩》卷四七三收此爲李逢吉詩，題作《奉酬忠武李相公見寄》，疑誤。","）。"]', '["直繼先朝衛與英，能移孝友作忠貞。","劍门失險曾縛虎，淮水安流緣斬鯨。","黄閣碧幢惟是儉，三公二伯未爲榮。","惠連忽贈池塘句，又遣羸師破膽驚。","（见蒲積中《古今歲时杂詠》卷二八）（按：《全唐诗》卷四七三收此爲李逢吉诗，題作《奉酬忠武李相公见寄》，疑誤。","）。"]', '诗', 'shi', '', NULL, '酬蘇少尹中元夜追懷去年此夕鄙人與故李諫議郭員外見訪感時傷舊之作 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f459a9-fae6-403d-aac8-1b93b38cb926', '社日早出赴祠祭', '社日早出赴祠祭', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["滿城人盡閑，惟我早開關。","慙被家童問，因何別舊山？","（見同書卷十）。"]', '["满城人尽闲，惟我早开关。","慙被家童问，因何別旧山？","（见同书卷十）。"]', '诗', 'shi', '', NULL, '社日早出赴祠祭 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35036542-389e-4071-ac21-62d1d0bdf2c4', '鄂州使至竇七副使中丞（《王》作「竇鞏中丞副使」）見示與元（《王》此下有「稹」字）相公獻酬之什鄙人（《王》作「余頃」）任戶部尚書時（《王》作「日」）中丞是當司員外郎每示（《王》作「有」）篇章多相唱和今因（《王》作「因題」）四韻以寄所懷', '鄂州使至竇七副使中丞（《王》作「竇鞏中丞副使」）见示與元（《王》此下有「稹」字）相公獻酬之什鄙人（《王》作「余頃」）任戶部尚书时（《王》作「日」）中丞是當司員外郎每示（《王》作「有」）篇章多相唱和今因（《王》作「因題」）四韻以寄所懷', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["仙吏秦城別，新詩鄂渚來。","才推今八[斗]（米）（從《王》改），職副舊三台。","雕鏤心偏許，緘封手自開。","何年相贈答，却得在中臺。","（錄自《四部叢刊續編》影宋本《竇氏聯珠集》，以王安石《唐百家詩選》〖簡作《王》〗卷十四所錄詩相校。","）（按：《全唐詩》卷三三四收此詩，題僅作《和寄竇七中丞》，詩中有誤字，故重錄之。","同卷同人《秋懷寄錢侍郎》，《唐百寄詩選》作《郢城秋懷寄江州錢徽侍郎》，附記於此，以備徵考。","）。"]', '["仙吏秦城別，新诗鄂渚来。","才推今八[斗]（米）（從《王》改），職副旧三台。","雕鏤心偏許，緘封手自开。","何年相贈答，却得在中台。","（錄自《四部叢刊續編》影宋本《竇氏聯珠集》，以王安石《唐百家诗選》〖簡作《王》〗卷十四所錄诗相校。","）（按：《全唐诗》卷三三四收此诗，題僅作《和寄竇七中丞》，诗中有誤字，故重錄之。","同卷同人《秋懷寄錢侍郎》，《唐百寄诗選》作《郢城秋懷寄江州錢徽侍郎》，附記於此，以備徵考。","）。"]', '诗', 'shi', '', NULL, '鄂州使至竇七副使中丞（《王》作「竇鞏中丞副使」）見示與元（《王》此下有「稹」字）相公獻酬之什鄙人（《王》作「余頃」）任戶部尚書時（《王》作「日」）中丞是當司員外郎每示（《王》作「有」）篇章多相唱和今因（《王》作「因題」）四韻以寄所懷 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0975399-8a14-4f1c-b762-2f6295d0efe1', '奉送李相公重鎮襄陽', '奉送李相公重鎮襄陽', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["海內埏埴徧，漢陰旌旆還。","望留丹闕下，恩在紫霄間。","冰雪背秦嶺，風煙經武關。","樹皆人尚愛，轅即吏曾攀。","自惜兩心合，相看雙鬢斑。","終期謝戎務，同隱鑿龍山。","（見《文苑英華》卷二四五）（按：《全唐詩》卷四七三收此詩於李逢吉名下，實誤。","明刻本《文苑英華》誤歸逢吉，中華書局影印本參據各本，重編新目，移歸令狐楚，是。","檢《唐方鎮年表》卷四，逢吉於元和十五年初任山南東道節度使，至寶曆二年再任，即詩題所謂「重鎮襄陽」。","《文苑英華》同卷錄逢吉《再赴襄陽辱宣武相公貽詩今用奉酬》，即酬和令狐楚送詩之作，皆六韻。","《唐方鎮年表》卷二載：楚於長慶四年至大和二年間任宣武軍節度使。","）。"]', '["海內埏埴徧，漢陰旌旆還。","望留丹闕下，恩在紫霄间。","冰雪背秦嶺，风煙經武关。","樹皆人尚愛，轅即吏曾攀。","自惜兩心合，相看雙鬢斑。","終期謝戎務，同隐鑿龙山。","（见《文苑英华》卷二四五）（按：《全唐诗》卷四七三收此诗於李逢吉名下，實誤。","明刻本《文苑英华》誤归逢吉，中华书局影印本參據各本，重編新目，移归令狐楚，是。","檢《唐方鎮年表》卷四，逢吉於元和十五年初任山南东道節度使，至寶曆二年再任，即诗題所謂「重鎮襄陽」。","《文苑英华》同卷錄逢吉《再赴襄陽辱宣武相公貽诗今用奉酬》，即酬和令狐楚送诗之作，皆六韻。","《唐方鎮年表》卷二載：楚於长慶四年至大和二年间任宣武軍節度使。","）。"]', '诗', 'shi', '', NULL, '奉送李相公重鎮襄陽 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae393b8b-015b-4e81-8f08-2a02b0c2f57c', '重修望京樓因登樓賦詩（題擬）', '重修望京楼因登楼賦诗（題擬）', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["夷門一鎮五經秋，未得朝天未免愁。","因上此樓望京國，便名樓作望京樓。","（見宋樂史《太平寰宇記》卷一）（按：《全唐詩》卷五六三收此爲令狐綯詩，題作《登望京樓賦》。","岑仲勉先生《讀全唐詩札記》云：「按《寰宇記》一開封府浚儀縣，『望京樓，城西門樓，本無名，唐文宗太和二年，節度使令狐綯重修，因登樓賦詩曰』云云，詩中不免作未免。","據《舊書》一七上，長慶四年九月，『庚戌，以河南尹令狐楚檢校禮部尚書、汴州刺史宣武軍節度宋汴亳觀察等使』，由此計至大和二年，恰是五年。","綯雖嘗一鎮宣武，但《舊書》一七二《綯傳》云：『咸通二年，改汴州刺史宣武軍節度使，三年冬，遷揚州大都督府長史淮南節度副大使知節度事』，則先後祇兩年，非五經秋也。","且在大和二年後三十餘祀，紀年亦不合，是知《寰宇記》云令狐綯，實令狐楚之訛，此詩應移收前五函九冊，綯更無他詩，名應刪却。","」今從其說錄歸楚名下。","《舊唐書》卷十七上載大和二年十月李逢吉移宣武，「代令狐楚，以楚爲戶部尚書」。","楚在宣武任時間正與詩合。","）。"]', '["夷门一鎮五經秋，未得朝天未免愁。","因上此楼望京国，便名楼作望京楼。","（见宋乐史《太平寰宇記》卷一）（按：《全唐诗》卷五六三收此爲令狐綯诗，題作《登望京楼賦》。","岑仲勉先生《读全唐诗札記》云：「按《寰宇記》一开封府浚儀縣，『望京楼，城西门楼，本無名，唐文宗太和二年，節度使令狐綯重修，因登楼賦诗曰』云云，诗中不免作未免。","據《旧书》一七上，长慶四年九月，『庚戌，以河南尹令狐楚檢校禮部尚书、汴州刺史宣武軍節度宋汴亳观察等使』，由此計至大和二年，恰是五年。","綯雖嘗一鎮宣武，但《旧书》一七二《綯傳》云：『咸通二年，改汴州刺史宣武軍節度使，三年冬，遷揚州大都督府长史淮南節度副大使知節度事』，則先後祇兩年，非五經秋也。","且在大和二年後三十餘祀，紀年亦不合，是知《寰宇記》云令狐綯，實令狐楚之訛，此诗應移收前五函九冊，綯更無他诗，名應刪却。","」今從其说錄归楚名下。","《旧唐书》卷十七上載大和二年十月李逢吉移宣武，「代令狐楚，以楚爲戶部尚书」。","楚在宣武任时间正與诗合。","）。"]', '诗', 'shi', '', NULL, '重修望京樓因登樓賦詩（題擬） 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ecac8ff-eae8-48c5-bf76-6da64ee53879', '元和初任禮部員外郎作', '元和初任禮部員外郎作', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["移石幾回敲廢印，開箱何處送（《吟》作「納」）新圖。","（見《春明退朝錄》卷上。","《吟窗雜錄》卷四十作初任員外郎作詩。","）（按：《全唐詩》卷三三四已收二句，故重錄之。","）。"]', '["移石幾回敲廢印，开箱何处送（《吟》作「納」）新圖。","（见《春明退朝錄》卷上。","《吟窗杂錄》卷四十作初任員外郎作诗。","）（按：《全唐诗》卷三三四已收二句，故重錄之。","）。"]', '诗', 'shi', '', NULL, '元和初任禮部員外郎作 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b110716-b7e4-42af-94b1-2a17b3fbecbc', '土圭詩', '土圭诗', '70388b67-8b45-4633-8b84-944c053de38c', '唐', '["白日在重雲，如何分曲直。","（見宋陳應詩《吟窗雜錄》卷二九）。"]', '["白日在重云，如何分曲直。","（见宋陳應诗《吟窗杂錄》卷二九）。"]', '诗', 'shi', '', NULL, '土圭詩 蕭膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0727ce10-25ca-4646-bc10-54cbe464359b', '詠愁', '詠愁', '0493fadc-e2cd-45b2-a2fe-ab19c4c7abd0', '唐', '["應緣心裏難停住，化作新絲出鬢邊。","（同前）。"]', '["應緣心裏难停住，化作新絲出鬢邊。","（同前）。"]', '诗', 'shi', '', NULL, '詠愁 李滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60df530e-a6ac-4358-8507-b89aa193e234', '', '', '3b7d38fe-c931-4aec-a33c-4a3ec96e2833', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陳嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acacad4c-9447-4e2d-b611-fcb146a235ad', '霓裳羽衣曲賦附歌', '霓裳羽衣曲賦附歌', '3b7d38fe-c931-4aec-a33c-4a3ec96e2833', '唐', '["聖功成兮至樂脩，大道叶兮皇風流。","（《文苑英華》卷七四）。"]', '["聖功成兮至乐脩，大道叶兮皇风流。","（《文苑英华》卷七四）。"]', '诗', 'shi', '', NULL, '霓裳羽衣曲賦附歌 陳嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7db4d5-fec9-4f5f-b63c-f34779e185e7', '重建東峰亭（有序）', '重建东峰亭（有序）', 'b47a32d2-5c0f-4269-bb24-cce6927fb893', '唐', '["大賢志勳略，琢石依崔嵬。","聲容問古今，文字埋草萊。","仰想駐旌戟，仍聞建亭臺。","胡爲積歲荒，密邇無人開。","顧鄙作吏間，探幽來此隈。","披尋忽驚喜，歎咏空徘徊。","盼睞得殊境，卑高怯冗材。","薙蕪碧蘚出，芟竹鮮風來。","危檻架幽谷，飛軒標勝垓。","分明見城郭，畢竟拋塵埃。","疊嶂天外展，長溪林際迴。","平原淡煙境，遠壑生雲雷。","物象寧極已，英靈信悠哉。","淒清汎瑤瑟，放浪酣金杯。","求古外凡意，立言悲自媒。","永懷紫芝客，眺覽期相陪。","（清嘉慶十一年刊洪亮吉纂《涇縣志》卷三一）（〖1〗清趙紹祖《涇川金石記》載宋蔣之奇跋云：「裴丹《東峰亭詩》十六句，其碑亡之久矣。","初中裕得斷碑以示余，有其詩幷序，纔十〖「十」字似爲衍文〗六韻，而闕其十韻。","今年至水西，及還，中裕以其碑見寄云：『白雲院僧處璡掘土獲之。","』十六韻皆全，而缺二十餘字。","其前六韻幷序所缺字，則以斷編正之。","獨後十韻中缺一字不可考。","既而公曼復于民間訪得一本爲示，又補後所闕一字，遂爲完篇矣。","序雖不甚佳，而詩頗近雅，重刻之，所以存故事也。","熙寧二年十一月十六日，尚書主客員外郎前殿中侍御史裏行蔣之奇穎叔題。","」）。"]', '["大賢志勳略，琢石依崔嵬。","声容问古今，文字埋草萊。","仰想駐旌戟，仍闻建亭台。","胡爲積歲荒，密邇無人开。","顧鄙作吏间，探幽来此隈。","披尋忽驚喜，歎咏空徘徊。","盼睞得殊境，卑高怯冗材。","薙蕪碧蘚出，芟竹鲜风来。","危檻架幽谷，飞軒標勝垓。","分明见城郭，畢竟拋塵埃。","叠嶂天外展，长溪林際迴。","平原淡煙境，远壑生云雷。","物象寧極已，英靈信悠哉。","淒清汎瑤瑟，放浪酣金杯。","求古外凡意，立言悲自媒。","永懷紫芝客，眺覽期相陪。","（清嘉慶十一年刊洪亮吉纂《涇縣志》卷三一）（〖1〗清趙紹祖《涇川金石記》載宋蔣之奇跋云：「裴丹《东峰亭诗》十六句，其碑亡之久矣。","初中裕得斷碑以示余，有其诗幷序，纔十〖「十」字似爲衍文〗六韻，而闕其十韻。","今年至水西，及還，中裕以其碑见寄云：『白云院僧处璡掘土獲之。","』十六韻皆全，而缺二十餘字。","其前六韻幷序所缺字，則以斷編正之。","独後十韻中缺一字不可考。","既而公曼复于民间訪得一本爲示，又補後所闕一字，遂爲完篇矣。","序雖不甚佳，而诗頗近雅，重刻之，所以存故事也。","熙寧二年十一月十六日，尚书主客員外郎前殿中侍御史裏行蔣之奇穎叔題。","」）。"]', '诗', 'shi', '', NULL, '重建東峰亭（有序） 裴丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e27500-7434-42b9-b8c1-c23e409986b4', '新開龍泉晉水二池', '新开龙泉晉水二池', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["方塘含白水。","（見《白氏長慶集》卷三四《又和令公新開龍泉晉水二池詩》注引）。"]', '["方塘含白水。","（见《白氏长慶集》卷三四《又和令公新开龙泉晉水二池诗》注引）。"]', '诗', 'shi', '', NULL, '新開龍泉晉水二池 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a72d65-d651-42cb-87e3-89116f0be76e', '夏中雨後遊城南莊示樂天八韻（題擬）', '夏中雨後游城南莊示乐天八韻（題擬）', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["何處趁盃盤。","（見《白氏長慶集》卷三二《奉酬侍中夏中雨後遊城南莊見示八韻》自注引）。"]', '["何处趁盃盤。","（见《白氏长慶集》卷三二《奉酬侍中夏中雨後游城南莊见示八韻》自注引）。"]', '诗', 'shi', '', NULL, '夏中雨後遊城南莊示樂天八韻（題擬） 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4823547a-48da-4931-aa14-4e82a32d629b', '送義存出家（題擬）', '送義存出家（題擬）', '1a047c72-945e-4dbf-b8bf-980ab649825c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '送義存出家（題擬） 開成時儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450e923e-427e-4a61-a4bc-16164ec1ca3a', '送義存出家（題擬） 一', '送義存出家（題擬） 一', '1a047c72-945e-4dbf-b8bf-980ab649825c', '唐', '["光陰輪謝又逢春，池柳亭梅幾度新。","汝別家鄉須努力，莫將辜負丈夫身。"]', '["光陰輪謝又逢春，池柳亭梅幾度新。","汝別家乡須努力，莫將辜負丈夫身。"]', '诗', 'shi', '', NULL, '送義存出家（題擬） 一 開成時儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efb0676-d087-474a-857b-108205496a84', '送義存出家（題擬） 二', '送義存出家（題擬） 二', '1a047c72-945e-4dbf-b8bf-980ab649825c', '唐', '["鹿羣相受豈能成，鸞鳳終須萬里征。","何況故鄉貧與賤，蘇秦花錦事分明。"]', '["鹿羣相受豈能成，鸾鳳終須万里征。","何況故乡貧與賤，蘇秦花錦事分明。"]', '诗', 'shi', '', NULL, '送義存出家（題擬） 二 開成時儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4669cf-99b1-44cd-ac54-abb61889d577', '送義存出家（題擬） 三', '送義存出家（題擬） 三', '1a047c72-945e-4dbf-b8bf-980ab649825c', '唐', '["[原憲]（憲原）守貧志不移，顏回安命更誰知？","嘉禾未必春前熟，君子從來用有時。","（見《祖堂集》卷七）（按：《祖堂集》云：「師初出家，時儒假大德送三首詩。","」師指義存，長慶二年生，十七出家，時在開成三年。","「假大德」似非人名，「假」疑「賈」之誤，未能臆定，故姑以「開成時儒」立目。","）。"]', '["[原憲]（憲原）守貧志不移，顏回安命更誰知？","嘉禾未必春前熟，君子從来用有时。","（见《祖堂集》卷七）（按：《祖堂集》云：「師初出家，时儒假大德送三首诗。","」師指義存，长慶二年生，十七出家，时在开成三年。","「假大德」似非人名，「假」疑「賈」之誤，未能臆定，故姑以「开成时儒」立目。","）。"]', '诗', 'shi', '', NULL, '送義存出家（題擬） 三 開成時儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c0bf3b-39e9-4c17-896d-0487d0699fca', '答鹽官齊安國師見招 一', '答鹽官齊安国師见招 一', 'd92d49fc-cf33-4867-89e2-bfb7195b6b71', '唐', '["摧殘枯木倚寒（《祖堂集》作「青」）林，幾度逢春不變心。","樵客遇（《祖堂集》作「見」）之猶不顧（《比事》作「採」），郢人何事（《祖堂集》作「那更」，《傳燈錄》、《五燈會元》作「那得」）苦追（《比事》作「搜」）尋。","（見《古今禪藻集》卷七。","《祖堂集》卷八作曹和尚引古人偈，《景德傳燈錄》卷七、《苕溪漁隱叢話後集》卷三七均作偈，《莆陽比事》卷七引《禪林寶傳》載唐末閩僧躭章稱引此偈，今取以對校。","）（按：《全唐詩》卷八二三收此詩於躭章名下，誤。","躭章係引此偈辭鍾傳召，非自作。","《莆陽比事》云躭章即曹山本寂，可與《祖堂集》相參。","）。"]', '["摧殘枯木倚寒（《祖堂集》作「青」）林，幾度逢春不变心。","樵客遇（《祖堂集》作「见」）之猶不顧（《比事》作「採」），郢人何事（《祖堂集》作「那更」，《傳灯錄》、《五灯會元》作「那得」）苦追（《比事》作「搜」）尋。","（见《古今禪藻集》卷七。","《祖堂集》卷八作曹和尚引古人偈，《景德傳灯錄》卷七、《苕溪漁隐叢話後集》卷三七均作偈，《莆陽比事》卷七引《禪林寶傳》載唐末閩僧躭章稱引此偈，今取以对校。","）（按：《全唐诗》卷八二三收此诗於躭章名下，誤。","躭章係引此偈辞鍾傳召，非自作。","《莆陽比事》云躭章即曹山本寂，可與《祖堂集》相參。","）。"]', '诗', 'shi', '', NULL, '答鹽官齊安國師見招 一 法常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29beb3f1-22be-4c0c-8759-27285d2c5da9', '答鹽官齊安國師見招 二', '答鹽官齊安国師见招 二', 'd92d49fc-cf33-4867-89e2-bfb7195b6b71', '唐', '["一池荷葉衣無盡，數樹松花食有餘。","剛被世人知住處，又移茆舍（《沅湘耆舊集》作「屋」）入深居。","（見《五燈會元》卷四、《古今禪藻集》卷七。","張靖龍云見董慶酉《四明詩幹》卷下引《鄞縣志》、明李鄴嗣《甬上高僧詩》卷首）（按：《沅湘耆舊集》卷十收作隱山和尚詩，似誤。","《全唐詩》卷八六○收許宣平《見李白詩又吟》，與此詩相似，唯異文較多。","檢最早記載許宣平詩事沈汾《續仙傳》，幷不載此詩。","杜文瀾《古謠諺》卷五二引《雲谷臥餘》謂初見于焦竑《焦氏類林》，似候許詩爲明人附會。","今互收。","）。"]', '["一池荷葉衣無尽，數樹松花食有餘。","剛被世人知住处，又移茆舍（《沅湘耆旧集》作「屋」）入深居。","（见《五灯會元》卷四、《古今禪藻集》卷七。","張靖龙云见董慶酉《四明诗幹》卷下引《鄞縣志》、明李鄴嗣《甬上高僧诗》卷首）（按：《沅湘耆旧集》卷十收作隐山和尚诗，似誤。","《全唐诗》卷八六○收許宣平《见李白诗又吟》，與此诗相似，唯異文較多。","檢最早記載許宣平诗事沈汾《續仙傳》，幷不載此诗。","杜文瀾《古謠諺》卷五二引《云谷臥餘》謂初见于焦竑《焦氏類林》，似候許诗爲明人附會。","今互收。","）。"]', '诗', 'shi', '', NULL, '答鹽官齊安國師見招 二 法常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecec7aef-cd12-4e8c-9b49-b1b5796e6a48', '偈', '偈', 'b6d72575-175e-4091-be89-cbe530a010dc', '唐', '["樂兒本是一形軀，乍作官人乍作奴。","名目服章雖改變，始終奴主了無殊。","（見《宗鏡錄》卷七四）。"]', '["乐兒本是一形軀，乍作官人乍作奴。","名目服章雖改变，始終奴主了無殊。","（见《宗镜錄》卷七四）。"]', '诗', 'shi', '', NULL, '偈 宗密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118c1f50-049a-4ef9-b3fd-eeff63987bb4', '座右銘', '座右銘', 'b6d72575-175e-4091-be89-cbe530a010dc', '唐', '["寅起可辦事，省語終寡尤。","身安勤戒定，事簡疎交游。","他非不足辨，己過當自修。","百歲既有限，世事何時休。","落髮墮僧數，應須侔上流。","胡爲逐世變，志慮尚囂浮。","四恩重山嶽，錙銖未能酧。","蚩蚩居大廈，汲汲將焉求。","死生在呼吸，起滅若浮漚。","無令方服下，番作阿鼻由。","（《緇門警訓》卷二）。"]', '["寅起可辦事，省語終寡尤。","身安勤戒定，事簡疎交游。","他非不足辨，己過當自修。","百歲既有限，世事何时休。","落髮墮僧數，應須侔上流。","胡爲逐世变，志慮尚囂浮。","四恩重山嶽，錙銖未能酧。","蚩蚩居大廈，汲汲將焉求。","死生在呼吸，起滅若浮漚。","無令方服下，番作阿鼻由。","（《緇门警訓》卷二）。"]', '诗', 'shi', '', NULL, '座右銘 宗密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c84d81-cbc0-428f-bede-a24a5650a635', '答復禮禪師《真妄偈》（題擬） 一', '答复禮禪師《真妄偈》（題擬） 一', 'b6d72575-175e-4091-be89-cbe530a010dc', '唐', '["本淨本不覺，由斯妄念起。","知真妄即空，知空妄即止。","止處名有終，迷時號無始。","因緣如幻夢，何終復何始？","此是衆生源，窮之出生死。","。"]', '["本淨本不覺，由斯妄念起。","知真妄即空，知空妄即止。","止处名有終，迷时號無始。","因緣如幻梦，何終复何始？","此是衆生源，窮之出生死。","。"]', '诗', 'shi', '', NULL, '答復禮禪師《真妄偈》（題擬） 一 宗密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7976d0c7-6354-4d29-bb70-8cab80baf66a', '答復禮禪師《真妄偈》（題擬） 二', '答复禮禪師《真妄偈》（題擬） 二', 'b6d72575-175e-4091-be89-cbe530a010dc', '唐', '["不是真生妄，妄迷真而起。","悟妄本自真，知真妄即止。","妄止似終末，悟來似初始。","迷悟性皆空，皆空無終始。","生死由此迷，達此出生死。","（《林間錄》卷上）。"]', '["不是真生妄，妄迷真而起。","悟妄本自真，知真妄即止。","妄止似終末，悟来似初始。","迷悟性皆空，皆空無終始。","生死由此迷，達此出生死。","（《林间錄》卷上）。"]', '诗', 'shi', '', NULL, '答復禮禪師《真妄偈》（題擬） 二 宗密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a58f254-3044-47f8-ac4e-6c320fe7e3f5', '望賦附宮人憶月之歌', '望賦附宮人憶月之歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["張衡側身愁思久，王粲登樓日回首。","不作渭濱垂釣臣，羞爲洛陽拜塵友。","（見《劉賓客集》卷一）。"]', '["張衡側身愁思久，王粲登楼日回首。","不作渭濱垂釣臣，羞爲洛陽拜塵友。","（见《劉賓客集》卷一）。"]', '诗', 'shi', '', NULL, '望賦附宮人憶月之歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f70a725-9335-4be6-a548-dde8cd86eabe', '改高陵人頌劉仁師詩（題擬）', '改高陵人頌劉仁師诗（題擬）', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["噫涇水之逶迤，溉我公兮及我私。","水無心兮人多僻，錮上游兮乾我澤。","時逢理兮官得材，墨綬繠兮劉君來。","能愛人兮恤其隱，心既公兮言既盡。","縣申府兮府聞天，積憤刷兮沈痾痊。","劃新渠兮百畝流，行龍蛇兮止膏油。","遵水式兮復田制，無荒區兮有良歲。","嗟劉君兮去翺翔，遺我福兮牽我腸。","紀成功兮鐫美石，求信詞兮昭懿績。","（見《劉賓客集》卷二《高陵縣令劉君遺愛碑》）（〖1〗碑云：「先是高陵人蒙被惠風而惜於捨去，發于胸懷，播爲聲詩。","今采其旨而變其詞，志于石。","」）。"]', '["噫涇水之逶迤，溉我公兮及我私。","水無心兮人多僻，錮上游兮乾我澤。","时逢理兮官得材，墨綬繠兮劉君来。","能愛人兮恤其隐，心既公兮言既尽。","縣申府兮府闻天，積憤刷兮沈痾痊。","劃新渠兮百畝流，行龙蛇兮止膏油。","遵水式兮复田制，無荒區兮有良歲。","嗟劉君兮去翺翔，遺我福兮牽我腸。","紀成功兮鐫美石，求信词兮昭懿績。","（见《劉賓客集》卷二《高陵縣令劉君遺愛碑》）（〖1〗碑云：「先是高陵人蒙被惠风而惜於捨去，發于胸懷，播爲声诗。","今采其旨而变其词，志于石。","」）。"]', '诗', 'shi', '', NULL, '改高陵人頌劉仁師詩（題擬） 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ebc22e3-fb5d-46c4-8552-2ab71205dad7', '祭韓吏部文附詩', '祭韓吏部文附诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["岐山威鳳不復鳴，華亭別鶴中夜驚。","畏簡書兮拘印綬，思臨慟兮志莫就。","生芻一束酒一杯，故人故人歆此來。","（見《劉賓客外集》卷十）。"]', '["岐山威鳳不复鳴，华亭別鹤中夜驚。","畏簡书兮拘印綬，思臨慟兮志莫就。","生芻一束酒一杯，故人故人歆此来。","（见《劉賓客外集》卷十）。"]', '诗', 'shi', '', NULL, '祭韓吏部文附詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c035f0f-1fa2-4957-ad56-90550fdc724e', '聽軋箏', '听軋箏', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["滿座無言聽軋箏，秋山碧樹一蟬清。","只應曾送秦王女，寫得雲間鸞鳳聲。","（見《千載佳句》卷下《宴喜門·箏》）。"]', '["满座無言听軋箏，秋山碧樹一蟬清。","只應曾送秦王女，寫得云间鸾鳳声。","（见《千載佳句》卷下《宴喜门·箏》）。"]', '诗', 'shi', '', NULL, '聽軋箏 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b098b7-6536-420d-a008-4517bc4739e0', '贈樂天', '贈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["唯君比萱草，相見可忘憂。","（《白氏長慶集》卷三四《酬夢得比萱草見贈》自注引）。"]', '["唯君比萱草，相见可忘憂。","（《白氏长慶集》卷三四《酬梦得比萱草见贈》自注引）。"]', '诗', 'shi', '', NULL, '贈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1feb20ad-1ad1-4510-8d0d-1dc1c849af67', '貧居詠懷贈樂天', '貧居詠懷贈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["若有金揮勝二疏。","（同前卷三五《酬夢得貧居詠懷見贈》自注引）。"]', '["若有金揮勝二疏。","（同前卷三五《酬梦得貧居詠懷见贈》自注引）。"]', '诗', 'shi', '', NULL, '貧居詠懷贈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35eeae24-e915-4227-81d7-313dea5a09f4', '酬樂天', '酬乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鍊盡美少年。","（同前《夢得前所酬篇有鍊盡美少年之句因思往事兼詠今懷重以長句答之》）。"]', '["鍊尽美少年。","（同前《梦得前所酬篇有鍊尽美少年之句因思往事兼詠今懷重以长句答之》）。"]', '诗', 'shi', '', NULL, '酬樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58940ba3-35fb-45f6-99d8-27929ca34dd9', '賀樂天談氏外孫女初生', '賀乐天談氏外孫女初生', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["從此引鴛雛。","（同前《談氏外孫生三日喜是男偶吟成篇兼戲呈夢得》自注引。","以上四題皆承陶敏先生見示）（按：陶敏先生告：《南京日報》一九七八年十月二十八日刊許總《友誼的遺珍》一文，云劉禹錫作《贈日本僧智藏》詩，智藏有和詩云：「杯浮碧海海浮天，飄向中華五岳巔。","佛法精微期妙悟，詩靈肸蠁總勾牽。","流連勝境忘來處，契翕嘉賓結異緣。","誰說个中多障礙，試開心鏡照飛烟。","」云出「埋沒數百年的未刊鈔本」。","此詩出處不明，姑附此以俟考詳。","）。"]', '["從此引鴛雛。","（同前《談氏外孫生三日喜是男偶吟成篇兼戲呈梦得》自注引。","以上四題皆承陶敏先生见示）（按：陶敏先生告：《南京日報》一九七八年十月二十八日刊許總《友誼的遺珍》一文，云劉禹錫作《贈日本僧智藏》诗，智藏有和诗云：「杯浮碧海海浮天，飄向中华五岳巔。","佛法精微期妙悟，诗靈肸蠁總勾牽。","流連勝境忘来处，契翕嘉賓結異緣。","誰说个中多障礙，試开心镜照飞烟。","」云出「埋沒數百年的未刊鈔本」。","此诗出处不明，姑附此以俟考詳。","）。"]', '诗', 'shi', '', NULL, '賀樂天談氏外孫女初生 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f694f435-8e02-494b-8c6a-886f83cbd61a', '', '', 'ee485a62-7e91-4060-919f-5559c95b9a8c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 路單 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8f4608-c369-42b0-98e4-020f1fb1f6c0', '和元常侍晦除浙東留題越亭（題擬）', '和元常侍晦除浙东留題越亭（題擬）', 'ee485a62-7e91-4060-919f-5559c95b9a8c', '唐', '["謝安致理逾三載，黃霸清聲徹九重。","猶輟珮環歸鳳闕，且將仁政到稽峰。","林間立馬羅千騎，池上開筵醉一鐘。","共喜甘棠有新詠，獨慚霜鬢又攀龍。","（《桂林風土記》）（按：《全唐詩》卷五四七收此詩，作者誤爲路貫，今改正重錄之。","）。"]', '["謝安致理逾三載，黄霸清声徹九重。","猶輟珮环归鳳闕，且將仁政到稽峰。","林间立马羅千騎，池上开筵醉一鐘。","共喜甘棠有新詠，独慚霜鬢又攀龙。","（《桂林风土記》）（按：《全唐诗》卷五四七收此诗，作者誤爲路貫，今改正重錄之。","）。"]', '诗', 'shi', '', NULL, '和元常侍晦除浙東留題越亭（題擬） 路單 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b5cfa0-06b7-46cd-865b-c5539d0185d0', '樂天偶眠詩', '乐天偶眠诗', 'd3b7ce71-9ac2-4997-b8c1-4da0db5a9411', '唐', '["放盃書桉上，枕臂火爐前。","（《吟窗雜錄》卷二六）。"]', '["放盃书桉上，枕臂火爐前。","（《吟窗杂錄》卷二六）。"]', '诗', 'shi', '', NULL, '樂天偶眠詩 盧貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84045ce1-c890-4e04-a557-71ad4ffafc85', '詠山魈', '詠山魈', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["山魈本是伍家奴，何事今爲聖者呼？小鬼不須乖去就，國家才子號肩吾。","（見何光遠《鑑誡錄》卷八）（《鑑戒錄》云：肩吾「及第後，遊南楚。","楚多山魈爲患，俗號聖者。","是時亦來館谷，攪擾施君，施君當風一詠，於是屏跡。","詩曰〖略〗」。","）。"]', '["山魈本是伍家奴，何事今爲聖者呼？小鬼不須乖去就，国家才子號肩吾。","（见何光远《鑑誡錄》卷八）（《鑑戒錄》云：肩吾「及第後，游南楚。","楚多山魈爲患，俗號聖者。","是时亦来館谷，攪擾施君，施君當风一詠，於是屏跡。","诗曰〖略〗」。","）。"]', '诗', 'shi', '', NULL, '詠山魈 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2d881a-c5e4-439c-8c56-deeedb9cccf0', '下元歌', '下元歌', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["契真之道飄颻易，動不動中如有寄。","那知有無可超忽，去住玄機此其義。","（《雲笈七籤》卷八八施肩吾《養生辨疑訣》附）。"]', '["契真之道飄颻易，动不动中如有寄。","那知有無可超忽，去住玄機此其義。","（《云笈七籤》卷八八施肩吾《養生辨疑訣》附）。"]', '诗', 'shi', '', NULL, '下元歌 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('009ffcda-056b-47e3-941c-c3f4908e3b3e', '贈袁將軍', '贈袁將軍', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["白錦滿胸鷹未老，青鱗動匣劍長寒。","（《千載佳句》卷上《人事部·將軍》）。"]', '["白錦满胸鷹未老，青鱗动匣劍长寒。","（《千載佳句》卷上《人事部·將軍》）。"]', '诗', 'shi', '', NULL, '贈袁將軍 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ff31cd-a891-4f09-bb7e-e42c01d5f367', '太白經附頌', '太白經附頌', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["神水華池便是丹，東西高下自相看。","勸君莫把凡鉛弄，活計生涯便好捐。","鉛則何妨本自鉛，鉛中何處覓神仙？","東西南北還丹了，爭奈仙家不肯傳。","同色同名合好音，亦能爍爍亦沉沉。","乾坤顛倒驅雷雨，龍躍安能出上陰？","（《正統道藏》本《太白經》）。"]', '["神水华池便是丹，东西高下自相看。","勸君莫把凡鉛弄，活計生涯便好捐。","鉛則何妨本自鉛，鉛中何处覓神仙？","东西南北還丹了，爭奈仙家不肯傳。","同色同名合好音，亦能爍爍亦沉沉。","乾坤顛倒驱雷雨，龙躍安能出上陰？","（《正統道藏》本《太白經》）。"]', '诗', 'shi', '', NULL, '太白經附頌 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578e8f1b-8f02-4069-8128-65af116823bb', '皇恩寺（題擬）', '皇恩寺（題擬）', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["睿（別本作「廣」）澤潭來數百年，海山高處有祇園。","禪林自是三三（別本作「山」）界，塵世誰知十二門。","詩客迢迢尋義路，禪翁特特（別本作「轉」）起談軒。","香爐頂上垂東注，萬派分明出一源。","（見影印文淵閣《四庫全書》本《淳熙三山志》卷三五，所注別本指上海圖書館藏清紅格抄本。","原署作者爲「潘誠」，今從《全唐詩》以咸爲正名。","）。"]', '["睿（別本作「廣」）澤潭来數百年，海山高处有祇园。","禪林自是三三（別本作「山」）界，塵世誰知十二门。","诗客迢迢尋義路，禪翁特特（別本作「轉」）起談軒。","香爐頂上垂东注，万派分明出一源。","（见影印文淵閣《四庫全书》本《淳熙三山志》卷三五，所注別本指上海圖书館藏清紅格抄本。","原署作者爲「潘誠」，今從《全唐诗》以咸爲正名。","）。"]', '诗', 'shi', '', NULL, '皇恩寺（題擬） 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c176405-66ab-4b86-8ae1-b99f56a3cd7e', '歌', '歌', 'c914125a-8415-4b72-a544-3f514d8f8a1a', '唐', '["經世學，經世學成無用著。","山中樂，山中樂土堪耕鑿。","癭飄有酒同君酌，醉臥草廬誰喚覺。","松陰忽聽雙鳴（《中國醫籍考》卷七十引作「鳩」）鶴，起來日出穿林薄。","（見《道藏·太平部》收《急救仙方》卷六十《仙授理傷續斷仙方序》引）。"]', '["經世学，經世学成無用著。","山中乐，山中乐土堪耕鑿。","癭飄有酒同君酌，醉臥草廬誰喚覺。","松陰忽听雙鳴（《中国醫籍考》卷七十引作「鳩」）鹤，起来日出穿林薄。","（见《道藏·太平部》收《急救仙方》卷六十《仙授理傷續斷仙方序》引）。"]', '诗', 'shi', '', NULL, '歌 宜春頭陀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ea00d8-ada7-4501-ab02-8187f89e46f1', '樂道歌（《燈錄》作「獲珠吟」）', '乐道歌（《灯錄》作「獲珠吟」）', '1b73c1e2-e65a-4cbc-a6e5-bcd995e2e5ed', '唐', '["三界兮和燄（一作「幻」），六道兮如幻（一作「夢」），聖賢出世兮同（一作「如」）。","國土猶如水上泡，無常生滅頻（一作「無生滅」）遷變。","唯有摩訶大般若（一作「般若堅」），堅（一作「猶」）如金剛是可羨（一作「不可讚」）。","軟似兜羅大等空，極小纖（一作「小極微」）塵不可見。","擁之令聚而不聚，撥之令散而不散，側耳欲聞而不聞，瞪目觀之不能見（一作「而不見」）。","謌復謌，盤陀石上笑訶訶。","笑復笑，青蘿松（一作「松影」）下高聲叫。","自從頓獲此明珠（一作「獲得此心珠」），帝釋輪王都（一作「俱」）不要。","不是山僧獨施爲，自古先賢作此調。","不坐禪，不修道，任運逍遙只摩好（一作「麽了」）。","但知萬（一作「能方」）法不干懷，無如（一作「始」）何曾有生老。","（見《祖堂集》卷十七，注「一作」者，爲《景德傳燈錄》卷三十所收此詩之異文。","）。"]', '["三界兮和燄（一作「幻」），六道兮如幻（一作「梦」），聖賢出世兮同（一作「如」）。","国土猶如水上泡，無常生滅頻（一作「無生滅」）遷变。","唯有摩訶大般若（一作「般若堅」），堅（一作「猶」）如金剛是可羨（一作「不可讚」）。","軟似兜羅大等空，極小纖（一作「小極微」）塵不可见。","擁之令聚而不聚，撥之令散而不散，側耳欲闻而不闻，瞪目观之不能见（一作「而不见」）。","謌复謌，盤陀石上笑訶訶。","笑复笑，青蘿松（一作「松影」）下高声叫。","自從頓獲此明珠（一作「獲得此心珠」），帝釋輪王都（一作「俱」）不要。","不是山僧独施爲，自古先賢作此調。","不坐禪，不修道，任運逍遙只摩好（一作「麽了」）。","但知万（一作「能方」）法不干懷，無如（一作「始」）何曾有生老。","（见《祖堂集》卷十七，注「一作」者，爲《景德傳灯錄》卷三十所收此诗之異文。","）。"]', '诗', 'shi', '', NULL, '樂道歌（《燈錄》作「獲珠吟」） 道常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e424b813-76fd-42b8-8a3c-3df6b904fd74', '船子和尚東遊泊釣船處', '船子和尚东游泊釣船处', '44caf784-6062-493b-8f61-8a9d28197024', '唐', '["和尚東來泊釣船，一溪秋水月明天。","此中定有高人出，爲憶前身幾百年。","（《續機緣集》卷上）（按：清嘉慶六年三月二十七日，法忍寺天空閣毀於火，於灰燼中得小碣，中刻此詩，後勒會昌元年十一月款，書愚公谷人記。","）。"]', '["和尚东来泊釣船，一溪秋水月明天。","此中定有高人出，爲憶前身幾百年。","（《續機緣集》卷上）（按：清嘉慶六年三月二十七日，法忍寺天空閣毀於火，於灰燼中得小碣，中刻此诗，後勒會昌元年十一月款，书愚公谷人記。","）。"]', '诗', 'shi', '', NULL, '船子和尚東遊泊釣船處 愚公谷人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e1da2c-08c8-4945-9dc4-d1295b8e4b03', '逢友人', '逢友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["還似不才命未通，相逢雲水思無窮。","清時年少爲幽客，寒月更深聽過鴻。","東越山多連楚疊，南朝城古枕江空。","蒼崖欲隱誰招我？姜子生涯只此中。","（見《吟窗雜錄》卷十三梅堯臣《續金針詩格》引）。"]', '["還似不才命未通，相逢云水思無窮。","清时年少爲幽客，寒月更深听過鴻。","东越山多連楚叠，南朝城古枕江空。","蒼崖欲隐誰招我？姜子生涯只此中。","（见《吟窗杂錄》卷十三梅堯臣《續金針诗格》引）。"]', '诗', 'shi', '', NULL, '逢友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6640f70-0934-4378-9f2f-958feb160991', '送人', '送人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["半夜長安雨，燈前越客心。","（見同書卷十二沙門文彧《詩格》）。"]', '["半夜长安雨，灯前越客心。","（见同书卷十二沙门文彧《诗格》）。"]', '诗', 'shi', '', NULL, '送人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2c4007-e20d-4361-b2bd-99d6b503106a', '桃氏林亭', '桃氏林亭', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["窗含明月樹，沙起白雲鷗。","（見同書卷十四正字王元《詩中旨格》）。"]', '["窗含明月樹，沙起白云鷗。","（见同书卷十四正字王元《诗中旨格》）。"]', '诗', 'shi', '', NULL, '桃氏林亭 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0338d586-a194-4c28-87b0-89d8eab76841', '南臺對月', '南台对月', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["僧歸湖裏寺，魚聽水邊經。"]', '["僧归湖裏寺，鱼听水邊經。"]', '诗', 'shi', '', NULL, '南臺對月 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da570122-9eed-4b2c-bc5e-132e09adae05', '寄[貞]（正）空二上人', '寄[貞]（正）空二上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["老窺明鏡少，秋憶故山多。","（均見同書卷三五《賈島句對》）。"]', '["老窺明镜少，秋憶故山多。","（均见同书卷三五《賈島句对》）。"]', '诗', 'shi', '', NULL, '寄[貞]（正）空二上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125192f7-099a-4cfc-b6e8-01229b19145f', '句 一', '句 一', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["風雷一夜雨，山川半年行。","（見同書卷十三王夢簡《進士王氏詩要格律》）。"]', '["风雷一夜雨，山川半年行。","（见同书卷十三王梦簡《進士王氏诗要格律》）。"]', '诗', 'shi', '', NULL, '句 一 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97a927d9-c474-4bd7-a236-19e20808d2a3', '句 二', '句 二', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["祭閒收朔雪，弔後折寒花。"]', '["祭閒收朔雪，弔後折寒花。"]', '诗', 'shi', '', NULL, '句 二 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70d5da8-19dc-4879-a59a-9e2af6853cbb', '句 三', '句 三', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["離人隔楚水，落葉滿長安。","（均見同書卷十三僧虛中《流類手鑑》）。"]', '["離人隔楚水，落葉满长安。","（均见同书卷十三僧虛中《流類手鑑》）。"]', '诗', 'shi', '', NULL, '句 三 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5202e617-2755-4bb8-bac4-a06f113b082d', '梧桐詩', '梧桐诗', 'e085510b-72c4-4e40-a95d-f7a795ccb88c', '唐', '["只期丹鳳宿，不許別禽棲。","（見《吟窗雜錄》卷十四正字王元《詩中旨格》）。"]', '["只期丹鳳宿，不許別禽棲。","（见《吟窗杂錄》卷十四正字王元《诗中旨格》）。"]', '诗', 'shi', '', NULL, '梧桐詩 周賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ac16be-36cc-4433-87d6-0c6bc59e23e0', '句', '句', 'e085510b-72c4-4e40-a95d-f7a795ccb88c', '唐', '["兩鬢已垂白，五湖歸釣魚。","（見《唐詩紀事》卷七六）。"]', '["兩鬢已垂白，五湖归釣鱼。","（见《唐诗紀事》卷七六）。"]', '诗', 'shi', '', NULL, '句 周賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09322169-1fa5-4f61-aa1e-57ca187da535', '秋望', '秋望', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["西風蟬滿樹，東岸有殘暉。","（《吟窗雜錄》卷十徐衍《風騷要式》）。"]', '["西风蟬满樹，东岸有殘暉。","（《吟窗杂錄》卷十徐衍《风騷要式》）。"]', '诗', 'shi', '', NULL, '秋望 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fab094d-3004-4252-8188-f6445b718349', '', '', '60e1819c-71a9-4afa-a62b-30d2cee4e52d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 賀蘭朋吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83192071-aeae-4c24-b20e-f32b2fe57b64', '句', '句', '60e1819c-71a9-4afa-a62b-30d2cee4e52d', '唐', '["五更愁處雨，三月盡時花。","（見《吟窗雜錄》卷三五）。"]', '["五更愁处雨，三月尽时花。","（见《吟窗杂錄》卷三五）。"]', '诗', 'shi', '', NULL, '句 賀蘭朋吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0379de5f-11f2-42e1-9183-d986938a4d1b', '句', '句', 'c6d49214-8563-47f3-9ec3-24699c780fdf', '唐', '["多少千條拂地垂。","（《江湖小集》卷七紹嵩《江浙紀行集句詩》引）。"]', '["多少千條拂地垂。","（《江湖小集》卷七紹嵩《江浙紀行集句诗》引）。"]', '诗', 'shi', '', NULL, '句 滕邁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c533d33-5a3e-4c4b-977c-861b1f394946', '玉泉寺次韻寄白樂天刺史', '玉泉寺次韻寄白乐天刺史', '529f101c-cf3b-420a-a77b-78793c508df7', '唐', '["古泉猶玉色，散木自閑身。","挹秀尋芳躅，賡題步後塵。","登山謝雙屐，漉酒一陶巾。","誰得向清淨，居亭作主人。","（見《古今禪藻集》卷四）。"]', '["古泉猶玉色，散木自闲身。","挹秀尋芳躅，賡題步後塵。","登山謝雙屐，漉酒一陶巾。","誰得向清淨，居亭作主人。","（见《古今禪藻集》卷四）。"]', '诗', 'shi', '', NULL, '玉泉寺次韻寄白樂天刺史 僧初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f8f4399-7304-409a-8ac9-f445ecbe785b', '悼故妓', '悼故妓', '13f7b2aa-1470-42f9-9ca6-fac4b26349ef', '唐', '["直應人世無風月，始是心中忘却時。","（見《白氏長慶集》卷三五《對酒有懷寄李十九郎中》自注引）（按：李十九即李播，從郁賢皓先生《唐刺史考》卷一三一《蘄州》考證。","）。"]', '["直應人世無风月，始是心中忘却时。","（见《白氏长慶集》卷三五《对酒有懷寄李十九郎中》自注引）（按：李十九即李播，從郁賢皓先生《唐刺史考》卷一三一《蘄州》考證。","）。"]', '诗', 'shi', '', NULL, '悼故妓 李播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01a7b736-d1e5-4761-966e-24dd6b0640b1', '長相思', '长相思', '690ebd4a-6225-482d-83cd-b55799b3af9b', '唐', '["深畫眉，淺畫眉，蟬鬢鬅鬙雲滿衣，陽臺行雨迴。","巫山高，巫山低，暮雨瀟瀟郎不歸，空房獨守時。","（見宋黃昇《唐宋諸賢絕妙詞選》卷一，原署爲白居易作）（〖1〗明刻本《吟窗雜錄》卷五十錄吳二娘《長相思令》云：「深黛眉，淺黛眉，十指蘢葱雲染衣，巫山行雨行〖疑爲迴之誤〗。","巫山高，巫山低，暮暮朝朝良不歸，空房獨守誰？","」〖2〗明楊慎《升菴詩話》卷四云：「吳二娘，杭州名妓也。","有《長相思》一詞云：『深花枝，淺花枝，深淺花枝相間時，花枝難似伊。","巫山高，巫山低，暮雨瀟瀟郎不歸，空房獨守時。","』白樂天詩：『吳娘暮雨瀟瀟曲，自別江南久不聞。","』又：『夜舞吳娘袖，春歌蠻子詞。","』自注：『吳二娘歌詞有暮雨瀟瀟郎不歸之句。","』《絕妙詞選》以此爲白樂天詞，誤矣。","吳二娘亦杜公之黃四娘也，聊表出之。","」今按：楊慎引白氏二詩，前詩爲《寄殷協律》，後詩爲《聽彈湘妃怨》。","其訂黃氏之失，甚是。","《吟窗雜錄》爲北宋末蔡傳所作書〖詳拙文《殷璠〈丹陽集〉輯考》〗，已徑題吳二娘作，可證。","惟三本文字差異較大，黃昇所錄，似與白氏所聞者最爲接近，故錄爲正文，而以餘二本附於後。","《全唐詩》卷八九○據黃昇所錄收歸白居易，今爲移正之。","）。"]', '["深畫眉，淺畫眉，蟬鬢鬅鬙云满衣，陽台行雨迴。","巫山高，巫山低，暮雨瀟瀟郎不归，空房独守时。","（见宋黄昇《唐宋諸賢絕妙词選》卷一，原署爲白居易作）（〖1〗明刻本《吟窗杂錄》卷五十錄吳二娘《长相思令》云：「深黛眉，淺黛眉，十指蘢葱云染衣，巫山行雨行〖疑爲迴之誤〗。","巫山高，巫山低，暮暮朝朝良不归，空房独守誰？","」〖2〗明楊慎《升菴诗話》卷四云：「吳二娘，杭州名妓也。","有《长相思》一词云：『深花枝，淺花枝，深淺花枝相间时，花枝难似伊。","巫山高，巫山低，暮雨瀟瀟郎不归，空房独守时。","』白乐天诗：『吳娘暮雨瀟瀟曲，自別江南久不闻。","』又：『夜舞吳娘袖，春歌蠻子词。","』自注：『吳二娘歌词有暮雨瀟瀟郎不归之句。","』《絕妙词選》以此爲白乐天词，誤矣。","吳二娘亦杜公之黄四娘也，聊表出之。","」今按：楊慎引白氏二诗，前诗爲《寄殷協律》，後诗爲《听彈湘妃怨》。","其訂黄氏之失，甚是。","《吟窗杂錄》爲北宋末蔡傳所作书〖詳拙文《殷璠〈丹陽集〉輯考》〗，已徑題吳二娘作，可證。","惟三本文字差異較大，黄昇所錄，似與白氏所闻者最爲接近，故錄爲正文，而以餘二本附於後。","《全唐诗》卷八九○據黄昇所錄收归白居易，今爲移正之。","）。"]', '诗', 'shi', '', NULL, '長相思 吳二娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7cb149-77ed-42cd-bbbd-0f63572f9c81', '', '', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0069dbf-0726-4440-8fc3-19dd1f95cc42', '濟源上枉舒員外兩篇因酬六韻', '濟源上枉舒員外兩篇因酬六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歇手不判案，舉頭仍見山。","雖來鞍馬上，不離詩酒間。","濟源三臨泛，王屋一登攀。","猶嫌百里近，祇得十日閒。","明朝却歸府，塵事如循環。","猶聽瑤華曲，稍開風土顏。","（見《四部叢刊》影印那波道圓本《白氏文集》卷五二）。"]', '["歇手不判案，舉头仍见山。","雖来鞍马上，不離诗酒间。","濟源三臨泛，王屋一登攀。","猶嫌百里近，祇得十日閒。","明朝却归府，塵事如循环。","猶听瑤华曲，稍开风土顏。","（见《四部叢刊》影印那波道圓本《白氏文集》卷五二）。"]', '诗', 'shi', '', NULL, '濟源上枉舒員外兩篇因酬六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d48d728-057e-425e-85af-754a45addbe0', '同崔十八宿龍門兼寄令狐尚書馮常侍', '同崔十八宿龙门兼寄令狐尚书馮常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水碧玉磷磷，龍門秋勝春。","山中一夜月，海內兩閒人。","等是幽棲伴，俱非富貴身。","尚書與常侍，不可得相親。","（見前書卷五七）。"]', '["水碧玉磷磷，龙门秋勝春。","山中一夜月，海內兩閒人。","等是幽棲伴，俱非富貴身。","尚书與常侍，不可得相親。","（见前书卷五七）。"]', '诗', 'shi', '', NULL, '同崔十八宿龍門兼寄令狐尚書馮常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210bb1e1-f67f-4659-b105-31e6fc6893d3', '雨歇池上', '雨歇池上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["簷前微雨歇，池上凉風起。","橋竹碧鮮鮮，岸移莎靡靡。","蒼然古苔石，清淺平流水。","何言中門前，便是深山裏。","雙僮侍坐臥。","一杖扶行止。","飢聞麻粥香，渴覺雲湯美。","平生所好物，今日多在此。","此外更何思？","市朝心已矣！（見前書卷六三）。"]', '["簷前微雨歇，池上凉风起。","橋竹碧鲜鲜，岸移莎靡靡。","蒼然古苔石，清淺平流水。","何言中门前，便是深山裏。","雙僮侍坐臥。","一杖扶行止。","飢闻麻粥香，渴覺云湯美。","平生所好物，今日多在此。","此外更何思？","市朝心已矣！（见前书卷六三）。"]', '诗', 'shi', '', NULL, '雨歇池上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ddc407e-feb6-4815-9eeb-71b9729f4b91', '十二時行孝文 一', '十二时行孝文 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平旦寅，早起堂前參二親。","處分家中送疎水，莫[教]（交）父母喚頻聲。"]', '["平旦寅，早起堂前參二親。","处分家中送疎水，莫[教]（交）父母喚頻声。"]', '诗', 'shi', '', NULL, '十二時行孝文 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adef0210-ea0a-4877-b18c-7c76e3f20a03', '十二時行孝文 二', '十二时行孝文 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日出卯，立身之本須行孝。","甘{餄右爲危}盤中莫使空，時時奉上知饑飽。"]', '["日出卯，立身之本須行孝。","甘{餄右爲危}盤中莫使空，时时奉上知饑飽。"]', '诗', 'shi', '', NULL, '十二時行孝文 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b835f60f-4d4d-4c10-b467-fc9bbf213d82', '十二時行孝文 三', '十二时行孝文 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["食時辰，居家治務最須懃。","無事等閑莫外宿，歸來勞費父嫌憎。"]', '["食时辰，居家治務最須懃。","無事等闲莫外宿，归来勞費父嫌憎。"]', '诗', 'shi', '', NULL, '十二時行孝文 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ac99f8-35ce-4c3a-a4fe-7c194afac9e3', '十二時行孝文 四', '十二时行孝文 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隅中巳，終孝之心不合二。","竭力懃酬乳哺恩，自得名高上史記。","。"]', '["隅中巳，終孝之心不合二。","竭力懃酬乳哺恩，自得名高上史記。","。"]', '诗', 'shi', '', NULL, '十二時行孝文 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3353d090-1eba-4b6f-a4af-c66192a4b963', '十二時行孝文 五', '十二时行孝文 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["正南午，侍奉尊親莫辭[訴]（訢）。","迴乾就濕長成人，如今去（疑爲「未」字）合論辛苦。"]', '["正南午，侍奉尊親莫辞[訴]（訢）。","迴乾就濕长成人，如今去（疑爲「未」字）合論辛苦。"]', '诗', 'shi', '', NULL, '十二時行孝文 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21357813-0982-40a2-a2e6-a4790cfc1dd8', '十二時行孝文 六', '十二时行孝文 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日昳未，在家行孝兼行義。","莫取妻言兄弟疏，却[教]（交）父母流雙淚。"]', '["日昳未，在家行孝兼行義。","莫取妻言兄弟疏，却[教]（交）父母流雙泪。"]', '诗', 'shi', '', NULL, '十二時行孝文 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8634fa4b-9676-46d2-a166-a46011d1a7db', '十二時行孝文 七', '十二时行孝文 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晡時申，父母堂前莫動塵。","縱月些些不稱意，向前小語善諮聞。"]', '["晡时申，父母堂前莫动塵。","縱月些些不稱意，向前小語善諮闻。"]', '诗', 'shi', '', NULL, '十二時行孝文 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7816d93-9d4f-4c14-8757-fd0fb53a10d4', '十二時行孝文 八', '十二时行孝文 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日入酉，但願父母得長[壽]（受）。","身如松栢色堅政，莫學愚人多飲酒。"]', '["日入酉，但願父母得长[壽]（受）。","身如松栢色堅政，莫学愚人多饮酒。"]', '诗', 'shi', '', NULL, '十二時行孝文 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ccf359f-f8f0-4edf-a1fc-c245776601ba', '十二時行孝文 九', '十二时行孝文 九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃昏戌，下簾拂牀早交畢。","安置父母臥高堂，睡定然乃抽身出。"]', '["黄昏戌，下簾拂牀早交畢。","安置父母臥高堂，睡定然乃抽身出。"]', '诗', 'shi', '', NULL, '十二時行孝文 九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412f7ac1-d348-4a18-b686-1f004c564d71', '十二時行孝文 十', '十二时行孝文 十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人定亥，父母年高須[保]（報）愛。","但能行孝向尊親，總得揚名於後世。"]', '["人定亥，父母年高須[保]（報）愛。","但能行孝向尊親，總得揚名於後世。"]', '诗', 'shi', '', NULL, '十二時行孝文 十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af82098-a3dd-4302-a62b-c506ed502e1d', '十二時行孝文 十一', '十二时行孝文 十一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜半子，孝養父母存終始。","百年恩愛暫時間，莫學愚人不歡喜。"]', '["夜半子，孝養父母存終始。","百年恩愛暫时间，莫学愚人不歡喜。"]', '诗', 'shi', '', NULL, '十二時行孝文 十一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6055df-6f79-4497-9efa-a410f1158bc0', '十二時行孝文 十二', '十二时行孝文 十二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鷄鳴丑，高樓大宅得安久。","常勸父母發慈心，孝得題名終不朽。","（見伯三八二一卷。","原題作「白侍郎作《十二時行孝文》」）。"]', '["鷄鳴丑，高楼大宅得安久。","常勸父母發慈心，孝得題名終不朽。","（见伯三八二一卷。","原題作「白侍郎作《十二时行孝文》」）。"]', '诗', 'shi', '', NULL, '十二時行孝文 十二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffa3b5fe-ae50-45d9-90d6-cdfff9a52225', '行香子（清涼山文殊讚）', '行香子（清涼山文殊讚）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["文殊菩薩，出化清涼，神通力以（一作「應」）現他方。","真（一作「身」）座金毛師子，微放珠光。","衆生仰持寶蓋，絕名香。","我今發願，虔誠歸命，不求富貴，不戀榮華。","願當來世，生（一作無「世」、「生」二字，下同）淨土，法王家。","願當來世，生淨土，法王家。","（見日本長惠編《魚山詩鈔》，注「一作」者，爲《聲明古調》本之異文。","）。"]', '["文殊菩薩，出化清涼，神通力以（一作「應」）現他方。","真（一作「身」）座金毛師子，微放珠光。","衆生仰持寶蓋，絕名香。","我今發願，虔誠归命，不求富貴，不戀榮华。","願當来世，生（一作無「世」、「生」二字，下同）淨土，法王家。","願當来世，生淨土，法王家。","（见日本长惠編《鱼山诗鈔》，注「一作」者，爲《声明古調》本之異文。","）。"]', '诗', 'shi', '', NULL, '行香子（清涼山文殊讚） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c319582f-9bb1-479a-a0e4-772b5ea8eb1e', '鳥窠和尚贊', '鸟窠和尚贊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["形羸骨瘦久修行，一納麻衣稱道情。","曾結草庵倚碧樹，天涯知有鳥窠名。","（見《祖堂集》卷三）。"]', '["形羸骨瘦久修行，一納麻衣稱道情。","曾結草庵倚碧樹，天涯知有鸟窠名。","（见《祖堂集》卷三）。"]', '诗', 'shi', '', NULL, '鳥窠和尚贊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdf4d99f-fc45-45df-8595-3d7798719749', '贈鳥窠和尚詩（題擬）', '贈鸟窠和尚诗（題擬）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空門有路不知處，頭白齒黃猶念經。","何年飲著聲聞酒，迄至如今醉未醒。","（同前）（按：《全唐詩》卷四五八《戲禮經老僧》與此詩後二句同，前二句全異，未審爲一詩抑爲二詩。","）。"]', '["空门有路不知处，头白齒黄猶念經。","何年饮著声闻酒，迄至如今醉未醒。","（同前）（按：《全唐诗》卷四五八《戲禮經老僧》與此诗後二句同，前二句全異，未審爲一诗抑爲二诗。","）。"]', '诗', 'shi', '', NULL, '贈鳥窠和尚詩（題擬） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65bdbaab-4ac0-43ee-983f-ec89a93a6ee9', '南嶽橫龍寺（題擬）', '南嶽橫龙寺（題擬）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月射冷光新殿宇，風敲清韻古杉松。","問師寶額因何立，笑指橫溪有臥龍。","（見《南嶽總勝集》卷中）。"]', '["月射冷光新殿宇，风敲清韻古杉松。","问師寶額因何立，笑指橫溪有臥龙。","（见《南嶽總勝集》卷中）。"]', '诗', 'shi', '', NULL, '南嶽橫龍寺（題擬） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0834a91c-23f8-4085-af70-95613f4dfb46', '遊紫霄宮七言八句（藏頭拆字詩）', '游紫霄宮七言八句（藏头拆字诗）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水洗塵埃道味甞，甘於於名利相相忘。","心懷天洞丹霞客，各誦三清紫府章。","早裏採蓮歌達旦，一輪明月桂飄香。","日高公子還相覓，見得山中好酒漿。","（見宋桑世昌《回文類聚》卷二引）（按：《回文類聚》收此詩作環行排列，各句首字皆略去。","附《讀法》云：「每句取第一字下半爲起字，從右轉，首句用漿字之下半水字讀起，如『水洗塵埃道味甞，甘於名利兩相忘』是也。","」）。"]', '["水洗塵埃道味甞，甘於於名利相相忘。","心懷天洞丹霞客，各誦三清紫府章。","早裏採蓮歌達旦，一輪明月桂飄香。","日高公子還相覓，见得山中好酒漿。","（见宋桑世昌《回文類聚》卷二引）（按：《回文類聚》收此诗作环行排列，各句首字皆略去。","附《读法》云：「每句取第一字下半爲起字，從右轉，首句用漿字之下半水字读起，如『水洗塵埃道味甞，甘於名利兩相忘』是也。","」）。"]', '诗', 'shi', '', NULL, '遊紫霄宮七言八句（藏頭拆字詩） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe624da0-0812-4a55-a568-241a6563cc42', '讚崔氏夫人（幷序○題擬） 一', '讚崔氏夫人（幷序○題擬） 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亭亭獨步□枝花，紅臉青娥不是誇。","作將喜貌爲愁貌，未慣離家往婿家。"]', '["亭亭独步□枝花，紅臉青娥不是誇。","作將喜貌爲愁貌，未慣離家往婿家。"]', '诗', 'shi', '', NULL, '讚崔氏夫人（幷序○題擬） 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('896ed6be-1ef0-462c-aee0-8409aa87a0c6', '讚崔氏夫人（幷序○題擬） 二', '讚崔氏夫人（幷序○題擬） 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["拜別高堂日欲斜，紅巾拭淚貴新花。","徒來生處却爲客，今日隨夫始是家。","（見《敦煌掇瑣》二○錄伯二六三三卷。","原附《崔氏夫人要女文一本》後，題作「白侍郎讚」。","）。"]', '["拜別高堂日欲斜，紅巾拭泪貴新花。","徒来生处却爲客，今日隨夫始是家。","（见《敦煌掇瑣》二○錄伯二六三三卷。","原附《崔氏夫人要女文一本》後，題作「白侍郎讚」。","）。"]', '诗', 'shi', '', NULL, '讚崔氏夫人（幷序○題擬） 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1adce9a-1ddd-416e-8c95-bc893dc94c73', '采石墓', '采石墓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["采石江邊李白墳，遶田無限草連雲。","可憐荒壠泉骨，曾有驚天動地文。","但是詩人多薄命，就中淪落不過君。","渚蘋溪草猶堪薦，大雅遺風不可聞。","（見《采石志》，轉錄自《李白在安徽》）（按：《全唐詩》卷四四○收本詩，缺末二句，今重錄。","今人或謂末二句係人僞託。","）。"]', '["采石江邊李白墳，遶田無限草連云。","可怜荒壠泉骨，曾有驚天动地文。","但是诗人多薄命，就中淪落不過君。","渚蘋溪草猶堪薦，大雅遺风不可闻。","（见《采石志》，轉錄自《李白在安徽》）（按：《全唐诗》卷四四○收本诗，缺末二句，今重錄。","今人或謂末二句係人僞託。","）。"]', '诗', 'shi', '', NULL, '采石墓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84db7383-dbe0-4951-bd30-57c9cbc0a631', '宿雲門寺', '宿云门寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨夜有風雨，雲奔天地合。","龍吟古石樓，虎嘯層巖閣。","幽意未盡懷，更行三五匝。","（《會稽掇英總集》卷七）。"]', '["昨夜有风雨，云奔天地合。","龙吟古石楼，虎嘯層巖閣。","幽意未尽懷，更行三五匝。","（《會稽掇英總集》卷七）。"]', '诗', 'shi', '', NULL, '宿雲門寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195544c5-56fc-4628-9570-5f749fb1f68d', '會二同年', '會二同年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一樽聊接故人歡，百歲堪嗟鬢漸殘。","莫見白雲容易愛，照湖澄碧四明寒。","（同前卷十三）。"]', '["一樽聊接故人歡，百歲堪嗟鬢漸殘。","莫见白云容易愛，照湖澄碧四明寒。","（同前卷十三）。"]', '诗', 'shi', '', NULL, '會二同年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60795c4-636f-413a-a5bd-c48d1f5cd1e5', '題法華山天衣寺', '題法华山天衣寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山爲蓮宮作畫屏，樓臺迤邐插青冥。","雲生座底鋪金地，風起松梢韻寶鈴。","龍噴水聲連擊罄，猿啼月色閑持經。","時人不信非凡境，試入玄關一夜聽。","（同前卷八。","以上三首參鄒志方《唐詩補錄》收入）。"]', '["山爲蓮宮作畫屏，楼台迤邐插青冥。","云生座底鋪金地，风起松梢韻寶鈴。","龙噴水声連擊罄，猿啼月色闲持經。","时人不信非凡境，試入玄关一夜听。","（同前卷八。","以上三首參鄒志方《唐诗補錄》收入）。"]', '诗', 'shi', '', NULL, '題法華山天衣寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31dec283-f5f2-4267-8ada-1cd63e6c6277', '戲酬皇甫十再勸酒', '戲酬皇甫十再勸酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淨名居士眼方丈，玄晏先生釀老春。","手把屈巵未（疑應作「來」）勸我，世間何處覓波旬？","（前二句見《千載佳句》卷上《人事部·閑放》後二句見卷下《宴喜部·酒》）。"]', '["淨名居士眼方丈，玄晏先生釀老春。","手把屈巵未（疑應作「来」）勸我，世间何处覓波旬？","（前二句见《千載佳句》卷上《人事部·闲放》後二句见卷下《宴喜部·酒》）。"]', '诗', 'shi', '', NULL, '戲酬皇甫十再勸酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f90026d-dc63-43ca-873b-cd3943ca07df', '重陽日（一無「日」字）', '重陽日（一無「日」字）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["敬亭山外人歸遠，峽石溪邊水去斜。","茅屋老妻良釀酒，東籬黃菊任開花。","（前二句見《千載佳句》卷下《別離部·送別》，後二句見《草木部·菊酒》）。"]', '["敬亭山外人归远，峽石溪邊水去斜。","茅屋老妻良釀酒，东籬黄菊任开花。","（前二句见《千載佳句》卷下《別離部·送別》，後二句见《草木部·菊酒》）。"]', '诗', 'shi', '', NULL, '重陽日（一無「日」字） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d914ec1-9b1f-4269-ad42-0497d22ac1ff', '新艷', '新艷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲環獨𢮿細蜻蜓，雪手輕柔玳瑁箏。","飛鴈一行挑玉柱，十三絃上語嚶嚶。","（同上《宴喜部·箏》）。"]', '["云环独𢮿細蜻蜓，雪手轻柔玳瑁箏。","飞鴈一行挑玉柱，十三絃上語嚶嚶。","（同上《宴喜部·箏》）。"]', '诗', 'shi', '', NULL, '新艷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d59da35-b5fc-4559-9c8d-1ad633e69457', '江郎山', '江郎山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["林慮雙童長不食，江郎三子夢還家。","安得此身生羽翼，與君來往共烟霞。","（《古今圖書集成·職方典》卷一○一六《衢州府部》、《山川典》卷一三○《江郎山部》）。"]', '["林慮雙童长不食，江郎三子梦還家。","安得此身生羽翼，與君来往共烟霞。","（《古今圖书集成·職方典》卷一○一六《衢州府部》、《山川典》卷一三○《江郎山部》）。"]', '诗', 'shi', '', NULL, '江郎山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95594407-1603-4581-a2e7-f0231d513152', '題天柱峰', '題天柱峰', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["太微星斗拱瓊宮，聖祖琳宮鎮九垓。","天柱一峰擎日月，洞門千仞鎖雲雷。","玉光白橘相爭秀，金翠佳蓮蕊鬬開。","時訪左慈高隱處，紫清仙鶴認巢來。","（《天柱山志》）（按：《輿地紀勝》收三、四兩句爲南唐李明作，詳本書卷四十四。","）。"]', '["太微星斗拱瓊宮，聖祖琳宮鎮九垓。","天柱一峰擎日月，洞门千仞鎖云雷。","玉光白橘相爭秀，金翠佳蓮蕊鬬开。","时訪左慈高隐处，紫清仙鹤認巢来。","（《天柱山志》）（按：《輿地紀勝》收三、四兩句爲南唐李明作，詳本书卷四十四。","）。"]', '诗', 'shi', '', NULL, '題天柱峰 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6d21b0-6808-4f22-a9fd-3af178e6f3c7', '讚碎金', '讚碎金', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獡頭𧭉趠人難識，瀎𣳡𥏠{矲右爲面}惱家心。","寫向篋中甚敬重，要來一字一{碈右上爲尤}（當即「碎」字）金。"]', '["獡头𧭉趠人难識，瀎𣳡𥏠{矲右爲面}惱家心。","寫向篋中甚敬重，要来一字一{碈右上爲尤}（當即「碎」字）金。"]', '诗', 'shi', '', NULL, '讚碎金 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0661a98d-777c-4802-bc70-92031a5fda5a', '寄盧協律', '寄盧協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿卷玲瓏實碎金，展開無不稱人心。","曉眉歌得白居易，藐䓬盧郎更敢尋。","（二首見敦煌遺書斯六二○四卷，皆署「白侍郎」）。"]', '["满卷玲瓏實碎金，展开無不稱人心。","晓眉歌得白居易，藐䓬盧郎更敢尋。","（二首见敦煌遺书斯六二○四卷，皆署「白侍郎」）。"]', '诗', 'shi', '', NULL, '寄盧協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bedaf9e-8f45-4e4e-896b-5e4479d0c5ba', '登西山望硤石湖', '登西山望硤石湖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["菱歌清唱棹舟迴，樹裏南湖似鑒開。","平障煙浮低落日，出溪路細長新苔。","居民地僻常無事，太守官閑好獨來。","猶憶長安論詩句，至今惆悵獨書臺。","（見《海昌勝蹟志》卷三。","同書引秦瀛語，謂疑出後人附會。","此詩承陶敏先生錄示。","）。"]', '["菱歌清唱棹舟迴，樹裏南湖似鑒开。","平障煙浮低落日，出溪路細长新苔。","居民地僻常無事，太守官闲好独来。","猶憶长安論诗句，至今惆悵独书台。","（见《海昌勝蹟志》卷三。","同书引秦瀛語，謂疑出後人附會。","此诗承陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '登西山望硤石湖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f6ea742-acc5-42d4-9bd2-f19d9cda529f', '和楊同州寒食乾坑會後聞楊工部欲到知予與工部有敷水之期榮喜雖多歡宴且阻辱示長句因而答之', '和楊同州寒食乾坑會後闻楊工部欲到知予與工部有敷水之期榮喜雖多歡宴且阻辱示长句因而答之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往來東道千餘騎，新舊西曹兩侍郎。","（去年兄自工部拜同州，今年弟從常州拜工部。","）家占冬官傳印綬，路逢春日助恩光。","停留五馬經寒食，指點三峰過故鄉。","猶恨乾坑敷水會，差池歸雁不成行。","（見金澤文庫本《白氏文集》卷六五，據朱金城先生《白居易年譜》大和九年譜轉引。","《千載佳句》卷下《宴喜部·宴後》引五、六兩句）。"]', '["往来东道千餘騎，新旧西曹兩侍郎。","（去年兄自工部拜同州，今年弟從常州拜工部。","）家占冬官傳印綬，路逢春日助恩光。","停留五马經寒食，指点三峰過故乡。","猶恨乾坑敷水會，差池归雁不成行。","（见金澤文庫本《白氏文集》卷六五，據朱金城先生《白居易年譜》大和九年譜轉引。","《千載佳句》卷下《宴喜部·宴後》引五、六兩句）。"]', '诗', 'shi', '', NULL, '和楊同州寒食乾坑會後聞楊工部欲到知予與工部有敷水之期榮喜雖多歡宴且阻辱示長句因而答之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e07d59-e313-4b0b-bb89-d9e456d1ea53', '早春閑行', '早春闲行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鸎早乍啼猶冷落，花寒欲發尚遲疑。","（見日本大江維時《千載佳句》卷上《四時部·早春》）。"]', '["鸎早乍啼猶冷落，花寒欲發尚遲疑。","（见日本大江維时《千載佳句》卷上《四时部·早春》）。"]', '诗', 'shi', '', NULL, '早春閑行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f83585-42ca-4405-a81d-6f0c664d7b83', '對酒當歌', '对酒當歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["強來便住無禁老，暗去難留不奈春。","（同上《四時部·送春》）。"]', '["強来便住無禁老，暗去难留不奈春。","（同上《四时部·送春》）。"]', '诗', 'shi', '', NULL, '對酒當歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f4a1a0-4b95-40f1-b0f1-b11d88bfaee5', '早夏閑興', '早夏闲兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["簟冷乍逞新氣味，扇凉重敍舊恩情。","（同上《四時部·首夏》）。"]', '["簟冷乍逞新氣味，扇凉重敍旧恩情。","（同上《四时部·首夏》）。"]', '诗', 'shi', '', NULL, '早夏閑興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff70134-af91-4c85-8a67-2510a31c4f61', '辱牛僕射一札寄詩篇遇物寄懷情', '辱牛僕射一札寄诗篇遇物寄懷情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風雲聚散期難定，魚鳥飛沈勢不同。","（同上《人事部·朋友》）。"]', '["风云聚散期难定，鱼鸟飞沈勢不同。","（同上《人事部·朋友》）。"]', '诗', 'shi', '', NULL, '辱牛僕射一札寄詩篇遇物寄懷情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ef4be7-2295-4148-97f7-8045e674aa04', '辱牛僕射相公一札兼寄三篇寄懷雅意多興味亦以三長句各各繼來意次而和之', '辱牛僕射相公一札兼寄三篇寄懷雅意多兴味亦以三长句各各繼来意次而和之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憂悲欲作煎心火，榮利先爲翳眼塵。","（同上《人事部·感興》）（按：嚴紹盪以上列二首同列後題下，視爲同作三首中之二首，可參考。","今仍分列。","）。"]', '["憂悲欲作煎心火，榮利先爲翳眼塵。","（同上《人事部·感兴》）（按：嚴紹盪以上列二首同列後題下，視爲同作三首中之二首，可參考。","今仍分列。","）。"]', '诗', 'shi', '', NULL, '辱牛僕射相公一札兼寄三篇寄懷雅意多興味亦以三長句各各繼來意次而和之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25638a3-044d-4f0f-982d-edb2ff76a57f', '任氏行 一', '任氏行 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘭膏新沐雲鬢滑，寶釵斜墜青絲髮。"]', '["蘭膏新沐云鬢滑，寶釵斜墜青絲髮。"]', '诗', 'shi', '', NULL, '任氏行 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6715c53-569f-47ae-8e22-249c3f2ee69a', '任氏行 二', '任氏行 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟬鬢尚隨雲勢動，素衣猶帶月光來。","（均見《錦綉萬花谷》卷十七）（按：以上兩聯，《全唐詩續補遺》收作無名氏詩。","）。"]', '["蟬鬢尚隨云勢动，素衣猶带月光来。","（均见《錦綉万花谷》卷十七）（按：以上兩聯，《全唐诗續補遺》收作無名氏诗。","）。"]', '诗', 'shi', '', NULL, '任氏行 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a84606-1209-47a3-80a5-a71f2e9f97f9', '任氏行 三', '任氏行 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["燕脂漠漠桃花淺，青黛微微柳葉新。","（《千載佳句》卷上《人事部·美女》）。"]', '["燕脂漠漠桃花淺，青黛微微柳葉新。","（《千載佳句》卷上《人事部·美女》）。"]', '诗', 'shi', '', NULL, '任氏行 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a52c6e-683a-41be-bcec-749cfc4cd5a8', '任氏行 四', '任氏行 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉爪蒼鷹雲際滅，素牙黃犬草頭飛。","（同書卷下《遊牧部·遊獵》）。"]', '["玉爪蒼鷹云際滅，素牙黄犬草头飞。","（同书卷下《游牧部·游獵》）。"]', '诗', 'shi', '', NULL, '任氏行 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fa5681-b82c-4782-bf0f-666c85532fe6', '閨情', '閨情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙攢錦帳凝還散，風卷羅帷掩更開。","（同書卷上《人事部·艷情》）。"]', '["煙攢錦帳凝還散，风卷羅帷掩更开。","（同书卷上《人事部·艷情》）。"]', '诗', 'shi', '', NULL, '閨情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d3bf65d-c950-4cda-a653-802734cb2709', '木芙蓉', '木芙蓉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚函（一作「涵」）秋霧誰相似，如玉佳人帶酒容。","（同書卷下《草木部·木芙蓉》）。"]', '["晚函（一作「涵」）秋霧誰相似，如玉佳人带酒容。","（同书卷下《草木部·木芙蓉》）。"]', '诗', 'shi', '', NULL, '木芙蓉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03dda0a-84e8-4bfe-b105-92587153f250', '杭州景致', '杭州景致', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["松風碎助潮聲急，竹露零添澗水流。","（同上《草木部·松竹》）。"]', '["松风碎助潮声急，竹露零添澗水流。","（同上《草木部·松竹》）。"]', '诗', 'shi', '', NULL, '杭州景致 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f0c0eb2-2e30-4c70-877f-bc3f0fb95c1f', '春興', '春兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚隨酒客花間散，夜與琴僧月下期。","（同上《宴喜部·琴酒》）。"]', '["晚隨酒客花间散，夜與琴僧月下期。","（同上《宴喜部·琴酒》）。"]', '诗', 'shi', '', NULL, '春興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d0f6d0-8d4a-4ca6-9246-151ace486b6c', '同夢得醉後戲贈', '同梦得醉後戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["唯欠與君同制令（一作「命」），一時封作醉鄉侯。","（同上《宴喜部·醉》）。"]', '["唯欠與君同制令（一作「命」），一时封作醉乡侯。","（同上《宴喜部·醉》）。"]', '诗', 'shi', '', NULL, '同夢得醉後戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad7e4de-0699-4df0-a955-ff817241c7e9', '題新澗亭', '題新澗亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今日望鄉迷處所，猿聲暮雨一時來。","（同上《別離部·旅情》。","原注：「一作劉禹錫《元日登高》」）。"]', '["今日望乡迷处所，猿声暮雨一时来。","（同上《別離部·旅情》。","原注：「一作劉禹錫《元日登高》」）。"]', '诗', 'shi', '', NULL, '題新澗亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e394dd6a-226f-4b74-9260-392f38793604', '贈隱士', '贈隐士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["御風煙眇（一作「渺」）多無伴，入鳥差池不亂羣。","（同上《隱逸部·隱士》）（按：以上所據《千載佳句》，係據日本東京大學藏森鷗外所贈抄本。","此本係由王水照教授影印攜歸。","此本有校錄異文。","《文史》二十三輯刊嚴紹盪同志《日本〈千載佳句〉白居易詩佚句輯稿》，係據金子彥二郎校本，今亦據以參校。","）。"]', '["御风煙眇（一作「渺」）多無伴，入鸟差池不亂羣。","（同上《隐逸部·隐士》）（按：以上所據《千載佳句》，係據日本东京大学藏森鷗外所贈抄本。","此本係由王水照教授影印携归。","此本有校錄異文。","《文史》二十三輯刊嚴紹盪同志《日本〈千載佳句〉白居易诗佚句輯稿》，係據金子彥二郎校本，今亦據以參校。","）。"]', '诗', 'shi', '', NULL, '贈隱士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae7f09f-2f3e-4004-aeae-f8f82ccf76ba', '七夕', '七夕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶得少年長乞巧，竹竿頭上願絲多。","（見《日本古典文學大系》七三冊藤原公任《和漢朗詠集》卷上《七夕》）（〖1〗川口久雄校注云：「《佳句·七夕》題作『《七夕》，白』。","《全唐詩》、《文集》、《全唐詩逸》均未見。","當爲在中國已散逸而在我國流傳下來的白詩斷句。","」）。"]', '["憶得少年长乞巧，竹竿头上願絲多。","（见《日本古典文学大系》七三冊藤原公任《和漢朗詠集》卷上《七夕》）（〖1〗川口久雄校注云：「《佳句·七夕》題作『《七夕》，白』。","《全唐诗》、《文集》、《全唐诗逸》均未见。","當爲在中国已散逸而在我国流傳下来的白诗斷句。","」）。"]', '诗', 'shi', '', NULL, '七夕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930c673e-1ac3-4d69-9d35-1098fb8c874d', '聞裴李二舍人拜綸閣', '闻裴李二舍人拜綸閣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鳳池後面新秋月，龍闕前頭薄暮山。","（見前書卷下《禁中》）（〖1〗川口久雄校注云：「《佳句·早秋》及《禁中》作『白《聞裴李二舍人拜綸閣》』。","私注作『《題東北舊院小亭》，白』。","《文集》及《全唐詩》均未見。","《江談》四作《同裴李文拜綸閣》。","」）。"]', '["鳳池後面新秋月，龙闕前头薄暮山。","（见前书卷下《禁中》）（〖1〗川口久雄校注云：「《佳句·早秋》及《禁中》作『白《闻裴李二舍人拜綸閣》』。","私注作『《題东北旧院小亭》，白』。","《文集》及《全唐诗》均未见。","《江談》四作《同裴李文拜綸閣》。","」）。"]', '诗', 'shi', '', NULL, '聞裴李二舍人拜綸閣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a60d3bd8-27ca-4a1a-83b4-413d3c8c8caf', '別後寄美人', '別後寄美人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫怪紅巾遮面笑，春風吹綻牡丹花。","（見前書卷下《妓女》）（〖1〗川口久雄校注云：「私注作『《別後寄美人》，白』。","《佳句·美女》作『白《春詞》』。","《文集》、《全唐詩》均未見。","」）。"]', '["莫怪紅巾遮面笑，春风吹綻牡丹花。","（见前书卷下《妓女》）（〖1〗川口久雄校注云：「私注作『《別後寄美人》，白』。","《佳句·美女》作『白《春词》』。","《文集》、《全唐诗》均未见。","」）。"]', '诗', 'shi', '', NULL, '別後寄美人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7065a329-2ea3-4606-ad20-75cf343b2b30', '句 一', '句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空夜窗閑螢度後，深更軒白月明初。","（同前書卷上《夏夜》）（〖1〗川口久雄校注：「私注以下諸本作『《夜陰歸房》，紀納言』。","」）。"]', '["空夜窗闲螢度後，深更軒白月明初。","（同前书卷上《夏夜》）（〖1〗川口久雄校注：「私注以下諸本作『《夜陰归房》，紀納言』。","」）。"]', '诗', 'shi', '', NULL, '句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f96cd2de-0665-4856-a7ad-71e9e801e153', '句 二', '句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧浪金波三五初，秋風計會似空虛。","（同前書卷上《十五夜》）（〖1〗川口久雄校注云：「私注作『《月影滿秋池詩》發句，菅淳茂』。","《文粹》八作『《八月十五夜侍亭子院同賦月影滿秋池應太上法皇製》，菅淳茂』。","……底本注作者『白』，似誤。","」）。"]', '["碧浪金波三五初，秋风計會似空虛。","（同前书卷上《十五夜》）（〖1〗川口久雄校注云：「私注作『《月影满秋池诗》發句，菅淳茂』。","《文粹》八作『《八月十五夜侍亭子院同賦月影满秋池應太上法皇製》，菅淳茂』。","……底本注作者『白』，似誤。","」）。"]', '诗', 'shi', '', NULL, '句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('466aad8f-10d8-41f6-bdbf-83cd5a6f4bb1', '句 三', '句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嫌褰錦帳長薰麝，惡卷珠簾晚著釵。","（見前書卷下《妓女》）（〖1〗川口久雄校注：「私注作『《佳人難出》，田達音』。","集注作『《古題》，作者不知。","或云菅三品作』。","底本『白』字疑誤。","」按：以上三聯疑皆非白居易作。","因其出處甚早，仍附存之。","）。"]', '["嫌褰錦帳长薰麝，惡卷珠簾晚著釵。","（见前书卷下《妓女》）（〖1〗川口久雄校注：「私注作『《佳人难出》，田達音』。","集注作『《古題》，作者不知。","或云菅三品作』。","底本『白』字疑誤。","」按：以上三聯疑皆非白居易作。","因其出处甚早，仍附存之。","）。"]', '诗', 'shi', '', NULL, '句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768049ae-c89d-481e-a9bb-8d5ee157197a', '句 四', '句 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["櫻桃樊素口，楊柳小蠻腰。","（《雲溪友議》、《本事詩》）。"]', '["櫻桃樊素口，楊柳小蠻腰。","（《云溪友議》、《本事诗》）。"]', '诗', 'shi', '', NULL, '句 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340af1e8-335d-41fc-ac55-bf06b8c99dd6', '新婦石', '新婦石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["堂堂不語望夫君，四畔無家石作鄰。","蟬鬢一梳千歲髻，蛾眉長掃萬年春。","雪爲輕粉憑風拂，霞作胭脂使日勻。","莫道面前無寶鑑，月來山下照夫人。","（《咸淳臨安志》卷二六。","以下皆轉錄自朱金城先生《白居易集箋校》）。"]', '["堂堂不語望夫君，四畔無家石作鄰。","蟬鬢一梳千歲髻，蛾眉长掃万年春。","雪爲轻粉憑风拂，霞作胭脂使日勻。","莫道面前無寶鑑，月来山下照夫人。","（《咸淳臨安志》卷二六。","以下皆轉錄自朱金城先生《白居易集箋校》）。"]', '诗', 'shi', '', NULL, '新婦石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('929486e4-3b7d-4ca6-bee7-4323547118a6', '西巖山', '西巖山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["千古仙居物象饒，道成丹熟晝昇霄。","巖前寶磬轉松韻，洞口靈池應海潮。","崖折百花遲日晚，鶴歸清夜唳聲遙。","登臨漸到希夷境，手拂行雲度石橋。","（同前卷二七）。"]', '["千古仙居物象饒，道成丹熟晝昇霄。","巖前寶磬轉松韻，洞口靈池應海潮。","崖折百花遲日晚，鹤归清夜唳声遙。","登臨漸到希夷境，手拂行云度石橋。","（同前卷二七）。"]', '诗', 'shi', '', NULL, '西巖山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('462bd017-80bc-49b1-aae8-384f0fa42ada', '懶出', '懶出', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慵遊懶出門多掩，縱暫逢迎不下堂。","不是向人情漸薄，病宜閑靜老宜藏。","（金澤文庫本《白氏文集》卷六八）。"]', '["慵游懶出门多掩，縱暫逢迎不下堂。","不是向人情漸薄，病宜闲静老宜藏。","（金澤文庫本《白氏文集》卷六八）。"]', '诗', 'shi', '', NULL, '懶出 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce808ae4-1b36-469b-8171-bd8701c96458', '聽琵琶勸殷協律酒', '听琵琶勸殷協律酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何堪朔塞胡關曲，又是秋天雨夜聞。","青塚葬時沙莽莽，烏孫愁處雪紛紛。","知君怕病推辭酒，故遣琵琶勸諫君。","（《白氏文集管見抄》）。"]', '["何堪朔塞胡关曲，又是秋天雨夜闻。","青塚葬时沙莽莽，烏孫愁处雪紛紛。","知君怕病推辞酒，故遣琵琶勸諫君。","（《白氏文集管见抄》）。"]', '诗', 'shi', '', NULL, '聽琵琶勸殷協律酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f60575-6d9e-4c2f-b0a4-13f2ca58d718', '歙州山行懷故山', '歙州山行懷故山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悔別故山遠，愁行歸路遲。","雲峯雜滿眼，不當隱淪時。","（同前。","以上四詩皆轉錄自日本花房英樹《白氏文集批判研究》）。"]', '["悔別故山远，愁行归路遲。","云峯杂满眼，不當隐淪时。","（同前。","以上四诗皆轉錄自日本花房英樹《白氏文集批判研究》）。"]', '诗', 'shi', '', NULL, '歙州山行懷故山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d73729fb-bd80-41f1-a302-e1f45734e4be', '贈牛思黯', '贈牛思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百尋竿上擲身難。","（《後山詩注》卷六《送杜擇之》注引）。"]', '["百尋竿上擲身难。","（《後山诗注》卷六《送杜擇之》注引）。"]', '诗', 'shi', '', NULL, '贈牛思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c763bf9-a1ea-4079-a99b-a5289c90ed56', '句 一', '句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慈恩塔下題名處，十七人中最少年。","（《唐遮言》卷三）。"]', '["慈恩塔下題名处，十七人中最少年。","（《唐遮言》卷三）。"]', '诗', 'shi', '', NULL, '句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5651303-6634-4b27-bf68-660b4a59d77b', '句 二', '句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長生不似無生理，休向青山學煉丹。","（《唐詩紀事》卷三八引《詩人主客圖》）。"]', '["长生不似無生理，休向青山学煉丹。","（《唐诗紀事》卷三八引《诗人主客圖》）。"]', '诗', 'shi', '', NULL, '句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a456fd36-4957-4fce-b771-18a8cd1de3ca', '句 三', '句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白髮鑷不盡，根在愁腸中。","（同前）。"]', '["白髮鑷不尽，根在愁腸中。","（同前）。"]', '诗', 'shi', '', NULL, '句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd198983-03c9-4b5c-a67f-122ceb3e9eb4', '句 四', '句 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["生爲漢宮妃，死作胡地鬼。","（《集注分類東坡詩》卷四《昭君村》注引）。"]', '["生爲漢宮妃，死作胡地鬼。","（《集注分類东坡诗》卷四《昭君村》注引）。"]', '诗', 'shi', '', NULL, '句 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f11699-04fb-41df-bb93-2ef100337a6c', '句 五', '句 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢庭重少公何在？（《後山詩注》卷一《次韻答邢居實二首》引）。"]', '["漢庭重少公何在？（《後山诗注》卷一《次韻答邢居實二首》引）。"]', '诗', 'shi', '', NULL, '句 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ee28d3-637e-44ff-8e39-1444eee5e29e', '句 六', '句 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百年青天過鳥翼。","（《山谷詩注》卷九《乞桃花二首》注引）。"]', '["百年青天過鸟翼。","（《山谷诗注》卷九《乞桃花二首》注引）。"]', '诗', 'shi', '', NULL, '句 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87fd5566-9009-47ac-885b-7b48dd6faeec', '句 七', '句 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["園林亦要聞閑置。","（《山谷詩注》卷十四《萬州太守高仲本約遊岑公洞而夜雨連明戲作二首》注引）。"]', '["园林亦要闻闲置。","（《山谷诗注》卷十四《万州太守高仲本約游岑公洞而夜雨連明戲作二首》注引）。"]', '诗', 'shi', '', NULL, '句 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577144df-4f3f-462c-9af1-f0799f492960', '暮宿清凉院', '暮宿清凉院', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["野客閑來日，山房落葉中。","微寒生夜半，積雨向秋終。","證道方離法，安禪不住空。","□迷將覺路，語默在西東。","（影印本《詩淵》第五冊第三七三六頁）。"]', '["野客闲来日，山房落葉中。","微寒生夜半，積雨向秋終。","證道方離法，安禪不住空。","□迷將覺路，語默在西东。","（影印本《诗淵》第五冊第三七三六頁）。"]', '诗', 'shi', '', NULL, '暮宿清凉院 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('667e68ce-40d7-4aba-8326-7684f5dca116', '在端州知家累以九月九日發衡州因寄（題擬）', '在端州知家累以九月九日發衡州因寄（題擬）', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["菊花開日有人逢，知過衡陽迴雁峰。","江樹送秋黃葉少，海天迎遠碧雲重。","音書斷達聽蠻鵲，風水多虞祝媼龍。","想見病身渾不識，自磨青鏡照衰容。","（李紳《追昔遊詩》卷一《逾嶺嶠止荒陬抵高要》詩「雁飛難渡漳江東」句下自注引。","）（按：自注云：「余在南中日，知家累以其年九月九日發衡州，因寄云〖略〗。","」爲後來追述語氣。","今據以擬題。","宣統《高要縣志》擬題爲《移家來端州先寄以詩》，與原注不甚契合。","）。"]', '["菊花开日有人逢，知過衡陽迴雁峰。","江樹送秋黄葉少，海天迎远碧云重。","音书斷達听蠻鵲，风水多虞祝媼龙。","想见病身渾不識，自磨青镜照衰容。","（李紳《追昔游诗》卷一《逾嶺嶠止荒陬抵高要》诗「雁飞难渡漳江东」句下自注引。","）（按：自注云：「余在南中日，知家累以其年九月九日發衡州，因寄云〖略〗。","」爲後来追述語氣。","今據以擬題。","宣統《高要縣志》擬題爲《移家来端州先寄以诗》，與原注不甚契合。","）。"]', '诗', 'shi', '', NULL, '在端州知家累以九月九日發衡州因寄（題擬） 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f391169-0d42-4e9a-ac78-8dd3ea39c040', '再遊應天寺聖母閣', '再游應天寺聖母閣', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["越地靈蹤多少處，伽藍難尚此樓臺。","有時風掣浪聲到，半夜月排山勢來。","極目煙嵐迷遠近，百般花木離塵埃。","可憐光景吟不盡，知我登臨更幾回。","（宋孔延之編《會稽掇英總集》卷八）。"]', '["越地靈蹤多少处，伽藍难尚此楼台。","有时风掣浪声到，半夜月排山勢来。","極目煙嵐迷远近，百般花木離塵埃。","可怜光景吟不尽，知我登臨更幾回。","（宋孔延之編《會稽掇英總集》卷八）。"]', '诗', 'shi', '', NULL, '再遊應天寺聖母閣 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec94a165-bd42-4bab-aef5-24b91b34bd7b', '仙都即事', '仙都即事', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["獨出諸峰表，周圍百丈圓。","千尋雄鎮地，萬仞上擎天。","湖浪動星際，蓮花生日邊。","終當駕雲鶴，絕頂會羣仙。","（光緒《縉雲縣志》卷八）。"]', '["独出諸峰表，周圍百丈圓。","千尋雄鎮地，万仞上擎天。","湖浪动星際，蓮花生日邊。","終當駕云鹤，絕頂會羣仙。","（光緒《縉云縣志》卷八）。"]', '诗', 'shi', '', NULL, '仙都即事 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc85089-c5c2-47c5-a3b1-ab17790a7ad4', '題北峰黃道士草堂', '題北峰黄道士草堂', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["清溪道士紫微仙，暗誦真經北斗前。","壇上獨窺華頂月，霧中潛到羽人天。","飛流夜落銀河水，喬木朝含絳闕煙。","會了浮名休世事，伴君閑種五芝田。","（按：宋林表民《天台前集別編》于楊衡《登紫霄峰贈黃仙師》詩下注：「即李紳所題北峰黃道士也。","」楊詩收入《全唐詩》卷四六五。","）。"]', '["清溪道士紫微仙，暗誦真經北斗前。","壇上独窺华頂月，霧中潛到羽人天。","飞流夜落銀河水，喬木朝含絳闕煙。","會了浮名休世事，伴君闲種五芝田。","（按：宋林表民《天台前集別編》于楊衡《登紫霄峰贈黄仙師》诗下注：「即李紳所題北峰黄道士也。","」楊诗收入《全唐诗》卷四六五。","）。"]', '诗', 'shi', '', NULL, '題北峰黃道士草堂 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('011c65fd-8443-4e65-bf0c-ac4da29ae7dc', '題龍宮寺淨院四上人', '題龙宮寺淨院四上人', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["擁褐梵香四道師，靈山香侶自肩隨。","前期鴈塔應同化，今日龍宮又再期。","炎月護生依寶地，夜燈觀性息禪枝。","東方幾度留車馬，談盡空門習氏知。","（以上二首見宋林師蒧《天台前集》卷中）。"]', '["擁褐梵香四道師，靈山香侶自肩隨。","前期鴈塔應同化，今日龙宮又再期。","炎月護生依寶地，夜灯观性息禪枝。","东方幾度留车马，談尽空门習氏知。","（以上二首见宋林師蒧《天台前集》卷中）。"]', '诗', 'shi', '', NULL, '題龍宮寺淨院四上人 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75383dd4-64f9-42eb-a8e6-63719f4fabc2', '與李頻詩', '與李頻诗', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["鸕鷀山頭片雲晴，揚州城裏見潮生。","（見宋胡仔《苕溪漁隱叢話前集》卷二四《蔡寬夫詩話》引、《嘉定鎮江志》卷二二）（按：《全唐詩》卷一三三李頎《送劉昱》云：「鸕鷀山頭微雨晴，揚州城裏暮潮生。","」與此二句極相似，未詳係蔡氏誤記，抑爲李紳用李頎之成句。","）。"]', '["鸕鷀山头片云晴，揚州城裏见潮生。","（见宋胡仔《苕溪漁隐叢話前集》卷二四《蔡寬夫诗話》引、《嘉定鎮江志》卷二二）（按：《全唐诗》卷一三三李頎《送劉昱》云：「鸕鷀山头微雨晴，揚州城裏暮潮生。","」與此二句極相似，未詳係蔡氏誤記，抑爲李紳用李頎之成句。","）。"]', '诗', 'shi', '', NULL, '與李頻詩 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f38cef-726e-4a92-a562-a585444cf7ad', '句', '句', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["魚驚翠羽金鱗躍，蓮脫紅衣紫菂擢。","（見宋高似孫《剡錄》卷十引）。"]', '["鱼驚翠羽金鱗躍，蓮脫紅衣紫菂擢。","（见宋高似孫《剡錄》卷十引）。"]', '诗', 'shi', '', NULL, '句 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76062958-c3d0-48c1-83cf-acce416d0d17', '芝草（題擬）', '芝草（題擬）', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["靈根盤錯呈天瑞，寶葉蟬聯表地仙。","（見宋陳景沂《全芳備祖後集》卷十一《卉部·芳草》、無名氏《翰苑新書後集》卷十三）。"]', '["靈根盤錯呈天瑞，寶葉蟬聯表地仙。","（见宋陳景沂《全芳備祖後集》卷十一《卉部·芳草》、無名氏《翰苑新书後集》卷十三）。"]', '诗', 'shi', '', NULL, '芝草（題擬） 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1aab49a-f282-448b-9a60-4b3a2312c2a3', '過盱江麻姑山題絕句', '過盱江麻姑山題絕句', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["萬疊峰巒入太清，麻姑從此會方平。","一從燕罷歸何處，寶殿瑤臺空月明。","（見宋趙與虤《娛書堂詩話》卷下）（〖1〗《娛書堂詩話》：「先作『自從』，後於同輩舉似，同輩云：『詩固清矣，自字未穩，當作一字。","』雲服其言。","暨再入山，已爲人改作『一從』矣。","亦可謂一字師。","」）。"]', '["万叠峰巒入太清，麻姑從此會方平。","一從燕罷归何处，寶殿瑤台空月明。","（见宋趙與虤《娛书堂诗話》卷下）（〖1〗《娛书堂诗話》：「先作『自從』，後於同輩舉似，同輩云：『诗固清矣，自字未穩，當作一字。","』云服其言。","暨再入山，已爲人改作『一從』矣。","亦可謂一字師。","」）。"]', '诗', 'shi', '', NULL, '過盱江麻姑山題絕句 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bccfc655-d389-4e02-90a2-0dcb08e4ac84', '贈敬睦助教', '贈敬睦助教', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["禁掖人知連狀薦，國庠官滿一家貧。","清儀都道蓬瀛客，直氣堪爲諫諍臣。","（見宋謝維新《古今合璧事類備要後集》卷四十、宋潘自牧《記纂淵海》卷三二）。"]', '["禁掖人知連狀薦，国庠官满一家貧。","清儀都道蓬瀛客，直氣堪爲諫諍臣。","（见宋謝維新《古今合璧事類備要後集》卷四十、宋潘自牧《記纂淵海》卷三二）。"]', '诗', 'shi', '', NULL, '贈敬睦助教 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9663cec3-ace1-4799-bb53-8f7472a5615e', '江寧詠雪', '江寧詠雪', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["常持皎潔性，終恰艷陽年。","（見《吟窗雜錄》卷三六《續句圖》）。"]', '["常持皎潔性，終恰艷陽年。","（见《吟窗杂錄》卷三六《續句圖》）。"]', '诗', 'shi', '', NULL, '江寧詠雪 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba24b997-4136-4c8b-a0e3-1de6173cc66f', '句', '句', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["煮雪問茶味，當風看鴈門。","（宋高似孫《緯略》卷七）。"]', '["煮雪问茶味，當风看鴈门。","（宋高似孫《緯略》卷七）。"]', '诗', 'shi', '', NULL, '句 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d3e416-2011-4a59-9b70-64af205e239b', '春寒夜宿先天寺無可上人房', '春寒夜宿先天寺無可上人房', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["雙扉檜下開，寄宿石莓苔。","{牆左爲阝}北香風動，城寒散雪來。","收棋想雲夢，罷茗議天台。","同憶前年臘，師初白閣回。","（見《四庫珍本初集》本宋李庚《天台前集》卷七）（按：《全唐詩》卷六四九收此詩爲方干作，文字略異。","今考方干年輩晚於無可，喻鳧則與無可年次相當。","據詩意，似以喻作爲近是。","）。"]', '["雙扉檜下开，寄宿石莓苔。","{牆左爲阝}北香风动，城寒散雪来。","收棋想云梦，罷茗議天台。","同憶前年臘，師初白閣回。","（见《四庫珍本初集》本宋李庚《天台前集》卷七）（按：《全唐诗》卷六四九收此诗爲方干作，文字略異。","今考方干年輩晚於無可，喻鳧則與無可年次相當。","據诗意，似以喻作爲近是。","）。"]', '诗', 'shi', '', NULL, '春寒夜宿先天寺無可上人房 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('923ae8ca-1137-4faa-80cb-dc297a99f7d8', '海上', '海上', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["花留身住越，月遞夢還秦。","（見《海錄碎事》卷十）（按：《全唐詩》卷五四二收此二句，缺題，今重錄。","）。"]', '["花留身住越，月遞梦還秦。","（见《海錄碎事》卷十）（按：《全唐诗》卷五四二收此二句，缺題，今重錄。","）。"]', '诗', 'shi', '', NULL, '海上 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea20b8bf-d2fb-404f-9224-be703d777854', '曹娥廟', '曹娥廟', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["孝女魂兮何所之？故園遺廟兩堪悲。","嶺頭霞散漫涂臉，江口月沈難畫眉。","恨跡未消雲黯黯，愁痕長在浪漪漪。","人間榮謝不迴首，千載波濤喪色絲。","（嘉慶《曹江孝女廟志》卷八《題詠》。","此則承陶敏先生告知。","）。"]', '["孝女魂兮何所之？故园遺廟兩堪悲。","嶺头霞散漫涂臉，江口月沈难畫眉。","恨跡未消云黯黯，愁痕长在浪漪漪。","人间榮謝不迴首，千載波濤喪色絲。","（嘉慶《曹江孝女廟志》卷八《題詠》。","此則承陶敏先生告知。","）。"]', '诗', 'shi', '', NULL, '曹娥廟 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('290f7917-bb21-4fae-bce4-b845951bbf84', '及第日報破東平', '及第日報破东平', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["三十仙人誰得聽，含元殿角管絃聲。","（見《日本古典文學大系》七三冊日人藤原公任一○一八年頃纂《倭漢朗詠集》卷下《禁中》）（按：題據川口久雄校注引家藏私注本補。","）。"]', '["三十仙人誰得听，含元殿角管絃声。","（见《日本古典文学大系》七三冊日人藤原公任一○一八年頃纂《倭漢朗詠集》卷下《禁中》）（按：題據川口久雄校注引家藏私注本補。","）。"]', '诗', 'shi', '', NULL, '及第日報破東平 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfcb053d-1ed4-4885-ba14-127e1ec23b46', '秋夜旅情詩', '秋夜旅情诗', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["枕上用心天未曙，北風吹出禁中鐘。","（《千載佳句》卷上《時節部·閑夜》）。"]', '["枕上用心天未曙，北风吹出禁中鐘。","（《千載佳句》卷上《时節部·闲夜》）。"]', '诗', 'shi', '', NULL, '秋夜旅情詩 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e75435-8d82-43e9-8aec-5d83f22d90cb', '句', '句', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["露寒鍾結乳，風定玉花香。","（《剡錄》卷十）。"]', '["露寒鍾結乳，风定玉花香。","（《剡錄》卷十）。"]', '诗', 'shi', '', NULL, '句 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f528aad-e789-4595-80d1-27afa100b57a', '答廣宣上人', '答廣宣上人', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["延英面奉入春闈，亦選功夫亦選奇。","在治只求金不耗，用心空學秤無私。","龍門變化人皆望，鶯谷飛鳴自有時。","獨喜向公誰是證？彌天大士與新詩。","（見《唐摭言》卷三、《唐詩紀事》卷七二。","）（按：二書皆云此詩爲起會昌放第二牓後答廣宣賀詩作，《唐詩紀事》又錄劉夢得、元微之二人和詩，二人皆前卒。","會昌當爲長慶之誤，此詩作於長慶三年春，詳卞孝萱《劉禹錫年譜》。","《全唐詩》卷三四六以此詩爲王涯作，王涯未曾知貢舉，上舉二書皆明確載爲王起作。","）。"]', '["延英面奉入春闈，亦選功夫亦選奇。","在治只求金不耗，用心空学秤無私。","龙门变化人皆望，鶯谷飞鳴自有时。","独喜向公誰是證？彌天大士與新诗。","（见《唐摭言》卷三、《唐诗紀事》卷七二。","）（按：二书皆云此诗爲起會昌放第二牓後答廣宣賀诗作，《唐诗紀事》又錄劉梦得、元微之二人和诗，二人皆前卒。","會昌當爲长慶之誤，此诗作於长慶三年春，詳卞孝萱《劉禹錫年譜》。","《全唐诗》卷三四六以此诗爲王涯作，王涯未曾知貢舉，上舉二书皆明確載爲王起作。","）。"]', '诗', 'shi', '', NULL, '答廣宣上人 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257c9c3b-988d-40f0-9696-2b9216774c5d', '訾州宴遊', '訾州宴游', '91ed4642-1a5f-4496-b08f-3b04a9540d06', '唐', '["桂林雲物畫漫漫，雨裏花開雨裏殘。","惟有今朝好風景，櫻桃含笑柳眉攢。","（見唐莫休符《桂林風土記》、清汪森輯《粤西詩載》卷二二。","）。"]', '["桂林云物畫漫漫，雨裏花开雨裏殘。","惟有今朝好风景，櫻桃含笑柳眉攢。","（见唐莫休符《桂林风土記》、清汪森輯《粤西诗載》卷二二。","）。"]', '诗', 'shi', '', NULL, '訾州宴遊 楊漢公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b75e10-7ba7-4b6a-bece-57fc46ff7039', '八月十五夜銷樓翫月', '八月十五夜銷楼翫月', '91ed4642-1a5f-4496-b08f-3b04a9540d06', '唐', '["人在虛空月在溪。","（見宋談鑰《嘉泰吳輿志》卷十三「明月樓」條引）（按：詩題中「夏」當作「暑」，宋人諱改。","此句下尚有「溪上玉樓樓上月」一句，爲《全唐詩》卷五一六已收之《明月樓》中句，《嘉泰吳興志》同卷亦引之。","另陣元靚《歲時廣記》卷三錄漢公《九月十五日夜絕句》，與《全唐詩》所收之《明月樓》異文全同。","今輯出此句，與《明月樓》關係尚騅確定。","《明月樓》題爲後人代擬，大約不成問題。","）。"]', '["人在虛空月在溪。","（见宋談鑰《嘉泰吳輿志》卷十三「明月楼」條引）（按：诗題中「夏」當作「暑」，宋人諱改。","此句下尚有「溪上玉楼楼上月」一句，爲《全唐诗》卷五一六已收之《明月楼》中句，《嘉泰吳兴志》同卷亦引之。","另陣元靚《歲时廣記》卷三錄漢公《九月十五日夜絕句》，與《全唐诗》所收之《明月楼》異文全同。","今輯出此句，與《明月楼》关係尚騅確定。","《明月楼》題爲後人代擬，大約不成问題。","）。"]', '诗', 'shi', '', NULL, '八月十五夜銷樓翫月 楊漢公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7d6af8-6231-405d-af80-9662b2fe1cd1', '答樂天見寄履道新小灘詩（題擬）', '答乐天见寄履道新小灘诗（題擬）', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["請向歸仁砌下看。","（見《白氏長慶集》卷三五《贈思黯》題注引）。"]', '["請向归仁砌下看。","（见《白氏长慶集》卷三五《贈思黯》題注引）。"]', '诗', 'shi', '', NULL, '答樂天見寄履道新小灘詩（題擬） 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd74d97d-137f-49b6-97ab-f51023e90c83', '句', '句', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["螢燭多愁對九枝。","（宋蘇頌《蘇魏集》卷十二引《牛僧孺集》）。"]', '["螢燭多愁对九枝。","（宋蘇頌《蘇魏集》卷十二引《牛僧孺集》）。"]', '诗', 'shi', '', NULL, '句 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0f8d14-e16f-4bd9-a246-276bf25e93b0', '句', '句', '0d42cf3b-e63c-48be-beba-109937ef94a7', '唐', '["作官不了却歸來，還是杜陵一男子。","（見《全唐文》卷六九五韋瓘《浯溪題壁記》引）。"]', '["作官不了却归来，還是杜陵一男子。","（见《全唐文》卷六九五韋瓘《浯溪題壁記》引）。"]', '诗', 'shi', '', NULL, '句 韋瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b95920-f049-4b6c-b90d-dc06574bbdbf', '畫桐華鳳扇賦附歌', '畫桐华鳳扇賦附歌', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["東風（一作「青春」）晚兮芳節闌，敷紫華兮蔭碧湍。","美斯鳥（一作「茲禽」）兮類鵷鸞，具體微兮容色丹。","（見《文苑英華》卷一○八、《李文饒別集》卷一。","）。"]', '["东风（一作「青春」）晚兮芳節闌，敷紫华兮蔭碧湍。","美斯鸟（一作「茲禽」）兮類鵷鸾，具體微兮容色丹。","（见《文苑英华》卷一○八、《李文饒別集》卷一。","）。"]', '诗', 'shi', '', NULL, '畫桐華鳳扇賦附歌 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086153b1-cb85-4b60-9213-985f19b837cb', '白芙蓉賦附歌', '白芙蓉賦附歌', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["秋水濶兮秋露濃，盛華落兮歎芙蓉。","菖花紫兮君不識，萍實丹兮君不逢。","想佳人兮密靜處，顏如玉兮無冶容。","（見《李衛公別集》卷一）。"]', '["秋水濶兮秋露濃，盛华落兮歎芙蓉。","菖花紫兮君不識，萍實丹兮君不逢。","想佳人兮密静处，顏如玉兮無冶容。","（见《李衛公別集》卷一）。"]', '诗', 'shi', '', NULL, '白芙蓉賦附歌 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a746c64-4ae0-4f9b-9a8e-ebec4d0243c0', '重臺芙蓉賦附歌', '重台芙蓉賦附歌', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["吳山秀兮煙景媚，因淑女兮感斯瑞。","蓮雖多兮無厥類，蘭徒芳兮何足貴。","人已去兮代不留，獨含情兮託茲地。","（同前）。"]', '["吳山秀兮煙景媚，因淑女兮感斯瑞。","蓮雖多兮無厥類，蘭徒芳兮何足貴。","人已去兮代不留，独含情兮託茲地。","（同前）。"]', '诗', 'shi', '', NULL, '重臺芙蓉賦附歌 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59bccc68-712c-4341-aa0d-d50bd0965a54', '柳栢賦附謠', '柳栢賦附謠', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["楚山側兮秋（一作「湘」）水源，美斯栢兮託幽根，條總翠兮冬轉茂，實垂昧兮秋始蕃，彼變化兮不測焉，知非張緒之精魂。","（見《文苑英華》卷一四五）。"]', '["楚山側兮秋（一作「湘」）水源，美斯栢兮託幽根，條總翠兮冬轉茂，實垂昧兮秋始蕃，彼变化兮不測焉，知非張緒之精魂。","（见《文苑英华》卷一四五）。"]', '诗', 'shi', '', NULL, '柳栢賦附謠 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f21c68f-129c-4e50-95d4-ae8da40668af', '晚下北固山喜松行徑成陰悵然懷古偶題臨江亭', '晚下北固山喜松行徑成陰悵然懷古偶題臨江亭', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["□□□□□，□□□□柳。","□□□□□，□□□□久。","□□□□□，□□□□阜。","自有此山川，於今幾太守？","憶昔蔡與謝，茲焉屢迴首。","□□□□□，□□□□口。","□□□□□，□□□□吼。","□□□□□，□□□□後。","□□□□□，□□□□朽。","□□□□□，□□□□有。","近世二千石，畢公宣化厚。","丞相量納川，平陽氣衝斗。","三賢若時雨，所至躋仁壽。","凜凜君子風，余將千載友。","（丞相謂陸兖公，尚書謂畢隆擇，平陽謂齊詹事澣，三賢皆歷此郡。","）□□□□□，□□□□偶。","□□□□□，□□□□綬。","□□□□□，□□□□茍。","□□□□□，□□□□酒。","□□□□□，多景懸窗牖。","□□□□□，□□□□負。","（詳附按）班劍出妓堂。","（郡城東南有謝公妓院堂遺迹。","○見《嘉定鎮江志》卷十二）（按：「自有」二句、「憶昔」二句見《輿地紀勝》卷七《鎮江府》，題作《遊北固》；「自有」二句、「近世」六句見《野客叢書》卷十七、《嘉定鎮江志》卷十四；自注據《嘉定鎮江志》，《野客叢書》所錄稍異，錄如次：「畢構政事爲開元第一，陸丞相象先、平陽齊澣，三賢皆爲此郡。","」疑已經引錄者改寫；「凜凜」二句及詩題見《嘉定鎮江志》卷十四；「多景」句見《墨莊漫錄》卷四；各韻字據《劉賓客外集》卷七《和浙西李大夫晚下北固山喜松徑成陰悵然懷古偶題臨江亭幷浙東元相公所和〖注：依本韻〗》。","全詩據傳璇琮先生《李德裕年譜》寶曆元年譜考證處理。","《全唐詩》卷四七五據《野客叢書》錄八句及注。","）。"]', '["□□□□□，□□□□柳。","□□□□□，□□□□久。","□□□□□，□□□□阜。","自有此山川，於今幾太守？","憶昔蔡與謝，茲焉屢迴首。","□□□□□，□□□□口。","□□□□□，□□□□吼。","□□□□□，□□□□後。","□□□□□，□□□□朽。","□□□□□，□□□□有。","近世二千石，畢公宣化厚。","丞相量納川，平陽氣衝斗。","三賢若时雨，所至躋仁壽。","凜凜君子风，余將千載友。","（丞相謂陸兖公，尚书謂畢隆擇，平陽謂齊詹事澣，三賢皆歷此郡。","）□□□□□，□□□□偶。","□□□□□，□□□□綬。","□□□□□，□□□□茍。","□□□□□，□□□□酒。","□□□□□，多景懸窗牖。","□□□□□，□□□□負。","（詳附按）班劍出妓堂。","（郡城东南有謝公妓院堂遺迹。","○见《嘉定鎮江志》卷十二）（按：「自有」二句、「憶昔」二句见《輿地紀勝》卷七《鎮江府》，題作《游北固》；「自有」二句、「近世」六句见《野客叢书》卷十七、《嘉定鎮江志》卷十四；自注據《嘉定鎮江志》，《野客叢书》所錄稍異，錄如次：「畢構政事爲开元第一，陸丞相象先、平陽齊澣，三賢皆爲此郡。","」疑已經引錄者改寫；「凜凜」二句及诗題见《嘉定鎮江志》卷十四；「多景」句见《墨莊漫錄》卷四；各韻字據《劉賓客外集》卷七《和浙西李大夫晚下北固山喜松徑成陰悵然懷古偶題臨江亭幷浙东元相公所和〖注：依本韻〗》。","全诗據傳璇琮先生《李德裕年譜》寶曆元年譜考證处理。","《全唐诗》卷四七五據《野客叢书》錄八句及注。","）。"]', '诗', 'shi', '', NULL, '晚下北固山喜松行徑成陰悵然懷古偶題臨江亭 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85c9d56d-6a82-4729-925d-a0b3d93d8ad3', '闕題', '闕題', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["宛轉雙翹釵舉，飄飄翠雲輕楚楚。","映燭看花未敢前，低鬟向人嬌不語。","（見《錦繡萬花谷前集》卷十七《美人》）。"]', '["宛轉雙翹釵舉，飄飄翠云轻楚楚。","映燭看花未敢前，低鬟向人嬌不語。","（见《錦繡万花谷前集》卷十七《美人》）。"]', '诗', 'shi', '', NULL, '闕題 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('320c7126-2f5f-4eb5-a363-9558005e2612', '遊北固 一', '游北固 一', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["南山寂歷風飈發，半夜青崖吐明月。"]', '["南山寂歷风飈發，半夜青崖吐明月。"]', '诗', 'shi', '', NULL, '遊北固 一 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db74de9-8c1b-40fc-ae3c-dcc3fc164302', '遊北固 二', '游北固 二', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["地接三茅嶺，江迎子胥濤。","（《至順鎮江志》作「川迎伍子濤」）。"]', '["地接三茅嶺，江迎子胥濤。","（《至順鎮江志》作「川迎伍子濤」）。"]', '诗', 'shi', '', NULL, '遊北固 二 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19607c8-ff47-4fc0-bccd-3c42fa46eaf2', '遊北固 三', '游北固 三', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["水國逾千里，風帆過萬艘。","（見《輿地紀勝》卷七《鎮江府》。","「地接」二句又見《至順鎮江志》卷七。","）。"]', '["水国逾千里，风帆過万艘。","（见《輿地紀勝》卷七《鎮江府》。","「地接」二句又见《至順鎮江志》卷七。","）。"]', '诗', 'shi', '', NULL, '遊北固 三 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed8fb8b-d590-41c0-ad41-7e0e1ee64fd3', '廬山', '廬山', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["輕煙冒爐峰，飛流灑星灣。","（見《輿地紀勝》卷二五《南康軍》、《記纂淵海》卷十。","）。"]', '["轻煙冒爐峰，飞流灑星灣。","（见《輿地紀勝》卷二五《南康軍》、《記纂淵海》卷十。","）。"]', '诗', 'shi', '', NULL, '廬山 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe94d77d-24f9-44a1-a1f3-69a26af06da4', '贈甘露寺僧道行（題擬）', '贈甘露寺僧道行（題擬）', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["削圓方竹杖，漆却斷紋琴。","（《堯山堂外紀》卷三三）。"]', '["削圓方竹杖，漆却斷紋琴。","（《堯山堂外紀》卷三三）。"]', '诗', 'shi', '', NULL, '贈甘露寺僧道行（題擬） 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebbd5ec6-4059-474d-b310-e539c3bf122d', '句', '句', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["遙思宮苑青春夜，坐得宮人畫詔迴。","（見《海錄碎事》卷十一）。"]', '["遙思宮苑青春夜，坐得宮人畫詔迴。","（见《海錄碎事》卷十一）。"]', '诗', 'shi', '', NULL, '句 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c915290-f695-4837-af1f-94e6554c32e4', '句', '句', 'd7cd585f-f4bd-4c72-9c3b-09e0dd7706d3', '唐', '["當時還見鴈南飛。","（見《吟窗雜錄》卷三五王安石《胡笳十八拍集句》。","王詩收入本集時不注出處。","）。"]', '["當时還见鴈南飞。","（见《吟窗杂錄》卷三五王安石《胡笳十八拍集句》。","王诗收入本集时不注出处。","）。"]', '诗', 'shi', '', NULL, '句 陳商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313cfdde-cf1e-405b-a770-9d9b4130f3a1', '登天姥', '登天姥', '03f45b67-b969-4207-b418-2589aa4a62b1', '唐', '["天姥三重嶺，危途遶峻溪。","水喧無晝夜，雲暗失東西。","問路音難辨，通樵跡易迷。","依稀日將午，何處一聲鷄？","（見孔延之《會稽掇英總集》卷四）。"]', '["天姥三重嶺，危途遶峻溪。","水喧無晝夜，云暗失东西。","问路音难辨，通樵跡易迷。","依稀日將午，何处一声鷄？","（见孔延之《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登天姥 李敬方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf79da6-29db-4ff1-bc32-d1c3e5169cb7', '句', '句', '03f45b67-b969-4207-b418-2589aa4a62b1', '唐', '["相逢不飲空歸去，洞口桃花也笑人。","（見《苕溪漁隱叢話後集》卷十六引《復齋漫錄》引）。"]', '["相逢不饮空归去，洞口桃花也笑人。","（见《苕溪漁隐叢話後集》卷十六引《复斋漫錄》引）。"]', '诗', 'shi', '', NULL, '句 李敬方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b38719e-d225-4047-af32-d1cff885b762', '句', '句', 'd93add19-48bd-4978-b27c-0501386290fb', '唐', '["東風吹曉霜，雪鳥雙雙來。","（見《唐詩紀事》卷六十引張爲《詩人主客圖》）。"]', '["东风吹晓霜，雪鸟雙雙来。","（见《唐诗紀事》卷六十引張爲《诗人主客圖》）。"]', '诗', 'shi', '', NULL, '句 賈馳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('903f3899-900a-493e-a2a2-e1752efa33b4', '寄劉環中秀才', '寄劉环中秀才', 'd838db3e-ec14-4cf8-a69a-2a332d028d42', '唐', '["待醉烏程酒，思斟平望羹。","煙雲金斗暗，苔蘚石尊平。","（見宋程大昌《演繁露續集》卷四引《顧渚茶錄》）。"]', '["待醉烏程酒，思斟平望羹。","煙云金斗暗，苔蘚石尊平。","（见宋程大昌《演繁露續集》卷四引《顧渚茶錄》）。"]', '诗', 'shi', '', NULL, '寄劉環中秀才 張文規 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81756f86-6128-4363-80de-022348cc629d', '郡齋書情', '郡斋书情', 'd838db3e-ec14-4cf8-a69a-2a332d028d42', '唐', '["食有吳興鮓。","（見《嘉泰吳興志》卷十八）。"]', '["食有吳兴鮓。","（见《嘉泰吳兴志》卷十八）。"]', '诗', 'shi', '', NULL, '郡齋書情 張文規 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e6004a-5fac-49bd-90ef-ee1e8437b5b0', '和兵部鄭侍郎省中四松詩', '和兵部鄭侍郎省中四松诗', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["右相歷兵署，四松皆手栽。","斸時驚鶴去，移處帶雲來。","根倍雙桐植，花分八桂開。","生成造化力，長作棟梁材。","豈羨蘭依省，猶嫌栢占臺。","出樓終百尺，入夢已三台。","幽韻和宮漏，餘香度酒杯。","拂冠枝上雪，染履影中苔。","高位相承地，新詩寡和才。","何由比蘿蔓，攀附在條[枚]（枝）。","（從《全唐詩》卷四八八改。","見《文苑英華》卷三二四）（按：《全唐詩》卷四八八收此詩作陶雍詩，係雍陶之誤，今據中華書局影印本《文苑英華》新編目錄移正。","）。"]', '["右相歷兵署，四松皆手栽。","斸时驚鹤去，移处带云来。","根倍雙桐植，花分八桂开。","生成造化力，长作棟梁材。","豈羨蘭依省，猶嫌栢占台。","出楼終百尺，入梦已三台。","幽韻和宮漏，餘香度酒杯。","拂冠枝上雪，染履影中苔。","高位相承地，新诗寡和才。","何由比蘿蔓，攀附在條[枚]（枝）。","（從《全唐诗》卷四八八改。","见《文苑英华》卷三二四）（按：《全唐诗》卷四八八收此诗作陶雍诗，係雍陶之誤，今據中华书局影印本《文苑英华》新編目錄移正。","）。"]', '诗', 'shi', '', NULL, '和兵部鄭侍郎省中四松詩 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0706c97-22e5-4662-88fb-9871fa55e640', '小桃源詩 一', '小桃源诗 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["學山雲頂遍尋遊，煙棹夷猶出簡州。","夜雨借公三日水，秋風送我一蘭舟。"]', '["学山云頂遍尋游，煙棹夷猶出簡州。","夜雨借公三日水，秋风送我一蘭舟。"]', '诗', 'shi', '', NULL, '小桃源詩 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13ef8a0-639e-4c97-ac6a-25d425a68acf', '小桃源詩 二', '小桃源诗 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["二水清渾合，三山錦繡張。","迹況簿書冗，身在水雲鄉。","（見《輿地紀勝》卷一四五《簡州》）。"]', '["二水清渾合，三山錦繡張。","迹況簿书冗，身在水云乡。","（见《輿地紀勝》卷一四五《簡州》）。"]', '诗', 'shi', '', NULL, '小桃源詩 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b041bf9-6e5a-4001-8345-c0d9ba4425a9', '賀王僕射放榜（幷序）', '賀王僕射放榜（幷序）', 'd77376a5-1ab8-43c0-b281-def605726ee0', '唐', '["空（按：《全唐詩》卷五六三收此詩，缺序，今據《唐摭言》卷三補錄之。","）。"]', '["空（按：《全唐诗》卷五六三收此诗，缺序，今據《唐摭言》卷三補錄之。","）。"]', '诗', 'shi', '', NULL, '賀王僕射放榜（幷序） 周墀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d82d35-429f-4282-aab8-438f0c7da171', '缺題 一', '缺題 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["我愛朱處士，三吳居中央。","罷亞百頃稻，西風吹半黃。"]', '["我愛朱处士，三吳居中央。","罷亞百頃稻，西风吹半黄。"]', '诗', 'shi', '', NULL, '缺題 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb7f927-3038-4dc0-90cb-5a668f5747fa', '缺題 二', '缺題 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["我昔造其室，羽儀鸞鶴翔。","交橫碧流上，竹映琴書牀。","出俗無近語，堯舜禹武湯。","（見宋朱長文《吳郡圖經續記》卷下）（按：此詩僅存兩段，未全。","）。"]', '["我昔造其室，羽儀鸾鹤翔。","交橫碧流上，竹映琴书牀。","出俗無近語，堯舜禹武湯。","（见宋朱长文《吳郡圖經續記》卷下）（按：此诗僅存兩段，未全。","）。"]', '诗', 'shi', '', NULL, '缺題 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a846f04-bee6-47ac-81af-749ba31af52c', '貴池亭', '貴池亭', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["倚雲軒檻夏疑秋，下視西江一帶流。","鳥簇晴沙殘照墮，風迴極浦片帆收。","驚濤隱隱遙天際，遠樹微微古岸頭。","祇此登攀心便足，何須箇箇到瀛洲。","（見《古今圖書集成·職方典》卷八一○《池州府部·藝文》）。"]', '["倚云軒檻夏疑秋，下視西江一带流。","鸟簇晴沙殘照墮，风迴極浦片帆收。","驚濤隐隐遙天際，远樹微微古岸头。","祇此登攀心便足，何須箇箇到瀛洲。","（见《古今圖书集成·職方典》卷八一○《池州府部·藝文》）。"]', '诗', 'shi', '', NULL, '貴池亭 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f3beccc-cf8c-4c60-94cc-518373b5d4db', '暮春因遊明月峽故留題', '暮春因游明月峽故留題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["從前聞說真仙景，今日追遊始有因。","滿眼山川流水在，古來靈跡必通神。","（《塵史》卷中）。"]', '["從前闻说真仙景，今日追游始有因。","满眼山川流水在，古来靈跡必通神。","（《塵史》卷中）。"]', '诗', 'shi', '', NULL, '暮春因遊明月峽故留題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4375fa93-dbf3-4cad-87cd-178ba66e2692', '安賢寺', '安賢寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["謝家池上安賢寺，面面松窗對水開。","莫道閉門防俗客，愛閒能有幾人來。","（見民國十三年刊徐乃昌纂《南陵懸志》卷四二）。"]', '["謝家池上安賢寺，面面松窗对水开。","莫道閉门防俗客，愛閒能有幾人来。","（见民国十三年刊徐乃昌纂《南陵懸志》卷四二）。"]', '诗', 'shi', '', NULL, '安賢寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e2287c9-fbfb-4f7c-b7af-f4f8b2843a9a', '玉泉', '玉泉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["山股遙飛泉，泓澄傍巖石。","亂垂寒玉條，碎灑珍珠滴。","澄波涵萬象，明鏡瀉天色。","有時乘月來，賞迹還自適。","（《古今圖書集成·職方典》卷五七四《慶陽府部》）。"]', '["山股遙飞泉，泓澄傍巖石。","亂垂寒玉條，碎灑珍珠滴。","澄波涵万象，明镜瀉天色。","有时乘月来，賞迹還自適。","（《古今圖书集成·職方典》卷五七四《慶陽府部》）。"]', '诗', 'shi', '', NULL, '玉泉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bad75a-0150-4703-818d-9fd78d19986f', '遊盤谷', '游盤谷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["巉巖太行高，其下有幽谷。","環繞兩峰間，盤向廓山腹。","甘泉注肥疇，茂草映修木。","勢阻絶諠譁，巖深易潛伏。","昔人有李愿，築地一居獨。","白鳥依蘆塘，菰花映茅屋。","心怡適所安，憂大反忘慾。","掉頭不肯應，謂我此樂足。","友人韓昌黎，文章驚世俗。","長言貴生毛，落落燦珠玉。","好事買名石，鐫文寄崖隩。","已經三十年，磨滅僅可讀。","我來不復見，命吏廣追逐。","訪知石氏遇，猶畏長官督。","不愛石上字，秋風一砧覆。","易之以千金，復使置巖麓。","從此生光輝，萬古從瞻矚。","（見《古今圖書集成·山川典》卷四八《太行山部》）。"]', '["巉巖太行高，其下有幽谷。","环繞兩峰间，盤向廓山腹。","甘泉注肥疇，茂草映修木。","勢阻絶諠譁，巖深易潛伏。","昔人有李愿，築地一居独。","白鸟依蘆塘，菰花映茅屋。","心怡適所安，憂大反忘慾。","掉头不肯應，謂我此乐足。","友人韓昌黎，文章驚世俗。","长言貴生毛，落落燦珠玉。","好事買名石，鐫文寄崖隩。","已經三十年，磨滅僅可读。","我来不复见，命吏廣追逐。","訪知石氏遇，猶畏长官督。","不愛石上字，秋风一砧覆。","易之以千金，复使置巖麓。","從此生光輝，万古從瞻矚。","（见《古今圖书集成·山川典》卷四八《太行山部》）。"]', '诗', 'shi', '', NULL, '遊盤谷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd618cb7-7326-4eb4-a13d-1ba362f61c65', '走筆送杜十三歸京', '走笔送杜十三归京', 'd4cdcbd0-460a-4e16-bfd7-57896821b7c4', '唐', '["煙鴻上漢聲聲遠，逸驥尋雲步步高。","應笑內兄年六十，郡城閑坐養霜毛。","（見《樊川文集·外集》）（按：此詩自宋時起，即收杜牧名下。","胡震亨《唐音戊籤》一〖《統籤》卷五六二〗云：「按牧之卒年五十，此云六十，或非牧詩也。","」其說是。","岑仲勉先生《唐人行第錄》引後二句詩後云：「如謂內兄指被送者而言，則牧既爲杜十三，其內兄〖即妻兄〗斷不能爲杜十三。","如曰詩題『杜十三』錯誤，亦有疑問，因牧卒時年僅五十一，若牧尚未還京，行年更不及五十，詩苟牧自作，斷不至如此荒唐。","故對此詩之較合理解釋，當是送者乃牧內兄之爲郡守者，後人不求甚解，將此詩混入《樊川集》內也。","」今按：《樊川文集》卷四有《寄內兄和州崔員外十二韻》，知作者即此人。","《全唐詩》卷五二四誤收杜牧名下，今爲移正。","又，杜牧《自撰墓志銘》稱妻裴氏，未言另有崔氏妻。","《樊川文集》卷九有其妻兄裴希顏墓志，希顏仕履未至州牧，姑存疑。","）。"]', '["煙鴻上漢声声远，逸驥尋云步步高。","應笑內兄年六十，郡城闲坐養霜毛。","（见《樊川文集·外集》）（按：此诗自宋时起，即收杜牧名下。","胡震亨《唐音戊籤》一〖《統籤》卷五六二〗云：「按牧之卒年五十，此云六十，或非牧诗也。","」其说是。","岑仲勉先生《唐人行第錄》引後二句诗後云：「如謂內兄指被送者而言，則牧既爲杜十三，其內兄〖即妻兄〗斷不能爲杜十三。","如曰诗題『杜十三』錯誤，亦有疑问，因牧卒时年僅五十一，若牧尚未還京，行年更不及五十，诗苟牧自作，斷不至如此荒唐。","故对此诗之較合理解釋，當是送者乃牧內兄之爲郡守者，後人不求甚解，將此诗混入《樊川集》內也。","」今按：《樊川文集》卷四有《寄內兄和州崔員外十二韻》，知作者即此人。","《全唐诗》卷五二四誤收杜牧名下，今爲移正。","又，杜牧《自撰墓志銘》稱妻裴氏，未言另有崔氏妻。","《樊川文集》卷九有其妻兄裴希顏墓志，希顏仕履未至州牧，姑存疑。","）。"]', '诗', 'shi', '', NULL, '走筆送杜十三歸京 崔□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46db69af-f89f-4929-831d-13b04c128f62', '贈李庠郊居', '贈李庠郊居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["揚子東灣下板橋，密籬迂巷半通橈。","霜鳴郭外深秋月，消到門前半夜潮。","看着竹林成竹筍，別來箕樹長新條。","相逢未語平生意，莫忘傾樽慰寂寥。","（影宋蜀刻本《張承吉文集》卷八）。"]', '["揚子东灣下板橋，密籬迂巷半通橈。","霜鳴郭外深秋月，消到门前半夜潮。","看着竹林成竹筍，別来箕樹长新條。","相逢未語平生意，莫忘傾樽慰寂寥。","（影宋蜀刻本《張承吉文集》卷八）。"]', '诗', 'shi', '', NULL, '贈李庠郊居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23a2a0e-06d8-45f0-8fc5-138a601cdbd4', '春遊東林寺', '春游东林寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一到東林寺，春深景致芳。","（見《吟窗雜錄》卷十二沙門文彧《詩格》）。"]', '["一到东林寺，春深景致芳。","（见《吟窗杂錄》卷十二沙门文彧《诗格》）。"]', '诗', 'shi', '', NULL, '春遊東林寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eed7645-8699-44a1-868a-89c94767adf6', '上牢盆使', '上牢盆使', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["椿兒繞樹春園裏，桂子尋花夜月中。","（見《桂苑叢談》）（按：《全唐詩》卷五一一收二句，缺題，今補出。","）。"]', '["椿兒繞樹春园裏，桂子尋花夜月中。","（见《桂苑叢談》）（按：《全唐诗》卷五一一收二句，缺題，今補出。","）。"]', '诗', 'shi', '', NULL, '上牢盆使 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('707e5b14-fcbb-4596-81f3-c1b16fd45941', '採蓮（一作「花」）', '採蓮（一作「花」）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["常聞浣紗女，復有弄珠姬。","（見《後村大全集》卷一七七《詩話續集》卷一引李康成《玉臺後集》引）（按：《玉臺後集》收詩迄於天寶末，不當收入張祜詩，後村所錄，未詳因何致誤，今姑存此。","）。"]', '["常闻浣紗女，复有弄珠姬。","（见《後村大全集》卷一七七《诗話續集》卷一引李康成《玉台後集》引）（按：《玉台後集》收诗迄於天寶末，不當收入張祜诗，後村所錄，未詳因何致誤，今姑存此。","）。"]', '诗', 'shi', '', NULL, '採蓮（一作「花」） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef602cb6-4ba1-443f-8b7f-18a9e8fb41c8', '李珏白日沖天詩', '李珏白日沖天诗', 'c1a7fcc2-9fdb-4a9b-a90d-f0c61d385561', '唐', '["金字空中見，分明列姓名。","三千功若滿，雲鶴自來迎。","要警貪惏息，將萌寵辱驚。","知之如不怠，霄漢是前程。","（《燈下閑談》卷下《升斗得仙》）（按：詩題中之李珏，爲揚子縣之小販，積功成仙，與作者姓名同。","）。"]', '["金字空中见，分明列姓名。","三千功若满，云鹤自来迎。","要警貪惏息，將萌寵辱驚。","知之如不怠，霄漢是前程。","（《灯下闲談》卷下《升斗得仙》）（按：诗題中之李珏，爲揚子縣之小販，積功成仙，與作者姓名同。","）。"]', '诗', 'shi', '', NULL, '李珏白日沖天詩 李珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5303a75c-4ce7-4d6f-b72b-d55358ea217e', '上李珏相公詩（題擬）', '上李珏相公诗（題擬）', '6f72a786-7f2b-4119-a001-9b2594a675fb', '唐', '["同姓復同名，金書應夢靈。","彼行功已滿，此德政惟馨。","中國爲元老，遙天是昴星。","將知賢相意，不去爲時寧。","（同前）。"]', '["同姓复同名，金书應梦靈。","彼行功已满，此德政惟馨。","中国爲元老，遙天是昴星。","將知賢相意，不去爲时寧。","（同前）。"]', '诗', 'shi', '', NULL, '上李珏相公詩（題擬） 淮南幕吏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dee081a-83b6-40bf-8e26-9184b6514280', '偈', '偈', 'fc98f232-1fd3-4aaa-92f8-42340940b033', '唐', '["不是潙山不是牛，一身兩號實難酬。","離却兩頭應須道，如何道德出常流。","（《五燈會元》卷九）。"]', '["不是潙山不是牛，一身兩號實难酬。","離却兩头應須道，如何道德出常流。","（《五灯會元》卷九）。"]', '诗', 'shi', '', NULL, '偈 靈祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f95f8f2-746c-480c-bba3-6e84abdedf59', '六言玉臺體 一', '六言玉台體 一', 'ae46ff97-80d7-4567-9241-1995fd7b9fbd', '唐', '["梁間舊燕新歸，塞外行人信稀。","高樹繁花漠漠，青樓細雨霏霏。","妾伴待勸寒食，隣姑競擣春衣。","唯有妾顏憔悴，良時獨怨芳菲。"]', '["梁间旧燕新归，塞外行人信稀。","高樹繁花漠漠，青楼細雨霏霏。","妾伴待勸寒食，隣姑競擣春衣。","唯有妾顏憔悴，良时独怨芳菲。"]', '诗', 'shi', '', NULL, '六言玉臺體 一 顧非熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f36e0c-3ec9-453c-95b1-4725c42d4be4', '六言玉臺體 二', '六言玉台體 二', 'ae46ff97-80d7-4567-9241-1995fd7b9fbd', '唐', '["未嫁謂如弄玉，嫁了却似淡容。","小姑眠後飡飯，鵶舅鳴時起舂。","對鏡休梳墮馬，照井暫掠盤龍。","那以在家無事，濃粧閑趁遊蜂。"]', '["未嫁謂如弄玉，嫁了却似淡容。","小姑眠後飡飯，鵶舅鳴时起舂。","对镜休梳墮马，照井暫掠盤龙。","那以在家無事，濃粧闲趁游蜂。"]', '诗', 'shi', '', NULL, '六言玉臺體 二 顧非熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09691823-921f-425a-bff5-2bf9b8e4e3e6', '六言玉臺體 三', '六言玉台體 三', 'ae46ff97-80d7-4567-9241-1995fd7b9fbd', '唐', '["少婦未離本家，新夫已行遼水。","閨中夢覺一身，枕上淚流雙耳。","歲歲長羨鴛鴦，日日虛憐蟢子。","有女莫嫁將軍，可惜蛾眉愁死。","（影印本《詩淵》第六冊第四一三九頁）。"]', '["少婦未離本家，新夫已行遼水。","閨中梦覺一身，枕上泪流雙耳。","歲歲长羨鴛鴦，日日虛怜蟢子。","有女莫嫁將軍，可惜蛾眉愁死。","（影印本《诗淵》第六冊第四一三九頁）。"]', '诗', 'shi', '', NULL, '六言玉臺體 三 顧非熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ea432b-c263-4a8e-82e8-43d54703d2ef', '入雲門五雲溪上作（六言）', '入云门五云溪上作（六言）', 'ae46ff97-80d7-4567-9241-1995fd7b9fbd', '唐', '["舟泊有時垂釣，舟行不廢閑吟。","沿山寺寺花樹，枕水家家竹林。","鴛鴦晝飛溪靜，鸜鵒夜轉村深。","忽聞風動蓮葉，起見波間月沉。","（《會稽掇英總集》卷八）（按：《會稽棳英總集》卷六收非熊《宿雲門寺》，《全唐詩》卷五八二作溫庭筠詩，卷五一○作張祜詩，題均作《題造微禪師院》。","《茅山志》卷二八收非熊《贈茅山高拾遺》，《全唐詩》卷五○六作章孝標詩。","孰作尚難確定，姑附識於此。","）。"]', '["舟泊有时垂釣，舟行不廢闲吟。","沿山寺寺花樹，枕水家家竹林。","鴛鴦晝飞溪静，鸜鵒夜轉村深。","忽闻风动蓮葉，起见波间月沉。","（《會稽掇英總集》卷八）（按：《會稽棳英總集》卷六收非熊《宿云门寺》，《全唐诗》卷五八二作溫庭筠诗，卷五一○作張祜诗，題均作《題造微禪師院》。","《茅山志》卷二八收非熊《贈茅山高拾遺》，《全唐诗》卷五○六作章孝標诗。","孰作尚难確定，姑附識於此。","）。"]', '诗', 'shi', '', NULL, '入雲門五雲溪上作（六言） 顧非熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f9ff2d-9c32-4690-a479-baeb4889dda1', '西明寺合歡牡丹', '西明寺合歡牡丹', 'ae46ff97-80d7-4567-9241-1995fd7b9fbd', '唐', '["綠莖同本兩花蓮，似證分身色相圓。","黃藥鬬香欺瑞麥，檀葩幷秀掩嘉蓮。","奏開祥瑞來天使，折去芳枝到御筵。","想得六宮人盡愛，幾多纖指遞相傳。","（影印本《詩淵》第四冊第二三八○頁）。"]', '["綠莖同本兩花蓮，似證分身色相圓。","黄藥鬬香欺瑞麦，檀葩幷秀掩嘉蓮。","奏开祥瑞来天使，折去芳枝到御筵。","想得六宮人尽愛，幾多纖指遞相傳。","（影印本《诗淵》第四冊第二三八○頁）。"]', '诗', 'shi', '', NULL, '西明寺合歡牡丹 顧非熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ebc52a-00c2-4f47-a7fa-c68b7c1396c8', '贈舍弟', '贈舍弟', '2a54e180-bff3-4973-9401-fec88f65d377', '唐', '["秦雲蜀浪兩堪愁，爾養晨昏我遠遊。","千里客心難寄夢，兩行鄉淚爲君流。","早驅風雨知龍聖，餓食魚蝦覺虎羞。","袖裏鏌鋣光似水，丈夫不合等閑休。","（《才調集》卷九）（按：《全唐詩》卷五六四誤收此詩於宇兄牢名下，今爲改正重錄。","）。"]', '["秦云蜀浪兩堪愁，爾養晨昏我远游。","千里客心难寄梦，兩行乡泪爲君流。","早驱风雨知龙聖，餓食鱼蝦覺虎羞。","袖裏鏌鋣光似水，丈夫不合等闲休。","（《才調集》卷九）（按：《全唐诗》卷五六四誤收此诗於宇兄牢名下，今爲改正重錄。","）。"]', '诗', 'shi', '', NULL, '贈舍弟 楊宇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb1f00e-d3b0-4884-af65-be3f807233c7', '遊雲門', '游云门', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["五雲溪影裏，萬慮淡涼天。","紅葉斜堦日，清風滿寺蟬。","幾多長道路，一餉暫留連。","惜別疎鐘去，看山坐水邊。","（見《會稽掇英總集》卷六）。"]', '["五云溪影裏，万慮淡涼天。","紅葉斜堦日，清风满寺蟬。","幾多长道路，一餉暫留連。","惜別疎鐘去，看山坐水邊。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '遊雲門 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551f725e-1c77-485f-9e93-5a4d10b8aeb6', '贈陳處士', '贈陳处士', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["鈎捐煙江風艇在，雨依山酒夜琴橫。","（《千載佳句》卷下《隱逸部·幽居》）。"]', '["鈎捐煙江风艇在，雨依山酒夜琴橫。","（《千載佳句》卷下《隐逸部·幽居》）。"]', '诗', 'shi', '', NULL, '贈陳處士 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a6c6ff-81bb-444b-a7f4-bf8a119db898', '陪盧侍御訪廬山元處士', '陪盧侍御訪廬山元处士', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["望臘早花緣路見，隋巖寒水隔夢聞。","（《千載佳句》卷上《四時部·歲暮》）。"]', '["望臘早花緣路见，隋巖寒水隔梦闻。","（《千載佳句》卷上《四时部·歲暮》）。"]', '诗', 'shi', '', NULL, '陪盧侍御訪廬山元處士 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f9b082-1cfa-46ed-92fe-04592dd4ecec', '句', '句', '7958783a-d3f8-4c34-b561-96bbe7c6fa3d', '唐', '["暗遞花香入客衣。","（《江湖小集》卷六紹嵩《江浙紀行集句詩》）。"]', '["暗遞花香入客衣。","（《江湖小集》卷六紹嵩《江浙紀行集句诗》）。"]', '诗', 'shi', '', NULL, '句 崔涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c1bb49-faa5-438c-95f2-d41590b4e75f', '', '', '7e72961d-d32d-4613-9a6d-5b0e768d899a', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 希運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db53b19-2db5-42c9-a0fa-8f32ba65faf8', '答裴相國休', '答裴相国休', '7e72961d-d32d-4613-9a6d-5b0e768d899a', '唐', '["心如大海無邊際，口吐紅蓮養病身。","雖有一雙無事手，不曾只揖等閑人。","（《黃蘖斷際禪師宛陵錄》、《天聖廣燈錄》卷八。","）。"]', '["心如大海無邊際，口吐紅蓮養病身。","雖有一雙無事手，不曾只揖等闲人。","（《黄蘖斷際禪師宛陵錄》、《天聖廣灯錄》卷八。","）。"]', '诗', 'shi', '', NULL, '答裴相國休 希運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd0b740-d087-4b8a-8123-1771a85c040a', '同觀察使張公仲方大和元年夏禱雨歸至聖泉寺作（題擬）', '同观察使張公仲方大和元年夏禱雨归至聖泉寺作（題擬）', '3c13c090-c22b-45cc-b589-0c760f59e11a', '唐', '["旌斾憂民至，風雲逐馬（《閩都記》作「雨」）來。","（見《淳熙三山志》卷八、《閩都記》卷十一。","）。"]', '["旌斾憂民至，风云逐马（《閩都記》作「雨」）来。","（见《淳熙三山志》卷八、《閩都記》卷十一。","）。"]', '诗', 'shi', '', NULL, '同觀察使張公仲方大和元年夏禱雨歸至聖泉寺作（題擬） 李貽孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6616f48-f213-49a4-a934-ea5b6d13b7ea', '', '', '10ec2948-cf6b-4d7e-98f1-8ee799cc4df5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a99db53e-2972-4b9d-ab23-4923f15ebbe8', '宿雲門香閣院', '宿云门香閣院', '10ec2948-cf6b-4d7e-98f1-8ee799cc4df5', '唐', '["香閣無塵雪後天，石盆如月貯寒泉。","高僧洗足南軒罷，還枕蒲團就日眠。","（見《會稽掇英總集》卷六）。"]', '["香閣無塵雪後天，石盆如月貯寒泉。","高僧洗足南軒罷，還枕蒲團就日眠。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '宿雲門香閣院 李褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b58362e-3f38-422c-8669-d65c7e24521b', '醉石', '醉石', 'fc2862a8-d8a8-4b72-b8de-09c253480688', '唐', '["山南山北鬱嵯峨，千古聲名保不磨，笑入醉鄉聊偃臥，我臨苔石重摩挲。","（見影印天一閣藏《正德南康府志》卷十）。"]', '["山南山北鬱嵯峨，千古声名保不磨，笑入醉乡聊偃臥，我臨苔石重摩挲。","（见影印天一閣藏《正德南康府志》卷十）。"]', '诗', 'shi', '', NULL, '醉石 張固 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82772ae-376a-4520-ab32-29db44a8eab0', '東林寺', '东林寺', 'fc2862a8-d8a8-4b72-b8de-09c253480688', '唐', '["鹿石曉寒雲漠漠，虎溪春淺水潺潺。","（見《輿地紀勝》卷三十《江州》）。"]', '["鹿石晓寒云漠漠，虎溪春淺水潺潺。","（见《輿地紀勝》卷三十《江州》）。"]', '诗', 'shi', '', NULL, '東林寺 張固 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a26710-dffb-4ba1-88f6-e62bab096562', '筍（題擬）', '筍（題擬）', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昨夜春霞迸蘚根，亂披煙籜出柴門。","稚川龍過應迴首，認得青青幾代孫。","（見《全芳備祖後集》卷二三）。"]', '["昨夜春霞迸蘚根，亂披煙籜出柴门。","稚川龙過應迴首，認得青青幾代孫。","（见《全芳備祖後集》卷二三）。"]', '诗', 'shi', '', NULL, '筍（題擬） 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1195963-da06-4837-99fa-9255c1f70c84', '句', '句', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["斜倚綠窗□□□。","（見李壁《王荆文公詩箋注》卷三五《金陵懷古》注引）。"]', '["斜倚綠窗□□□。","（见李壁《王荆文公诗箋注》卷三五《金陵懷古》注引）。"]', '诗', 'shi', '', NULL, '句 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e717ae8-fa0e-4a19-b356-3d6f53d199ae', '贈方干', '贈方干', '8285d0c3-e3a4-4fe4-b391-7f65eac897cc', '唐', '["弟子已折桂，先生猶灌園。","（見王定保《唐摭言》卷四）（〖1〗《摭言》云：「李頻師方干，後頻及第，詩僧清越贈干詩云〖略〗。","」《全唐詩》卷六五三誤將二句收歸方干，題作《寄李頻及第》，今改正。","又：《全唐詩》卷八二九據《禪月集》卷八收貫休《贈方干》一首，其三、四句云：「弟子已得桂，先生猶灌園。","」與清越二句幾全同。","考李頻爲大中八年進士，《全唐文》收清越一文，大中十三年作，時正相合。","疑貫休同清越句入詩以贈方干，或清越爲貫休早年所用之法名，識此俟考詳。","）。"]', '["弟子已折桂，先生猶灌园。","（见王定保《唐摭言》卷四）（〖1〗《摭言》云：「李頻師方干，後頻及第，诗僧清越贈干诗云〖略〗。","」《全唐诗》卷六五三誤將二句收归方干，題作《寄李頻及第》，今改正。","又：《全唐诗》卷八二九據《禪月集》卷八收貫休《贈方干》一首，其三、四句云：「弟子已得桂，先生猶灌园。","」與清越二句幾全同。","考李頻爲大中八年進士，《全唐文》收清越一文，大中十三年作，时正相合。","疑貫休同清越句入诗以贈方干，或清越爲貫休早年所用之法名，識此俟考詳。","）。"]', '诗', 'shi', '', NULL, '贈方干 清越 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a5e3db9-d0c9-489a-8a5b-8675e56d6afe', '浮雲宮', '浮云宮', '96501b87-8402-4005-82bc-230fa1c0d2df', '唐', '["道人西蜀來，自謂八萬歲。","愛此華林幽，穴居聊避世。","真風度萬劫，神仙邈相繼。","靈岫摩天空，鳥道入雲際。","石罅紫苔封，泉泓墨龍憇。","碧桃花未開，白鹿跡已逝。","春風撼山館，急雪舞林底。","滌除衣上塵，刮盡眼中瞖。","何當贈刀圭，豈復便俗吏。","吾不學李寬，盜名職嘲戲。","（見影印文淵閣《四庫全書》本《江西通志》卷一四七、同治十二年刊蕭浚蘭纂《瑞州府志》卷二一。","）。"]', '["道人西蜀来，自謂八万歲。","愛此华林幽，穴居聊避世。","真风度万劫，神仙邈相繼。","靈岫摩天空，鸟道入云際。","石罅紫苔封，泉泓墨龙憇。","碧桃花未开，白鹿跡已逝。","春风撼山館，急雪舞林底。","滌除衣上塵，刮尽眼中瞖。","何當贈刀圭，豈复便俗吏。","吾不学李寬，盜名職嘲戲。","（见影印文淵閣《四庫全书》本《江西通志》卷一四七、同治十二年刊蕭浚蘭纂《瑞州府志》卷二一。","）。"]', '诗', 'shi', '', NULL, '浮雲宮 宣宗皇帝李忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6df4688-9e3f-4a77-828a-cbb12682199f', '悼鹽官和尚（題擬《祖庭事苑》擬。《海昌勝蹟志》題作《悟空塔》）', '悼鹽官和尚（題擬《祖庭事苑》擬。《海昌勝蹟志》題作《悟空塔》）', '96501b87-8402-4005-82bc-230fa1c0d2df', '唐', '["像季何（一作「誰」）教禍所鍾，釋門光彩喪驪龍。","香階懶踏初生草，抵掌悲（一作「蕙帳愁」）看舊日容。","玉柄永雖（一作「辭」）三教座，金鳴（一作「銘」）長鎮萬年蹤。","知師下界因緣盡，應（一作「却」）上諸天第幾重？","（見宋僧善卿《祖庭事苑》卷二。","注「一作」者爲《海昌勝蹟志》卷一〖承陶敏先生告〗之異文。","）。"]', '["像季何（一作「誰」）教禍所鍾，釋门光彩喪驪龙。","香階懶踏初生草，抵掌悲（一作「蕙帳愁」）看旧日容。","玉柄永雖（一作「辞」）三教座，金鳴（一作「銘」）长鎮万年蹤。","知師下界因緣尽，應（一作「却」）上諸天第幾重？","（见宋僧善卿《祖庭事苑》卷二。","注「一作」者爲《海昌勝蹟志》卷一〖承陶敏先生告〗之異文。","）。"]', '诗', 'shi', '', NULL, '悼鹽官和尚（題擬《祖庭事苑》擬。《海昌勝蹟志》題作《悟空塔》） 宣宗皇帝李忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae059a03-2497-4781-9256-e3428d3c8f6d', '送崔鉉赴淮南', '送崔鉉赴淮南', '96501b87-8402-4005-82bc-230fa1c0d2df', '唐', '["今遣股肱親養治，一方獄市獲來蘇。","（《金華子雜編》卷上）（按：《全唐詩》卷四收此詩，前一句完全不同，故重錄。","此承陶先生告知。","）。"]', '["今遣股肱親養治，一方獄市獲来蘇。","（《金华子杂編》卷上）（按：《全唐诗》卷四收此诗，前一句完全不同，故重錄。","此承陶先生告知。","）。"]', '诗', 'shi', '', NULL, '送崔鉉赴淮南 宣宗皇帝李忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd81dca-be65-41f9-abf1-6c5ea3db7c19', '題天乙山寺', '題天乙山寺', '96501b87-8402-4005-82bc-230fa1c0d2df', '唐', '["門前山水丹青譜，洞裏乾坤蓬島圖。","（道光《奉新懸志》，轉錄自《文學遺產》一九八七年第二期刊謝先模文。","）。"]', '["门前山水丹青譜，洞裏乾坤蓬島圖。","（道光《奉新懸志》，轉錄自《文学遺產》一九八七年第二期刊謝先模文。","）。"]', '诗', 'shi', '', NULL, '題天乙山寺 宣宗皇帝李忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb77f60-0f2e-4db9-98fe-8dabbd58dc79', '還丹口訣', '還丹口訣', 'd8ca07de-dd7d-4518-a512-74e879553ba4', '唐', '["世上喧喧車馬人，紅顏綠鬢不長春。","藥術相傳萬甲子，學者茫茫尋不真。","尋不真，莫生嗔，蓋爲黃芽不得真。","鉛是鉛，汞是汞，世上之人總錯用。","草黃芽，木黃芽，世上聞說也亂誇。","自古口傳不形紙，燒者徒勞盡破家。","堪分付，遞相傳，固濟元來此道門。","妄傳非人遭殃禍，父子麤疎不合言。","黑服硫黃燒不煙，餌之中壽幾千年。","更加金室乾坤內，脫世浮空得飛仙。","（《大還丹照鑑》）。"]', '["世上喧喧车马人，紅顏綠鬢不长春。","藥術相傳万甲子，学者茫茫尋不真。","尋不真，莫生嗔，蓋爲黄芽不得真。","鉛是鉛，汞是汞，世上之人總錯用。","草黄芽，木黄芽，世上闻说也亂誇。","自古口傳不形紙，燒者徒勞尽破家。","堪分付，遞相傳，固濟元来此道门。","妄傳非人遭殃禍，父子麤疎不合言。","黑服硫黄燒不煙，餌之中壽幾千年。","更加金室乾坤內，脫世浮空得飞仙。","（《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹口訣 軒轅集 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1caa0ef8-3109-4d98-9d04-6560c0e2127c', '簡知舉陳商（題擬）', '簡知舉陳商（題擬）', 'ae215308-6b3d-4549-9949-abeaf1864ae7', '唐', '["中丞爲國拔英（《全唐詩》作「賢」）才，寒畯（《全唐詩》作「俊」）欣逢藻鑑開。","九朶蓮花秋浦隔，兩枝丹桂一時開。","（《登科記考》卷二二引《永樂大典》引《秋浦新志》。","此詩承湯華泉同志錄示。","）（按：《全唐詩》卷七九五僅存此詩之前二句。","）。"]', '["中丞爲国拔英（《全唐诗》作「賢」）才，寒畯（《全唐诗》作「俊」）欣逢藻鑑开。","九朶蓮花秋浦隔，兩枝丹桂一时开。","（《登科記考》卷二二引《永乐大典》引《秋浦新志》。","此诗承湯华泉同志錄示。","）（按：《全唐诗》卷七九五僅存此诗之前二句。","）。"]', '诗', 'shi', '', NULL, '簡知舉陳商（題擬） 高元裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c0dbcb-4b72-4e9b-83a8-c9290b9f94c6', '句', '句', '125cece1-6fdf-4b44-a82b-76c46de9c38e', '唐', '["芙蓉點露一枝開。","（胡偉《宮詞》）。"]', '["芙蓉点露一枝开。","（胡偉《宮词》）。"]', '诗', 'shi', '', NULL, '句 南卓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0bb6e0-ad84-43b3-9f53-de838ba7e915', '寄剡谿友', '寄剡谿友', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["歇馬亭西酒一巵，半年閒事亦堪悲。","船橫鏡水人眠後，蓼暗松江雁下時。","山晚迥尋蕭寺宿，雪寒誰與戴家期。","夜來忽覺秋風急，應有鱸魚觸釣絲。","（見宋高似孫《剡錄》卷六）。"]', '["歇马亭西酒一巵，半年閒事亦堪悲。","船橫镜水人眠後，蓼暗松江雁下时。","山晚迥尋蕭寺宿，雪寒誰與戴家期。","夜来忽覺秋风急，應有鱸鱼觸釣絲。","（见宋高似孫《剡錄》卷六）。"]', '诗', 'shi', '', NULL, '寄剡谿友 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9bd24e7-362e-420b-b8fd-3f41ea42dea9', '泉', '泉', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["飛下數千尺，全然無定形。","霓橫天日射，龍出石雲腥。","壯勢春曾看，寒聲佛共聽。","昔人云此水，洗目最能醒。","（見《宛委別藏》本《分門纂類唐宋時賢千家詩選》卷十五）。"]', '["飞下數千尺，全然無定形。","霓橫天日射，龙出石云腥。","壯勢春曾看，寒声佛共听。","昔人云此水，洗目最能醒。","（见《宛委別藏》本《分门纂類唐宋时賢千家诗選》卷十五）。"]', '诗', 'shi', '', NULL, '泉 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8030205-646a-44da-b018-cc8d100f392f', '臨終偈', '臨終偈', 'c25426a3-50db-42d5-865d-e444a4f659bf', '唐', '["舉手攀南斗，迴身倚北辰。","出頭天外見（《五燈會元》作「看」），誰是我般人？","（見《景德傳燈錄》卷十、《五燈會元》卷四）。"]', '["舉手攀南斗，迴身倚北辰。","出头天外见（《五灯會元》作「看」），誰是我般人？","（见《景德傳灯錄》卷十、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '臨終偈 智通 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de90c665-e201-4f3f-bea6-17d07877abb8', '題東林寺 一', '題东林寺 一', '67fcac3c-42a7-487c-97dc-860e4615a932', '唐', '["大中天子海恩深，再使迷徒識佛心。","半死白蓮初降[雨]（雲）（從《殷禮在斯堂叢書》本改），欲成荒地又鋪金。","僧開石室經猶在，虎印溪泉跡未沉。","誰謂五湖書劍客，此生重得見東林。"]', '["大中天子海恩深，再使迷徒識佛心。","半死白蓮初降[雨]（云）（從《殷禮在斯堂叢书》本改），欲成荒地又鋪金。","僧开石室經猶在，虎印溪泉跡未沉。","誰謂五湖书劍客，此生重得见东林。"]', '诗', 'shi', '', NULL, '題東林寺 一 周碏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27817210-5ed8-42a1-b39f-270ff6076142', '題東林寺 二', '題东林寺 二', '67fcac3c-42a7-487c-97dc-860e4615a932', '唐', '["再崇玄法象西天，宏閈新高碧嶂前。","風送片雲招白馬，鶴迎貧女誘金錢。","沙門覓佛曾諳路，苦海悲人易得船。","三教共興談帝道，大中年是太平年。","（見《吉石盦叢書》影宋本陳舜俞《廬山記》卷四，原署：「布衣周碏」。","）。"]', '["再崇玄法象西天，宏閈新高碧嶂前。","风送片云招白马，鹤迎貧女誘金錢。","沙门覓佛曾諳路，苦海悲人易得船。","三教共兴談帝道，大中年是太平年。","（见《吉石盦叢书》影宋本陳舜俞《廬山記》卷四，原署：「布衣周碏」。","）。"]', '诗', 'shi', '', NULL, '題東林寺 二 周碏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1b17d3-6eef-4cf9-a6e9-f5e0d828cb1d', '巢父井三絕 一', '巢父井三絕 一', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["巢山終古灑清風，四海輕於脫[屣]（徙）中。","留此一泓來者見，蝸牛角上少爭雄。"]', '["巢山終古灑清风，四海轻於脫[屣]（徙）中。","留此一泓来者见，蝸牛角上少爭雄。"]', '诗', 'shi', '', NULL, '巢父井三絕 一 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b810efc6-a44a-4d91-b2c0-2f8dacdec15c', '巢父井三絕 二', '巢父井三絕 二', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["深沉千尺湛寒泉，來往無私施不偏，愧我扶衰酌靈液，誰知真煖發丹田。"]', '["深沉千尺湛寒泉，来往無私施不偏，愧我扶衰酌靈液，誰知真煖發丹田。"]', '诗', 'shi', '', NULL, '巢父井三絕 二 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e01e38-ce1f-4929-99bc-a957ca457bb1', '巢父井三絕 三', '巢父井三絕 三', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["高名已與白日連，遺迹猶聞故老傳。","吊古每來荒廟下，落花流水總依然。","（見影印天一閣藏《正德汝州志》卷七）（按：詩下原署：「韓琮，員外郎。","」）。"]', '["高名已與白日連，遺迹猶闻故老傳。","吊古每来荒廟下，落花流水總依然。","（见影印天一閣藏《正德汝州志》卷七）（按：诗下原署：「韓琮，員外郎。","」）。"]', '诗', 'shi', '', NULL, '巢父井三絕 三 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc817a43-c10c-43a7-bd34-98b83501cc67', '遊香山寺', '游香山寺', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["信馬盤桓上碧穹，雲埋松翠梵王宮。","老僧細說禪機話，深會菩提色即空。","（同前）（按：詩下原署：「宋韓琮，員外郎。","」檢宋人傳記專書，未聞有韓琮其人。","唐之韓琮，嘗官司封員外郎，任陳許節度判官，官職既合，汝州亦其曾到之地，作宋人誤。","）。"]', '["信马盤桓上碧穹，云埋松翠梵王宮。","老僧細说禪機話，深會菩提色即空。","（同前）（按：诗下原署：「宋韓琮，員外郎。","」檢宋人傳記專书，未闻有韓琮其人。","唐之韓琮，嘗官司封員外郎，任陳許節度判官，官職既合，汝州亦其曾到之地，作宋人誤。","）。"]', '诗', 'shi', '', NULL, '遊香山寺 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a24daa-d042-43c1-a1c8-b90aa637d6c8', '句', '句', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["昨夜小園春已老。","（《江湖小集》卷二十李龏《梅花衲》引）。"]', '["昨夜小园春已老。","（《江湖小集》卷二十李龏《梅花衲》引）。"]', '诗', 'shi', '', NULL, '句 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56a1c84-8f02-4bac-b3ce-c4b8f473f5a1', '寄獨孤處士', '寄独孤处士', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["林下別多年，相逢事渺然。","扁舟浙水上，輕策剡山前。","坐石吟杉月，眠雲憶島仙。","何期歸太白，伴我雪中禪。","（見高似孫《剡錄》卷四）。"]', '["林下別多年，相逢事渺然。","扁舟浙水上，轻策剡山前。","坐石吟杉月，眠云憶島仙。","何期归太白，伴我雪中禪。","（见高似孫《剡錄》卷四）。"]', '诗', 'shi', '', NULL, '寄獨孤處士 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70e3c16a-07a2-44e5-a097-980df9a10e42', '懷竺法深', '懷竺法深', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["荒齋增暑夢，數留罷冥搜。","南極高僧問，西園獨鶴愁。","興生黃竹晚，吟斷碧雲秋。","共是忘機者，何當臥沃洲。","（同治《嵊縣志》卷二五《文翰志·方外》。","此首承陶敏先生錄示。","）。"]', '["荒斋增暑梦，數留罷冥搜。","南極高僧问，西园独鹤愁。","兴生黄竹晚，吟斷碧云秋。","共是忘機者，何當臥沃洲。","（同治《嵊縣志》卷二五《文翰志·方外》。","此首承陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '懷竺法深 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7678b563-02df-4155-8527-59d98750f8f0', '奉贈河西真法師', '奉贈河西真法師', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["知師遠自燉煌至，藝行兼通釋與儒。","還似法蘭與上國，仍論博望獻新圖。","已聞[□]隴春長在，更說河湟草不枯。","郡去五天多少地，丕騰得見雪山無。","（見伯三八八六卷。","原署：「京薦福寺內供奉大德栖白上。","」）。"]', '["知師远自燉煌至，藝行兼通釋與儒。","還似法蘭與上国，仍論博望獻新圖。","已闻[□]隴春长在，更说河湟草不枯。","郡去五天多少地，丕腾得见雪山無。","（见伯三八八六卷。","原署：「京薦福寺內供奉大德栖白上。","」）。"]', '诗', 'shi', '', NULL, '奉贈河西真法師 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38210b98-a81f-4713-8e02-01db37b05d3e', '五言美瓜沙僧獻款詩一首', '五言美瓜沙僧獻款诗一首', '11236fde-41f8-4029-884c-7288a371033b', '唐', '["聖主恩方洽，瓜沙有異僧。","身中多種藝，心地幾千燈。","面進輸誠款，親論嚮化能。","詔迥（疑應作「迴」）應錫賚，殊寵一層層。","（同前，又見伯三七二○卷。","原署：「右街千福寺內道場應制大德圓鑒」。","）。"]', '["聖主恩方洽，瓜沙有異僧。","身中多種藝，心地幾千灯。","面進輸誠款，親論嚮化能。","詔迥（疑應作「迴」）應錫賚，殊寵一層層。","（同前，又见伯三七二○卷。","原署：「右街千福寺內道場應制大德圓鑒」。","）。"]', '诗', 'shi', '', NULL, '五言美瓜沙僧獻款詩一首 圓鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0264b160-a442-4021-97ee-c9ebf440383f', '五言述瓜沙（一下有「州」字）僧獻款詩一首', '五言述瓜沙（一下有「州」字）僧獻款诗一首', '9941f7bb-fac7-4db8-ae7b-a4ddefbba977', '唐', '["鄉邑雖然異，銜恩萬國同。","遠朝來鳳闕，歸順賀宸聰。","昌（疑應作「冒」字）暑聞鶯囀，看花落晚紅。","辯清能擊論，學富早成功。","大教從西得，敷皂賜（一作「筵願」）向東。","今朝承聖旨，起坐沐天風。","（同前。","注「一作」者，爲伯三七二○卷之異文。","原署：「右街崇先寺內講論兼應制大德彥楚。","」）。"]', '["乡邑雖然異，銜恩万国同。","远朝来鳳闕，归順賀宸聰。","昌（疑應作「冒」字）暑闻鶯囀，看花落晚紅。","辯清能擊論，学富早成功。","大教從西得，敷皂賜（一作「筵願」）向东。","今朝承聖旨，起坐沐天风。","（同前。","注「一作」者，爲伯三七二○卷之異文。","原署：「右街崇先寺內講論兼應制大德彥楚。","」）。"]', '诗', 'shi', '', NULL, '五言述瓜沙（一下有「州」字）僧獻款詩一首 彥楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7235d9-73cf-499d-871d-55c2715363e9', '五言美瓜沙僧獻款詩一首', '五言美瓜沙僧獻款诗一首', '304d78ec-766c-4386-8659-0651b9750f0f', '唐', '["聖澤布遐荒，僧來自遠方。","願弘戎虜地，却作禮儀鄉。","博□諭鄉雅，清譚義更長。","□應恩意重，歸路轉生央。","（見伯三八八六卷。","原署：「右街千福寺沙門子言。","」）。"]', '["聖澤布遐荒，僧来自远方。","願弘戎虜地，却作禮儀乡。","博□諭乡雅，清譚義更长。","□應恩意重，归路轉生央。","（见伯三八八六卷。","原署：「右街千福寺沙门子言。","」）。"]', '诗', 'shi', '', NULL, '五言美瓜沙僧獻款詩一首 子言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debb3017-2e9f-4db0-97f2-e405800e5fb4', '感聖皇之化有燉煌都法師悟真上人特疏來朝因成四韻', '感聖皇之化有燉煌都法師悟真上人特疏来朝因成四韻', '89cf999f-cd32-4ad0-9f97-3b513917ff82', '唐', '["名出燉煌郡，身游日月宮。","柳烟輕古塞，邊草靡春風。","鼓舞千年聖，車書萬里同。","褐衣特獻疏，不戰四夷空。","（同前。","原署：「報恩寺賜紫僧建初。","」）。"]', '["名出燉煌郡，身游日月宮。","柳烟轻古塞，邊草靡春风。","鼓舞千年聖，车书万里同。","褐衣特獻疏，不戰四夷空。","（同前。","原署：「報恩寺賜紫僧建初。","」）。"]', '诗', 'shi', '', NULL, '感聖皇之化有燉煌都法師悟真上人特疏來朝因成四韻 建初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a5aa15-e2eb-413c-8791-84e2da31bf53', '五言四韻奉贈河西大德', '五言四韻奉贈河西大德', 'fab92f71-0ce2-491b-9031-7f34bd1d36e1', '唐', '["{喁左爲禹}{喁左爲禹}空門客，洋洋藝行全。","解投天上日，不住[□□]禪。","飛錫登雲路，摳衣拂戍烟。","喜同清淨教，樂我太平年。","（同前。","原署：「報聖寺內供奉沙門太奉。","」）。"]', '["{喁左爲禹}{喁左爲禹}空门客，洋洋藝行全。","解投天上日，不住[□□]禪。","飞錫登云路，摳衣拂戍烟。","喜同清淨教，乐我太平年。","（同前。","原署：「報聖寺內供奉沙门太奉。","」）。"]', '诗', 'shi', '', NULL, '五言四韻奉贈河西大德 太奉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bacbc492-47f8-4531-953b-de2d72759767', '立贈河西悟真法師', '立贈河西悟真法師', '08595fb1-49f4-41df-b576-a9b477b76afb', '唐', '["沙徼虜塵清，天親入帝京。","詞華推翹類，經論許縱橫。","幸喜乾坤泰，忻逢日月明。","還鄉報連[帥]（師），相寧□昇平。","（同前。","原署：「內供奉文章應制大德有孚。","」）（按：有孚，疑即《全唐詩》、《全唐詩補逸》已收之元孚。","元孚大中間自署爲「上都左街保壽寺文章應制內供奉」，與有孚所署合。","元、有二字，音亦相近，疑有抄誤。","今仍分列，以俟考詳。","）。"]', '["沙徼虜塵清，天親入帝京。","词华推翹類，經論許縱橫。","幸喜乾坤泰，忻逢日月明。","還乡報連[帥]（師），相寧□昇平。","（同前。","原署：「內供奉文章應制大德有孚。","」）（按：有孚，疑即《全唐诗》、《全唐诗補逸》已收之元孚。","元孚大中间自署爲「上都左街保壽寺文章應制內供奉」，與有孚所署合。","元、有二字，音亦相近，疑有抄誤。","今仍分列，以俟考詳。","）。"]', '诗', 'shi', '', NULL, '立贈河西悟真法師 有孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495119db-a496-41fb-b628-9717b5e48d70', '七言美瓜沙僧獻款詩二首 一', '七言美瓜沙僧獻款诗二首 一', '41cae679-22ab-4bc4-92e9-85018630162c', '唐', '["沙漠關河路幾程，師能獻土遠輸誠。","因茲却笑賓熬{下爲火}旅，史籍徒章貢賦名。"]', '["沙漠关河路幾程，師能獻土远輸誠。","因茲却笑賓熬{下爲火}旅，史籍徒章貢賦名。"]', '诗', 'shi', '', NULL, '七言美瓜沙僧獻款詩二首 一 宗茝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88642073-611c-4703-91ef-6a51d3d1b070', '七言美瓜沙僧獻款詩二首 二', '七言美瓜沙僧獻款诗二首 二', '41cae679-22ab-4bc4-92e9-85018630162c', '唐', '["行盡平沙入漢川，手搖金錫意朝天。","如今政是無爲代，堯舜聰明莫比肩。","（同前。","原署：「右街千福寺內道場表白兼應制賜紫大德宗茝。","」）。"]', '["行尽平沙入漢川，手搖金錫意朝天。","如今政是無爲代，堯舜聰明莫比肩。","（同前。","原署：「右街千福寺內道場表白兼應制賜紫大德宗茝。","」）。"]', '诗', 'shi', '', NULL, '七言美瓜沙僧獻款詩二首 二 宗茝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35f6258-eb66-4915-90f8-09f8554aac6b', '依韻奉酬悟真大德（題擬）', '依韻奉酬悟真大德（題擬）', '5672012e-4c71-425d-962a-e9d2adbc05d1', '唐', '["生居忠正地，遠慕鳳凰城。","已見三冬學，何言徒聚螢？","（伯三七二○卷。","原附悟真詩後，題作「依韻奉酬」。","其署銜爲「右街千福寺三教首座入內講論賜紫大德」。","）。"]', '["生居忠正地，远慕鳳凰城。","已见三冬学，何言徒聚螢？","（伯三七二○卷。","原附悟真诗後，題作「依韻奉酬」。","其署銜爲「右街千福寺三教首座入內講論賜紫大德」。","）。"]', '诗', 'shi', '', NULL, '依韻奉酬悟真大德（題擬） 辨章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c0e2da-660d-4d24-8634-7ca919d67bc8', '辭謝辨章大德（題擬）', '辞謝辨章大德（題擬）', 'e28f9e7f-ab39-4353-aa8a-b97247c4b385', '唐', '["生居狐[貊]（陌）地，長在磧邊城。","未能學吐鳳，徒事聚飛螢。","（同前。","原題作「悟真未能酬答和尚，故有辭謝。","」）（按：《敦煌歌辭總編》卷五收悟真《百歲篇》一組十首，茲不備錄。","）。"]', '["生居狐[貊]（陌）地，长在磧邊城。","未能学吐鳳，徒事聚飞螢。","（同前。","原題作「悟真未能酬答和尚，故有辞謝。","」）（按：《敦煌歌辞總編》卷五收悟真《百歲篇》一組十首，茲不備錄。","）。"]', '诗', 'shi', '', NULL, '辭謝辨章大德（題擬） 悟真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a0c9452-8d60-4431-8acf-7cc28ce1d3b3', '', '', 'ed877832-3a03-48a8-961f-941af6cdbe7e', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 景導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea47bc7-9d8c-4d05-ab50-52cc7438831d', '贈沙州僧悟真上人兼送歸', '贈沙州僧悟真上人兼送归', 'ed877832-3a03-48a8-961f-941af6cdbe7e', '唐', '["河湟舊邑新道復，天竺名僧漢地來。","經論三乘鶖子辯，詩吟五字慧休才。","登山振杖穿雲錫，渡水還浮逆浪杯。","明日玉階辭聖主，恩光西邁送書迴。","（斯四六五四卷。","原署：「左街保壽寺供奉講論大德景導。","」）。"]', '["河湟旧邑新道复，天竺名僧漢地来。","經論三乘鶖子辯，诗吟五字慧休才。","登山振杖穿云錫，渡水還浮逆浪杯。","明日玉階辞聖主，恩光西邁送书迴。","（斯四六五四卷。","原署：「左街保壽寺供奉講論大德景導。","」）。"]', '诗', 'shi', '', NULL, '贈沙州僧悟真上人兼送歸 景導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a073be-bb26-4177-bef5-d9a1b60944d3', '過耒江吊子美', '過耒江吊子美', '46d39d34-269a-4d59-bfbd-794004b621fe', '唐', '["耒陽浦口繫扁舟，紅蓼灘頭宿白鷗。","半夜青燈千里客，數聲寒雁一天秋。","蛩吟隔岸情如訴，斗柄橫江勢欲流。","惆悵杜陵老詩伯，斷碑古木繞荒丘。","（《杜詩詳注》附《諸家詠杜續編》引《耒陽縣志》。","此詩承陶敏先生錄示。","）。"]', '["耒陽浦口繫扁舟，紅蓼灘头宿白鷗。","半夜青灯千里客，數声寒雁一天秋。","蛩吟隔岸情如訴，斗柄橫江勢欲流。","惆悵杜陵老诗伯，斷碑古木繞荒丘。","（《杜诗詳注》附《諸家詠杜續編》引《耒陽縣志》。","此诗承陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '過耒江吊子美 李節 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e4019d-3e5c-4e92-9fe9-63c6c3ba0779', '泛若耶宿雲門', '泛若耶宿云门', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["溪船泛數里，漸覺少炎暉。","暎水花連影，逢人鳥背飛。","深猶見白石，涼好換生衣。","未得多詩句，終須隔宿歸。","（《會稽掇英總集》卷六）。"]', '["溪船泛數里，漸覺少炎暉。","暎水花連影，逢人鸟背飞。","深猶见白石，涼好換生衣。","未得多诗句，終須隔宿归。","（《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '泛若耶宿雲門 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26dbd54e-fd8b-4df6-9e0e-2ea335ef3914', '韋曲', '韋曲', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["韋曲城南錦作堆，千金不惜買花栽。","誰知貴戚多羇束，落盡春紅不看來。","（《類編長安志》卷九）。"]', '["韋曲城南錦作堆，千金不惜買花栽。","誰知貴戚多羇束，落尽春紅不看来。","（《類編长安志》卷九）。"]', '诗', 'shi', '', NULL, '韋曲 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d379367-07f8-4cff-93d6-03496e251346', '白水洞飛泉', '白水洞飞泉', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["靈泉何太高，北斗想可挹。","淩日五色雲，直偪千仞急。","白虹下飲澗，寒劍倚天立。","閃電不得瞬，長雷無敢蟄。","萬丈石崖坼，一道林巒濕。","險偪飛瀉墜，冷心山鬼泣。","須當截海去，濁浪不相入。","（見乾隆十二年刊張雄圖纂《長沙府志》卷四五、光緒《湖南通志》卷四《山川》二。","）。"]', '["靈泉何太高，北斗想可挹。","淩日五色云，直偪千仞急。","白虹下饮澗，寒劍倚天立。","閃電不得瞬，长雷無敢蟄。","万丈石崖坼，一道林巒濕。","險偪飞瀉墜，冷心山鬼泣。","須當截海去，濁浪不相入。","（见乾隆十二年刊張雄圖纂《长沙府志》卷四五、光緒《湖南通志》卷四《山川》二。","）。"]', '诗', 'shi', '', NULL, '白水洞飛泉 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2fdf4e-4c34-4c54-b612-988d3c506f53', '延慶化城寺', '延慶化城寺', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["平生志在野雲深，建立精藍大用心。","須達買園充聖地，祗陁施樹不收金。","鳴鐘尚息刀輪苦，下擊三塗地獄音。","爲報往來遊翫者，園林常住勿相侵。","（見道光五年刊方履籛編《河內縣志》卷二十）（〖1〗《河內縣志》云此詩石刻爲正書，在河內懸，題下署裴相公詩，詩末題一行：「唐長興四年癸巳主僧惠□立石。","」縣志作者附跋云：「裴公美本濟源人，常讀書野寺中，茲化城寺近其所居，故亦勒其詩。","然考此詩殊不似唐人作，疑即梵徒託名爲也。","」今按：此跋既謂裴休爲鄰縣人，有作詩可能，復疑其僞，立論不免牴牾。","石刻既爲後唐時立，休亦一生佞佛者，《景德傳燈錄》至爲其立傳，此詩與贈希運一詩相類，可決其非後世梵僧所僞撰。","又乾隆五十三年刊《濟源縣志》卷十六亦收此詩，題作《書留延慶化城寺壁》。","）。"]', '["平生志在野云深，建立精藍大用心。","須達買园充聖地，祗陁施樹不收金。","鳴鐘尚息刀輪苦，下擊三塗地獄音。","爲報往来游翫者，园林常住勿相侵。","（见道光五年刊方履籛編《河內縣志》卷二十）（〖1〗《河內縣志》云此诗石刻爲正书，在河內懸，題下署裴相公诗，诗末題一行：「唐长兴四年癸巳主僧惠□立石。","」縣志作者附跋云：「裴公美本濟源人，常读书野寺中，茲化城寺近其所居，故亦勒其诗。","然考此诗殊不似唐人作，疑即梵徒託名爲也。","」今按：此跋既謂裴休爲鄰縣人，有作诗可能，复疑其僞，立論不免牴牾。","石刻既爲後唐时立，休亦一生佞佛者，《景德傳灯錄》至爲其立傳，此诗與贈希運一诗相類，可決其非後世梵僧所僞撰。","又乾隆五十三年刊《濟源縣志》卷十六亦收此诗，題作《书留延慶化城寺壁》。","）。"]', '诗', 'shi', '', NULL, '延慶化城寺 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c77ff615-5550-4c11-bb8e-06cf2e800934', '頌黃陵斷際禪師（題擬）', '頌黄陵斷際禪師（題擬）', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["塵勞迥脫事非常，緊把繩頭繫一場。","不是一番寒徹骨，爭得梅花撲鼻香。","（見《大正新修大藏經》第四八冊裴休撰《黃陵斷際禪師宛陵錄》）。"]', '["塵勞迥脫事非常，緊把繩头繫一場。","不是一番寒徹骨，爭得梅花撲鼻香。","（见《大正新修大藏經》第四八冊裴休撰《黄陵斷際禪師宛陵錄》）。"]', '诗', 'shi', '', NULL, '頌黃陵斷際禪師（題擬） 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d371a0a9-afbf-4123-9c02-90dbd1766a2d', '武林石橋亭', '武林石橋亭', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["山斷石爲橋。","（見宋施諤撰《淳祐臨安志》殘本卷八）（按：影宋蜀刻《張承吉文集》卷八《題天竺寺》有此句。","）。"]', '["山斷石爲橋。","（见宋施諤撰《淳祐臨安志》殘本卷八）（按：影宋蜀刻《張承吉文集》卷八《題天竺寺》有此句。","）。"]', '诗', 'shi', '', NULL, '武林石橋亭 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e607af19-8ccc-481b-a89e-85086cdf6aca', '句 一', '句 一', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["雷電下嵩陰。"]', '["雷電下嵩陰。"]', '诗', 'shi', '', NULL, '句 一 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eb3b1f2-07c3-4bcd-a798-03e3e4d473da', '句 二', '句 二', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["香連隣舍像。","（見《唐詩紀事》卷四九引《酉陽雜俎》）。"]', '["香連隣舍像。","（见《唐诗紀事》卷四九引《酉陽杂俎》）。"]', '诗', 'shi', '', NULL, '句 二 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e113b0-4089-4810-a9c6-8d6ca49fc1f8', '樂道歌', '乐道歌', 'f09519fe-f9f6-4082-8acc-84b345b08a73', '唐', '["樂道山僧縱性多，天迥地轉任從他。","閑臥孤峯無伴侶，獨唱無生一曲歌。","無生歌，出世樂，堪笑時人和不著。","暢情樂道過殘生，張三李四渾忘卻。","大丈夫，須氣槩，莫順人情莫妨礙。","汝言順即是菩提，我謂從來自相背。","有時憨，有時癡，非我途中爭得知。","特達一生常任運，野客無鄉可得歸。","今日山僧只遮是，元本山僧更若爲。","探祖機，空王子，休似浮雲勿隈倚。","自古長披一衲衣，曾經幾度遭寒暑，不是真，不是僞，打鼓樂神施拜跪。","明明一道漢江雲，青山淥水不相似。","稟性成，無揩改，結角羅紋不相礙。","或運慈悲喜捨心，或即逢人以棒闓。","慈悲恩愛落牽纏，棒打交伊破恩愛。","報乎月下旅中人，若有恩情吾爲改。","（見《景德傳燈錄》卷三十）。"]', '["乐道山僧縱性多，天迥地轉任從他。","闲臥孤峯無伴侶，独唱無生一曲歌。","無生歌，出世乐，堪笑时人和不著。","暢情乐道過殘生，張三李四渾忘卻。","大丈夫，須氣槩，莫順人情莫妨礙。","汝言順即是菩提，我謂從来自相背。","有时憨，有时癡，非我途中爭得知。","特達一生常任運，野客無乡可得归。","今日山僧只遮是，元本山僧更若爲。","探祖機，空王子，休似浮云勿隈倚。","自古长披一衲衣，曾經幾度遭寒暑，不是真，不是僞，打鼓乐神施拜跪。","明明一道漢江云，青山淥水不相似。","稟性成，無揩改，結角羅紋不相礙。","或運慈悲喜捨心，或即逢人以棒闓。","慈悲恩愛落牽纏，棒打交伊破恩愛。","報乎月下旅中人，若有恩情吾爲改。","（见《景德傳灯錄》卷三十）。"]', '诗', 'shi', '', NULL, '樂道歌 道吾和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0707f888-ad52-41b5-9559-9e1f36f975a7', '句', '句', '6ec8f1f1-a7e7-4ab1-be1b-a60f7b1f4dd2', '唐', '["萍聚只因今日浪，荻斜都爲夜來風。","（《唐語林》卷三）。"]', '["萍聚只因今日浪，荻斜都爲夜来风。","（《唐語林》卷三）。"]', '诗', 'shi', '', NULL, '句 畢誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0877d431-3bf2-4217-929c-5dc393d42e35', '惜春', '惜春', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["自從春草生，不敢下階行。","（見日本汲古書院出版《和刻本類書集成》本宋陳元靚《重編羣書類要事林廣記癸集》卷十三《詼諧文話》引）。"]', '["自從春草生，不敢下階行。","（见日本汲古书院出版《和刻本類书集成》本宋陳元靚《重編羣书類要事林廣記癸集》卷十三《詼諧文話》引）。"]', '诗', 'shi', '', NULL, '惜春 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9f0c500-4be7-432b-af47-07ce44e0f092', '詠蟬', '詠蟬', '57f5c661-8ebb-4d9a-b0da-d25bce583447', '唐', '["雨餘翼斂槐煙薄，風急聲翻柳巷深。"]', '["雨餘翼斂槐煙薄，风急声翻柳巷深。"]', '诗', 'shi', '', NULL, '詠蟬 詹雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e42169a4-3ac4-47b5-8907-095914385a9b', '詠柳', '詠柳', '57f5c661-8ebb-4d9a-b0da-d25bce583447', '唐', '["自從彭澤先生後，翠葉芳條祇自春。","（均見《吟窗雜錄》卷二九《歷代吟譜》）。"]', '["自從彭澤先生後，翠葉芳條祇自春。","（均见《吟窗杂錄》卷二九《歷代吟譜》）。"]', '诗', 'shi', '', NULL, '詠柳 詹雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408ae5f2-6a71-4397-a10c-aaa4fbd0807b', '勸學偈', '勸学偈', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["萬丈竿頭未得休，堂堂有路少人遊。","禪師欲（《景德傳燈錄》作「願」）達南泉去，滿目青山萬萬秋。","（《祖堂集》卷十七、《景德傳燈錄》卷十）。"]', '["万丈竿头未得休，堂堂有路少人游。","禪師欲（《景德傳灯錄》作「願」）達南泉去，满目青山万万秋。","（《祖堂集》卷十七、《景德傳灯錄》卷十）。"]', '诗', 'shi', '', NULL, '勸學偈 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b2f435-5db9-4f54-9d27-51cde335d605', '誡人斫松竹偈', '誡人斫松竹偈', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["千年竹，萬年松，枝枝葉葉盡皆同。","爲報四方參（《景德傳燈錄》作「玄」）學者，動手無非觸祖翁（《景德傳燈錄》作「公」）。","（同前）。"]', '["千年竹，万年松，枝枝葉葉尽皆同。","爲報四方參（《景德傳灯錄》作「玄」）学者，动手無非觸祖翁（《景德傳灯錄》作「公」）。","（同前）。"]', '诗', 'shi', '', NULL, '誡人斫松竹偈 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd49aac-4007-4800-a49b-fa5bb6a782fc', '投機偈', '投機偈', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["處處真，處處真，塵塵盡是本來人。","真實說時聲不現，正體堂堂沒却身。","（《祖堂集》卷十七）。"]', '["处处真，处处真，塵塵尽是本来人。","真實说时声不現，正體堂堂沒却身。","（《祖堂集》卷十七）。"]', '诗', 'shi', '', NULL, '投機偈 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2efc8c6-360c-4588-8185-5d10f53e8bd5', '因事頌', '因事頌', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["自覺開佛堂，慧放五道光。","無人不佛佛，不悟意中藏。","（同前）。"]', '["自覺开佛堂，慧放五道光。","無人不佛佛，不悟意中藏。","（同前）。"]', '诗', 'shi', '', NULL, '因事頌 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53b1bf1b-254b-457e-b434-579d09a58cac', '須彌納芥子頌', '須彌納芥子頌', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["須彌本非有，芥子元來空。","將空納非有，何處不相容？","（同前）。"]', '["須彌本非有，芥子元来空。","將空納非有，何处不相容？","（同前）。"]', '诗', 'shi', '', NULL, '須彌納芥子頌 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c5db5c-a2ba-4153-9006-8097e7ba92a3', '明教中幻意偈', '明教中幻意偈', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["若人見幻本來真，是即名爲見佛人。","圓通法界無生滅，無滅無生是佛身。","（同前）。"]', '["若人见幻本来真，是即名爲见佛人。","圓通法界無生滅，無滅無生是佛身。","（同前）。"]', '诗', 'shi', '', NULL, '明教中幻意偈 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('046d6b06-58d4-44f1-b1dc-9f7dd76db631', '答南泉久住投機偈（題擬）', '答南泉久住投機偈（題擬）', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["今日投機事莫論，南泉不道遍乾坤。","還鄉須（《五燈會元》作「盡」）是兒孫事，祖父從來不入（《五燈會元》「出」）門。","（《景德傳燈錄》卷十、《五燈會元》卷四）（按：《五燈會元》以此首爲南泉普願作，而以南泉之作爲景岑作，似誤。","）。"]', '["今日投機事莫論，南泉不道遍乾坤。","還乡須（《五灯會元》作「尽」）是兒孫事，祖父從来不入（《五灯會元》「出」）门。","（《景德傳灯錄》卷十、《五灯會元》卷四）（按：《五灯會元》以此首爲南泉普願作，而以南泉之作爲景岑作，似誤。","）。"]', '诗', 'shi', '', NULL, '答南泉久住投機偈（題擬） 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bee1af9-0c66-450c-9b78-e81e276ef6b5', '偈 一', '偈 一', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["百丈竿頭不動人，雖然得入未爲真。","百丈竿頭須進步，十方世界是全身。","（《祖堂集》卷十七、《景德傳燈錄》卷十）。"]', '["百丈竿头不动人，雖然得入未爲真。","百丈竿头須進步，十方世界是全身。","（《祖堂集》卷十七、《景德傳灯錄》卷十）。"]', '诗', 'shi', '', NULL, '偈 一 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77adb80-162f-421b-896a-f8e17311449d', '偈 二', '偈 二', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["也大奇，也大奇，一月之中兩月疑。","見與見緣無自性，常寂誰是復誰非。","（《祖堂集》卷十七）。"]', '["也大奇，也大奇，一月之中兩月疑。","见與见緣無自性，常寂誰是复誰非。","（《祖堂集》卷十七）。"]', '诗', 'shi', '', NULL, '偈 二 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8f2af0-9422-4968-b4b3-0edd09db72d6', '偈 三', '偈 三', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["最甚深，最甚深，法界人身便是心。","迷者迷心爲衆色（《宗鏡錄》作「剎」），悟時剎海（《景德傳燈錄》作「境」）是真心。","身界二塵無實性（《宗鏡錄》、《景德傳燈錄》作「相」），分明達此號知音。","（《祖堂集》卷十七、《宗鏡錄》卷九八、《景德傳燈錄》卷十）。"]', '["最甚深，最甚深，法界人身便是心。","迷者迷心爲衆色（《宗镜錄》作「剎」），悟时剎海（《景德傳灯錄》作「境」）是真心。","身界二塵無實性（《宗镜錄》、《景德傳灯錄》作「相」），分明達此號知音。","（《祖堂集》卷十七、《宗镜錄》卷九八、《景德傳灯錄》卷十）。"]', '诗', 'shi', '', NULL, '偈 三 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a536dc-bfe5-4cae-99bf-208529624852', '偈 四', '偈 四', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["摩訶般若照，解脫甚深香（《景德傳燈錄》作「深」，《五燈會元》作「法」）。","法身寂滅體，三一理圓常。","欲識功齊處，此名常寂光。","（《祖堂集》卷十七、《景德傳燈錄》卷十、《五燈會元》卷四）。"]', '["摩訶般若照，解脫甚深香（《景德傳灯錄》作「深」，《五灯會元》作「法」）。","法身寂滅體，三一理圓常。","欲識功齊处，此名常寂光。","（《祖堂集》卷十七、《景德傳灯錄》卷十、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 四 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f64b0f9-6eb6-4ca3-a78a-29c4c4207518', '偈 五', '偈 五', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["虛空問萬像，萬像答虛空。","何（《景德傳燈錄》作「誰」）人親得聞，木叉丱角童。","（《祖堂集》卷十七、《景德傳燈錄》卷十。","）。"]', '["虛空问万像，万像答虛空。","何（《景德傳灯錄》作「誰」）人親得闻，木叉丱角童。","（《祖堂集》卷十七、《景德傳灯錄》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 五 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4510b1-6071-4adf-84c4-d7af72cd09bd', '偈 六', '偈 六', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["假有元非有，假滅亦非無。","湼槃償債義，一性更無殊。","（《祖堂集》卷十七）。"]', '["假有元非有，假滅亦非無。","湼槃償債義，一性更無殊。","（《祖堂集》卷十七）。"]', '诗', 'shi', '', NULL, '偈 六 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00878424-f22a-41fe-a38c-af4e8407f086', '偈 七', '偈 七', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["妙空妙用不思議，無滅無生無所依。","本覺性真爲智父，父生智子妙難思。","智智不覺元來妙，遠見無觀即本如。","父子本來無二相，即今即本更無時。","（同前）。"]', '["妙空妙用不思議，無滅無生無所依。","本覺性真爲智父，父生智子妙难思。","智智不覺元来妙，远见無观即本如。","父子本来無二相，即今即本更無时。","（同前）。"]', '诗', 'shi', '', NULL, '偈 七 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bdd6e9d-b7d1-4353-bfd0-daba7e096955', '偈 八', '偈 八', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["滿眼本非色，滿耳本非聲。","文殊常觸目，觀音塞耳根。","會三元一體，達四本同真。","堂堂法界性，無佛亦無人。","（《祖堂集》卷十七、《景德傳燈錄》卷十。","）。"]', '["满眼本非色，满耳本非声。","文殊常觸目，观音塞耳根。","會三元一體，達四本同真。","堂堂法界性，無佛亦無人。","（《祖堂集》卷十七、《景德傳灯錄》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 八 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b658511-ca47-4f1e-a2b4-e25b3228190e', '偈 九', '偈 九', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["誰問山河轉，山河轉向誰？","圓通無兩畔，法性本無歸。","（同前）。"]', '["誰问山河轉，山河轉向誰？","圓通無兩畔，法性本無归。","（同前）。"]', '诗', 'shi', '', NULL, '偈 九 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063be4d7-c3bc-4bd8-b909-670d935ba0a7', '偈 十', '偈 十', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["礙處無（《景德傳燈錄》作「非」）牆壁，通處勿（《景德傳燈錄》作「沒」）虛空。","若能（《景德傳燈錄》作「人」）如是解，心色本來同。","（《祖堂集》卷十七、《景德傳燈錄》卷十）。"]', '["礙处無（《景德傳灯錄》作「非」）牆壁，通处勿（《景德傳灯錄》作「沒」）虛空。","若能（《景德傳灯錄》作「人」）如是解，心色本来同。","（《祖堂集》卷十七、《景德傳灯錄》卷十）。"]', '诗', 'shi', '', NULL, '偈 十 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9793ea-fd64-4164-96c9-d7247f0a51b4', '偈 十一', '偈 十一', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["學道之人不識真，只爲從來認識神。","無始劫來生死本，癡人喚作本來身。","（《景德傳燈錄》卷十、《五燈會元》卷四、《叢林公論》）。"]', '["学道之人不識真，只爲從来認識神。","無始劫来生死本，癡人喚作本来身。","（《景德傳灯錄》卷十、《五灯會元》卷四、《叢林公論》）。"]', '诗', 'shi', '', NULL, '偈 十一 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191a76e7-7319-45dd-813a-0e8e53c662c3', '偈 十二', '偈 十二', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["佛性堂堂顯現，住性有情難見。","若悟衆生無我，我面何殊（《五燈會元》作「如」）佛面？","（《景德傳燈錄》卷十、《五燈會元》卷四）。"]', '["佛性堂堂显現，住性有情难见。","若悟衆生無我，我面何殊（《五灯會元》作「如」）佛面？","（《景德傳灯錄》卷十、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 十二 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21968036-b42c-4789-be36-41eb63c02c6d', '偈 十三', '偈 十三', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["不識金剛體，却喚作緣生。","十方真寂滅，誰在復誰行。","（同前。","又見《林間錄》卷上）。"]', '["不識金剛體，却喚作緣生。","十方真寂滅，誰在复誰行。","（同前。","又见《林间錄》卷上）。"]', '诗', 'shi', '', NULL, '偈 十三 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ad63d0-108d-4eaa-bddf-2da9a249e877', '偈 十四', '偈 十四', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["萬法一如不用揀，一如誰揀誰不揀。","即今生死本菩提，三世如來同箇眼。","（同前）。"]', '["万法一如不用揀，一如誰揀誰不揀。","即今生死本菩提，三世如来同箇眼。","（同前）。"]', '诗', 'shi', '', NULL, '偈 十四 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98788142-0fb6-4a71-bc0d-190ba6d4a8e4', '亡僧偈', '亡僧偈', '0847c167-538d-4d60-b0de-37875bac722e', '唐', '["目前無一法，當處亦無人。","蕩蕩金剛體，非妄亦非真。","（《林間錄》卷上）。"]', '["目前無一法，當处亦無人。","蕩蕩金剛體，非妄亦非真。","（《林间錄》卷上）。"]', '诗', 'shi', '', NULL, '亡僧偈 景岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2144bd-7c5f-4e3b-a44c-14b261f5fbc6', '句', '句', 'd6dfcef9-718b-4853-b397-11ea35dc02cb', '唐', '["君自成龍我成道。","（見明王應山篡《閩都記》卷十九）（按：《閩都記》云：「雙峰寺在綏平里，今四都也。","唐咸通五年，僧師復自小箬雙髻峰移建今所焉。","觀察使林袞同業儒同入關，至揚子渡口，師復有出塵之興，賦詩曰〖略〗。","浩然而歸，卜築於此。","觀察使李瓚請賜寺額。","」）。"]', '["君自成龙我成道。","（见明王應山篡《閩都記》卷十九）（按：《閩都記》云：「雙峰寺在綏平里，今四都也。","唐咸通五年，僧師复自小箬雙髻峰移建今所焉。","观察使林袞同業儒同入关，至揚子渡口，師复有出塵之兴，賦诗曰〖略〗。","浩然而归，卜築於此。","观察使李瓚請賜寺額。","」）。"]', '诗', 'shi', '', NULL, '句 師復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d701eb6-d3ba-4e56-a0bf-6ccf3604a19a', '偈', '偈', 'a2c8bdc3-71ec-4c0c-b84d-1e2192cf0a08', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '偈 智真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cacde6c4-053a-4068-8a51-5fa7fcf4c653', '偈 一', '偈 一', 'a2c8bdc3-71ec-4c0c-b84d-1e2192cf0a08', '唐', '["心本絕塵何用洗，身中無病豈求醫。","欲知是佛非身（《淳熙三山志》卷三七作「心」）處，明鑑高懸未照時。"]', '["心本絕塵何用洗，身中無病豈求醫。","欲知是佛非身（《淳熙三山志》卷三七作「心」）处，明鑑高懸未照时。"]', '诗', 'shi', '', NULL, '偈 一 智真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8d0edcd-5194-41ba-951c-2246497f42cf', '偈 二', '偈 二', 'a2c8bdc3-71ec-4c0c-b84d-1e2192cf0a08', '唐', '["明月分形處處新，白衣寧墜解空人。","誰言在俗解（《五燈會元》作「妨」）修道，金粟曾爲長者（《五燈會元》作「居士」）身。"]', '["明月分形处处新，白衣寧墜解空人。","誰言在俗解（《五灯會元》作「妨」）修道，金粟曾爲长者（《五灯會元》作「居士」）身。"]', '诗', 'shi', '', NULL, '偈 二 智真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da35872b-b58b-4abb-b7c4-2d8fcfe1abbf', '偈 三', '偈 三', 'a2c8bdc3-71ec-4c0c-b84d-1e2192cf0a08', '唐', '["忍仙林下坐禪時，曾被歌王割截肢。","況我聖朝無此事，只今休道亦何悲。","（見《景德傳燈錄》卷九、《五燈會元》卷四）（按：《祖堂集》卷十七以「心本」、「忍仙」二首作正原偈。","《淳熙三山志》卷三七則以正原「滄溟幾度變桑山」一偈歸智真，今皆不取。","）。"]', '["忍仙林下坐禪时，曾被歌王割截肢。","況我聖朝無此事，只今休道亦何悲。","（见《景德傳灯錄》卷九、《五灯會元》卷四）（按：《祖堂集》卷十七以「心本」、「忍仙」二首作正原偈。","《淳熙三山志》卷三七則以正原「滄溟幾度变桑山」一偈归智真，今皆不取。","）。"]', '诗', 'shi', '', NULL, '偈 三 智真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a05c4f-95db-40f1-aa23-c4b681cdfdad', '偈 四', '偈 四', 'a2c8bdc3-71ec-4c0c-b84d-1e2192cf0a08', '唐', '["勑命如雷下翠微，風前垂淚脫禪衣。","雲中有寺不容住，塵裏無家何處歸。","（見《五燈會元》卷四）（按：《輿地紀勝》卷十九錄中和間僧麻衣禪師《麻衣頌》，與此頌僅數字不同。","難以確定歸屬，今兩收。","《石倉歷代詩選》卷一一一收「明月」、「勑命」二首。","）。"]', '["勑命如雷下翠微，风前垂泪脫禪衣。","云中有寺不容住，塵裏無家何处归。","（见《五灯會元》卷四）（按：《輿地紀勝》卷十九錄中和间僧麻衣禪師《麻衣頌》，與此頌僅數字不同。","难以確定归屬，今兩收。","《石倉歷代诗選》卷一一一收「明月」、「勑命」二首。","）。"]', '诗', 'shi', '', NULL, '偈 四 智真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4326bdad-2139-4600-9c19-9ef695d35b87', '句 一', '句 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["山寺明媚木芍藥，野田叫噪官蝦蟆。","（見《能改齋漫錄》卷五《漢以牡丹爲木芍藥》條）。"]', '["山寺明媚木芍藥，野田叫噪官蝦蟆。","（见《能改斋漫錄》卷五《漢以牡丹爲木芍藥》條）。"]', '诗', 'shi', '', NULL, '句 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de24ca4f-8e1a-4b51-802c-f9741d64322b', '句 二', '句 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["窗疏眉語度。","（見《類說》卷四九《漢上題襟》）。"]', '["窗疏眉語度。","（见《類说》卷四九《漢上題襟》）。"]', '诗', 'shi', '', NULL, '句 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('459fac27-d7cb-49e1-96d9-eaba2931e2c9', '卜山居', '卜山居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["山底採薇雲不厭，洞中栽樹鶴先知。","（見《日本古典文學大系》七三冊藤原公任《和漢朗詠集》卷下《仙家》引）（按：上毛河世寧《全唐詩逸》卷中收二句歸「溫達」。","川口久雄注《和漢朗詠集》以爲係沿襲《千唐佳句》抄本的誤字而致誤。","題從架藏私注本。","）。"]', '["山底採薇云不厭，洞中栽樹鹤先知。","（见《日本古典文学大系》七三冊藤原公任《和漢朗詠集》卷下《仙家》引）（按：上毛河世寧《全唐诗逸》卷中收二句归「溫達」。","川口久雄注《和漢朗詠集》以爲係沿襲《千唐佳句》抄本的誤字而致誤。","題從架藏私注本。","）。"]', '诗', 'shi', '', NULL, '卜山居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726a5cc9-c662-47da-85ec-c2a9622fc14d', '爲湖州軍倅日與同年李大諫詩酒唱酧以疾阻歡及愈作此詩（題擬）', '爲湖州軍倅日與同年李大諫诗酒唱酧以疾阻歡及愈作此诗（題擬）', '6dd287e9-b235-48d1-815a-1a65e23edebf', '唐', '["已負數年紅畫燭，更辜雙帶繡香毬。","白蘋洲上風煙好，扶病須𢬵到後籌。"]', '["已負數年紅畫燭，更辜雙带繡香毬。","白蘋洲上风煙好，扶病須𢬵到後籌。"]', '诗', 'shi', '', NULL, '爲湖州軍倅日與同年李大諫詩酒唱酧以疾阻歡及愈作此詩（題擬） 封特卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bd44e1-3a60-40e0-a216-d899b35a79f4', '離別難', '離別难', '6dd287e9-b235-48d1-815a-1a65e23edebf', '唐', '["佛許衆生願，心堅石也穿。","今朝雖送別，會卻有明年。","（均見《增修詩話總龜》卷二三引江鄰幾《雜志》。","今本《江鄰幾雜志》無此條）。"]', '["佛許衆生願，心堅石也穿。","今朝雖送別，會卻有明年。","（均见《增修诗話總龟》卷二三引江鄰幾《杂志》。","今本《江鄰幾杂志》無此條）。"]', '诗', 'shi', '', NULL, '離別難 封特卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e98a8c15-8107-4d7b-8b07-81d1ddcd7e5a', '', '', '13367373-77fe-4700-9fa9-f4d22bda2f4b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 義玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1ed4a2-542d-42d1-ad6d-a03301aa78d9', '將示滅說傳法偈', '將示滅说傳法偈', '13367373-77fe-4700-9fa9-f4d22bda2f4b', '唐', '["沿流不止問如何？真照無偏（《五燈會元》、《林間錄》作「邊」）說似他。","離相離名人不稟，吹毛用了急還（《林間錄》、《五燈會元》作「須」）磨。","（見《天聖廣燈錄》卷十、《五燈會元》卷十一、《林間錄》卷下）。"]', '["沿流不止问如何？真照無偏（《五灯會元》、《林间錄》作「邊」）说似他。","離相離名人不稟，吹毛用了急還（《林间錄》、《五灯會元》作「須」）磨。","（见《天聖廣灯錄》卷十、《五灯會元》卷十一、《林间錄》卷下）。"]', '诗', 'shi', '', NULL, '將示滅說傳法偈 義玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ed29ec-d9eb-4b45-8bd7-9328b3788704', '趙州和尚將遊五臺作偈留之（題擬）', '趙州和尚將游五台作偈留之（題擬）', 'f01c17fd-3f75-4b54-9e3d-a06c0b8ec318', '唐', '["何（《五燈會元》作「無」）處青山不道場，何須策杖禮清涼。","雲中縱有金毛現，正眼觀時非吉祥。","（見《景德傳燈錄》卷十、《五燈會元》卷四。","《石倉歷代詩選》卷一一一誤作從諗詩）。"]', '["何（《五灯會元》作「無」）处青山不道場，何須策杖禮清涼。","云中縱有金毛現，正眼观时非吉祥。","（见《景德傳灯錄》卷十、《五灯會元》卷四。","《石倉歷代诗選》卷一一一誤作從諗诗）。"]', '诗', 'shi', '', NULL, '趙州和尚將遊五臺作偈留之（題擬） 某大德 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b38d1a1b-a547-4708-be50-d2e9ba2a1877', '十二時歌 一', '十二时歌 一', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["鷄鳴丑，愁見起來還漏逗。","裙子褊（《偈頌》作「偏」）衫箇也無，袈裟形相些些有。","裩無腰（一作「襠」），袴無口，頭上青灰三五斗。","比望（一作「本爲」）修行利濟人，誰知變作（一作「翻成」）不唧溜。","（按：宋圓悟《碧巖錄》卷四仰山引此首，注「一作」者爲其異文。","）。"]', '["鷄鳴丑，愁见起来還漏逗。","裙子褊（《偈頌》作「偏」）衫箇也無，袈裟形相些些有。","裩無腰（一作「襠」），袴無口，头上青灰三五斗。","比望（一作「本爲」）修行利濟人，誰知变作（一作「翻成」）不唧溜。","（按：宋圓悟《碧巖錄》卷四仰山引此首，注「一作」者爲其異文。","）。"]', '诗', 'shi', '', NULL, '十二時歌 一 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aa1336-ae98-4f54-92e4-ff9e4eb184ba', '十二時歌 二', '十二时歌 二', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["平旦寅，荒村破院實難論。","解齋粥米全無粒，空對閑窗與隙塵。","唯雀噪，勿人親，獨坐時聞落葉頻。","誰道出家憎愛斷，思量不覺淚沾巾。"]', '["平旦寅，荒村破院實难論。","解斋粥米全無粒，空对闲窗與隙塵。","唯雀噪，勿人親，独坐时闻落葉頻。","誰道出家憎愛斷，思量不覺泪沾巾。"]', '诗', 'shi', '', NULL, '十二時歌 二 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6388d7b5-855b-4125-b7a5-39b02311619a', '十二時歌 三', '十二时歌 三', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["日出卯，清淨却翻爲煩惱。","有爲功德被塵謾（《偈頌》作「幔」），無限田地未曾掃。","攢眉多，稱心少，尀耐東村黑黃老。","供利不曾將得來，放驢喫我堂前草。"]', '["日出卯，清淨却翻爲煩惱。","有爲功德被塵謾（《偈頌》作「幔」），無限田地未曾掃。","攢眉多，稱心少，尀耐东村黑黄老。","供利不曾將得来，放驢喫我堂前草。"]', '诗', 'shi', '', NULL, '十二時歌 三 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402c491e-179f-4809-9049-d99285e8f4b9', '十二時歌 四', '十二时歌 四', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["食時辰，煙火徒勞望四鄰。","饅頭䭔子前年別，今日思量空嚥津。","持念少，嗟歎頻，一百家中無善人。","來者祇道覓茶喫，不得茶童（《偈頌》作「噇」）去又嗔。"]', '["食时辰，煙火徒勞望四鄰。","饅头䭔子前年別，今日思量空嚥津。","持念少，嗟歎頻，一百家中無善人。","来者祇道覓茶喫，不得茶童（《偈頌》作「噇」）去又嗔。"]', '诗', 'shi', '', NULL, '十二時歌 四 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f5fdc6-9421-4d4c-9d9a-d3484caa2030', '十二時歌 五', '十二时歌 五', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["禺中巳，削髮誰知到如此。","無端被請作村僧，屈辱饑悽受欲死。","胡張三，黑李四，恭敬不曾生些子。","適來忽爾到門頭，唯道借茶兼借紙。"]', '["禺中巳，削髮誰知到如此。","無端被請作村僧，屈辱饑悽受欲死。","胡張三，黑李四，恭敬不曾生些子。","適来忽爾到门头，唯道借茶兼借紙。"]', '诗', 'shi', '', NULL, '十二時歌 五 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f28e2cfb-0508-421f-8e53-b303dd8d50ef', '十二時歌 六', '十二时歌 六', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["日南午，茶飯輪還無定度。","行却南家到北家，果至北家不推註。","苦沙鹽，大麥醋，蜀黍米飯虀萵苣。","唯稱供養不等閑，和尚道心須堅固。"]', '["日南午，茶飯輪還無定度。","行却南家到北家，果至北家不推註。","苦沙鹽，大麦醋，蜀黍米飯虀萵苣。","唯稱供養不等闲，和尚道心須堅固。"]', '诗', 'shi', '', NULL, '十二時歌 六 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af84adca-2188-4933-a381-3832bf54e048', '十二時歌 七', '十二时歌 七', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["日昳未，者回不踐光陰地。","曾聞一飽忘百饑，今日老僧身便是。","不習禪，不論義，鋪箇破席日裏睡。","想料上方兜率天，也無如此日炙背。"]', '["日昳未，者回不踐光陰地。","曾闻一飽忘百饑，今日老僧身便是。","不習禪，不論義，鋪箇破席日裏睡。","想料上方兜率天，也無如此日炙背。"]', '诗', 'shi', '', NULL, '十二時歌 七 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e3a4ac-52a2-4f74-9a0a-8f1555aff5f8', '十二時歌 八', '十二时歌 八', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["晡時申，也有燒香禮拜人。","五箇老婆三箇癭，一雙面子黑皴皴。","油麻茶，實是珍，金剛不用苦張筋。","願我來年蠶麥熟，羅㬋羅兒與一文。"]', '["晡时申，也有燒香禮拜人。","五箇老婆三箇癭，一雙面子黑皴皴。","油麻茶，實是珍，金剛不用苦張筋。","願我来年蠶麦熟，羅㬋羅兒與一文。"]', '诗', 'shi', '', NULL, '十二時歌 八 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8aeb09e-0406-4bcb-9292-f01e29285907', '十二時歌 九', '十二时歌 九', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["日入酉，除却荒涼更何守。","雲水高流定委無，歷寺沙彌鎮常有。","出格言，不到口，枉續牟尼子孫後。","一條拄杖麤楋蔾，不但登山兼打狗。","。"]', '["日入酉，除却荒涼更何守。","云水高流定委無，歷寺沙彌鎮常有。","出格言，不到口，枉續牟尼子孫後。","一條拄杖麤楋蔾，不但登山兼打狗。","。"]', '诗', 'shi', '', NULL, '十二時歌 九 從諗 shi');
